/* ---------------- builder ---------------- */
function viewBuild() {
  const c = cur();
  if (!c) { app.view = 'roster'; return viewRoster(); }
  const steps = stepsFor(c);
  const stepId = steps[clamp(app.step, 0, steps.length - 1)].id;
  const doneCount = steps.filter(s => stepDone(c, s.id)).length;
  const pct = Math.round(doneCount / steps.length * 100);
  const nav = `<div class="progress">
      <div class="lab">Step ${app.step + 1} of ${steps.length}</div>
      <div class="bar"><i style="width:${pct}%"></i></div>
    </div>` + steps.map((s, i) => `<button class="step ${i === app.step ? 'active' : ''} ${stepDone(c, s.id) ? 'done' : ''}" data-act="nav" data-step="${i}">
      <span class="num"><span>${i + 1}</span></span>${h(s.name)}</button>`).join('');

  const body = {
    system: stepSystem, identity: stepIdentity, lineage: stepLineage,
    background: stepBackground, class: stepClass, abilities: stepAbilities,
    skills: stepSkills, spells: stepSpells, advance: stepAdvance, gear: stepGear,
    flavor: stepFlavor, review: stepReview
  }[stepId](c);

  return pageBar(c, 'build') + `<div class="layout">
    <div><div class="steps">${nav}</div></div>
    <div>
      ${app.flash ? `<div class="callout">${h(app.flash)}</div>` : ''}
      ${body}
      <div class="footbar">
        <button class="btn" data-act="prev" ${app.step === 0 ? 'disabled' : ''}>← ${app.step === 0 ? 'Back' : h(steps[app.step - 1].name)}</button>
        <span class="note">Step ${app.step + 1} of ${steps.length}</span>
        ${app.step === steps.length - 1
      ? `<button class="btn primary" data-act="sheet">Finish — open the sheet</button>`
      : `<button class="btn primary" data-act="next">Next: ${h(steps[app.step + 1].name)} →</button>`}
      </div>
    </div>
    <div class="rail">${rail(c)}</div>
  </div>`;
}

/* ---------------- right rail live stats ---------------- */
function rail(c) {
  const S = sys(c.systemId);
  const d = derive(c);
  const s = c.finalScores;
  const issues = validate(c);
  const errs = issues.filter(i => i.level === 'error');
  const warns = issues.filter(i => i.level === 'warn');

  const abilRow = ABIL6.map(a => `<div class="stat"><div class="k">${a.toUpperCase()}</div>
    <div class="v">${s[a]}</div><div class="sub">${signed(mod(s[a]))}</div></div>`).join('');

  let core = '';
  if (c.systemId === '5e' || c.systemId === '5.5e') {
    core = kv([['Hit Points', d.hp], ['Hit Dice', d.hitDice], ['Armor Class', d.ac], ['Initiative', signed(d.initiative)],
    ['Speed', d.speed + ' ft.'], ['Prof. Bonus', signed(d.profBonus)], ['Passive Perception', d.passivePerception]]);
    if (d.spell) core += kv([['Spell Save DC', d.spell.dc], ['Spell Attack', signed(d.spell.attack)]]);
  } else if (c.systemId === '4e') {
    core = kv([['Hit Points', d.hp], ['Bloodied', d.bloodied], ['Healing Surges', d.surges + ' (' + d.surgeValue + ' HP)'],
    ['AC', d.ac], ['Fortitude', d.fort], ['Reflex', d.ref], ['Will', d.will],
    ['Initiative', signed(d.initiative)], ['Speed', d.speed], ['Tier', d.tier]]);
  } else if (c.systemId === 'pf1') {
    core = kv([['Hit Points', d.hp], ['AC', d.ac + ' (touch ' + d.touchAC + ', FF ' + d.flatFooted + ')'],
    ['BAB', signed(d.bab)], ['Fort / Ref / Will', signed(d.fort) + ' / ' + signed(d.ref) + ' / ' + signed(d.will)],
    ['CMB / CMD', signed(d.cmb) + ' / ' + d.cmd], ['Initiative', signed(d.initiative)], ['Speed', d.speed],
    ['Skill ranks', d.skillRanksSpent + ' / ' + d.skillRanksTotal]]);
  } else {
    core = kv([['Hit Points', d.hp], ['AC', d.ac + (d.shieldAc ? ' (' + d.shieldAc + ' shield)' : '')],
    ['Class DC', d.classDC], ['Perception', signed(d.perception) + ' (' + PROF_LABEL[d.perceptionRank] + ')'],
    ['Fort / Ref / Will', signed(d.fort) + ' / ' + signed(d.ref) + ' / ' + signed(d.will)],
    ['Speed', d.speed]]);
    if (d.spell) core += kv([['Spell DC', d.spell.dc], ['Spell attack', signed(d.spell.attack)], ['Tradition', d.spell.tradition]]);
  }
  if ((c.spells || []).length) {
    const cnt = spellCounts(c);
    core += kv([['Spells chosen', cnt.total + (cnt.prepared ? ' (' + cnt.prepared + ' prepared)' : '')]]);
  }

  return `<div class="panel">
      <h2>Live stats</h2>
      <div class="statgrid" style="margin-bottom:10px">${abilRow}</div>
      ${core}
    </div>
    <div class="panel">
      <h2>Checks <span class="hint">${errs.length} blocking</span></h2>
      ${issues.length
      ? `<ul class="issues">${errs.concat(warns).map(i => `<li class="${i.level}">${h(i.text)}</li>`).join('')}</ul>`
      : `<div class="ok">Everything checks out.</div>`}
    </div>
    ${d.notes && d.notes.length ? `<div class="panel"><h2>Rules notes</h2><ul class="issues">${d.notes.map(n => `<li class="warn">${h(n)}</li>`).join('')}</ul></div>` : ''}`;
}
function kv(pairs) {
  return pairs.map(([k, v]) => `<div class="kv"><span>${h(k)}</span><span>${h(v)}</span></div>`).join('');
}

/* ---------------- step: system ---------------- */
function stepSystem(c) {
  const untouched = !c.lineageId && !c.classId && !c.backgroundId;
  return `<div class="panel">
    <h2>Which game are you playing? <span class="hint">step one of ${stepsFor(c).length}</span></h2>
    <p class="note">${untouched
      ? 'Pick an edition and the rest of the wizard adapts to it — the right races, classes, skills, and spell lists.'
      : 'Switching systems keeps your name and level but clears race, class, background, and skills, since those don’t translate between editions.'}</p>
    <div class="cards" style="margin-top:10px">
      ${SYSTEM_ORDER.map(id => {
    const S = SYSTEMS[id];
    return `<button class="card ${c.systemId === id ? 'sel' : ''}" data-act="setsys" data-sys="${id}">
          <span class="pill">${h(S.tag)}</span><span class="t">${h(S.name)}</span>
          <span class="s">${h(S.blurb)}</span></button>`;
  }).join('')}
    </div>
    <div class="callout">${h(sysHelp(c.systemId))}</div>
    ${untouched ? `<p class="note">Currently set to <b>${h(sys(c.systemId).name)}</b>. Click a card to change it, or carry on to the next step.</p>` : ''}
  </div>`;
}
function sysHelp(id) {
  return {
    '5e': 'Ability scores come from point buy, a standard array, or rolling. Proficiency bonus scales from +2 to +6. Your race, class, and background each hand you a package of proficiencies.',
    '4e': 'Everything gets a bonus equal to half your level. Defenses are AC, Fortitude, Reflex, and Will. You pick powers rather than spells: at-will, encounter, daily, and utility.',
    'pf1': 'Skill ranks are spent individually and capped at your level; class skills get a flat +3 once you put a rank in. Base attack bonus and saves follow class progressions.',
    'pf2': 'Scores are built from boosts rather than bought: everything starts at 10, then ancestry, background, class, and four free boosts push it up. Proficiency has four ranks and your level is added to nearly every roll.'
  }[id] || '';
}

/* ---------------- step: identity ---------------- */
function stepIdentity(c) {
  const S = sys(c.systemId);
  return `<div class="panel">
    <h2>Identity</h2>
    <div class="grid2">
      <div class="field"><label>Character name</label><input data-field="name" value="${h(c.name)}" placeholder="e.g. Thoradin Emberhand"></div>
      <div class="field"><label>Player</label><input data-field="player" value="${h(c.player)}" placeholder="Your name"></div>
      <div class="field"><label>Level (1–${S.maxLevel})</label>
        <input type="number" min="1" max="${S.maxLevel}" data-field="level" data-num="1" value="${c.level}"></div>
      <div class="field"><label>${c.systemId === 'pf2' ? 'Alignment / edicts' : 'Alignment'}</label>
        <select data-field="alignment"><option value="">—</option>
        ${S.alignments.map(a => `<option ${c.alignment === a ? 'selected' : ''}>${h(a)}</option>`).join('')}</select></div>
      <div class="field"><label>Deity / patron</label><input data-field="deity" value="${h(c.deity)}" placeholder="Optional"></div>
      <div class="field"><label>Hit point method</label>
        <select data-field="hpMethod">
          <option value="average" ${c.hpMethod === 'average' ? 'selected' : ''}>Fixed average (standard)</option>
          <option value="roll" ${c.hpMethod === 'roll' ? 'selected' : ''}>Roll hit dice</option>
        </select></div>
    </div>
    ${c.hpMethod === 'roll' && c.systemId !== '4e' ? `<div class="callout">
      Rolled hit points per level after 1st: ${c.hpRolls.length ? c.hpRolls.join(', ') : 'none rolled yet'}.
      <button class="btn sm" data-act="rollhp" style="margin-left:8px">Roll for levels 2–${c.level}</button>
      <button class="btn sm ghost" data-act="clearhp">Clear</button></div>` : ''}
    ${c.systemId === '4e' ? `<div class="callout">4th Edition hit points are fixed: a starting value plus your Constitution score, then a flat amount per level. There is nothing to roll.</div>` : ''}
  </div>`;
}

/* ---------------- step: lineage ---------------- */
function stepLineage(c) {
  const S = sys(c.systemId);
  const lin = byId(S.lineages, c.lineageId);
  const sub = lin ? byId(lin.subs || [], c.lineageSubId) : null;

  const cards = S.lineages.map(l => {
    const bits = [];
    if (c.systemId === 'pf2') {
      bits.push('HP ' + l.hp, l.size, l.speed + ' ft.');
      if (l.boosts && l.boosts.length) bits.push('+' + l.boosts.map(b => b.toUpperCase()).join(' +'));
      if (l.freeBoosts) bits.push(l.freeBoosts + ' free');
      if (l.flaw) bits.push('−' + l.flaw.toUpperCase());
    } else {
      const a = l.asi || {};
      const str = Object.keys(a).map(k => signed(a[k]) + ' ' + k.toUpperCase()).join(', ');
      bits.push(str || 'flexible', l.size, l.speed + (c.systemId === '4e' ? ' sq.' : ' ft.'));
      if (l.choiceAsi) bits.push(l.choiceAsi.count + '×' + signed(l.choiceAsi.amount) + ' your choice');
    }
    return `<button class="card ${c.lineageId === l.id ? 'sel' : ''}" data-act="pick" data-field="lineageId" data-val="${l.id}">
      <span class="t">${h(l.name)}</span><span class="s">${h(bits.join(' · '))}</span></button>`;
  }).join('');

  let detail = '';
  if (lin) {
    detail = `<div class="panel"><h2>${h(lin.name)} <span class="hint">${h(lin.languages.join(', '))}${lin.extraLanguages ? ' + ' + lin.extraLanguages + ' of your choice' : ''}</span></h2>
      <ul class="traitlist">${(lin.traits || []).map(t => `<li><b>${h(t.name)}.</b> ${h(t.text)}</li>`).join('')}</ul>`;
    if ((lin.subs || []).length) {
      const label = c.systemId === 'pf2' ? 'Heritage' : c.systemId === '4e' ? 'Variant' : 'Subrace';
      detail += `<h3 style="margin-top:14px">${label}</h3><div class="cards">
        ${lin.subs.map(sb => {
        const extra = sb.asi ? Object.keys(sb.asi).map(k => signed(sb.asi[k]) + ' ' + k.toUpperCase()).join(', ') : '';
        return `<button class="card ${c.lineageSubId === sb.id ? 'sel' : ''}" data-act="pick" data-field="lineageSubId" data-val="${sb.id}">
            <span class="t">${h(sb.name)}</span><span class="s">${h(sb.note || extra || '')}${extra && sb.note ? ' · ' + h(extra) : ''}</span></button>`;
      }).join('')}</div>`;
    }
    if (lin.choice) {
      detail += `<div class="field" style="margin-top:14px"><label>${h(lin.choice.label)}</label>
        <select data-field="choices.${lin.choice.key}"><option value="">—</option>
        ${lin.choice.options.map(o => `<option ${(c.choices || {})[lin.choice.key] === o ? 'selected' : ''}>${h(o)}</option>`).join('')}</select></div>`;
    }
    // free ability picks
    if (c.systemId === 'pf2') {
      if (lin.freeBoosts) {
        detail += `<h3 style="margin-top:14px">Free ancestry boost${lin.freeBoosts > 1 ? 's' : ''}</h3>
          <div class="grid3">${Array.from({ length: lin.freeBoosts }, (_, i) => boostSelect(c, 'boosts.ancestryFree.' + i, asArray(c.boosts.ancestryFree)[i], lin.flaw ? [] : [], 'Boost ' + (i + 1))).join('')}</div>`;
      }
    } else {
      const spec = (sub && sub.choiceAsi) || lin.choiceAsi;
      if (spec) {
        detail += `<h3 style="margin-top:14px">Choose ${spec.count} ability increase${spec.count > 1 ? 's' : ''} (${signed(spec.amount)} each)</h3>
          <div class="grid3">${Array.from({ length: spec.count }, (_, i) => abilSelect(c, 'choiceAsi.' + i, asArray(c.choiceAsi)[i], spec.exclude || [], 'Increase ' + (i + 1))).join('')}</div>`;
      }
    }
    if (lin.skillBonus) {
      detail += `<div class="callout">Racial skill bonuses: ${Object.keys(lin.skillBonus).map(k => (byId(S.skills, k) || { name: k }).name + ' +' + lin.skillBonus[k]).join(', ')}.</div>`;
    }
    detail += `</div>`;
  }

  return `<div class="panel"><h2>${h(S.lineageLabel)}</h2><div class="cards">${cards}</div></div>${detail}`;
}
function abilSelect(c, path, val, exclude, label) {
  return `<div class="field"><label>${h(label)}</label><select data-field="${path}">
    <option value="">—</option>
    ${ABIL6.filter(a => !exclude.includes(a)).map(a => `<option value="${a}" ${val === a ? 'selected' : ''}>${ABIL_NAME[a]}</option>`).join('')}
  </select></div>`;
}
function boostSelect(c, path, val, exclude, label) { return abilSelect(c, path, val, exclude, label); }

/* ---------------- step: background ---------------- */
function stepBackground(c) {
  const S = sys(c.systemId);
  const bg = byId(S.backgrounds, c.backgroundId);
  const skName = id => (byId(S.skills, id) || { name: id }).name;
  const cards = S.backgrounds.map(b => {
    const bits = [];
    if (b.boosts) bits.push('+' + b.boosts.map(x => x.toUpperCase()).join(' +'));
    if (b.skills && b.skills.length) bits.push(b.skills.map(skName).join(', '));
    if (b.loreSkill) bits.push(b.loreSkill);
    if (b.feat) bits.push(b.feat);
    if (b.feature && b.feature !== '—') bits.push(b.feature);
    return `<button class="card ${c.backgroundId === b.id ? 'sel' : ''}" data-act="pick" data-field="backgroundId" data-val="${b.id}">
      <span class="t">${h(b.name)}</span><span class="s">${h(bits.join(' · '))}</span></button>`;
  }).join('');

  let detail = '';
  if (bg) {
    const rows = [];
    if (bg.boosts) rows.push(['Ability boosts', bg.boosts.map(x => ABIL_NAME[x]).join(' and ')]);
    if (bg.skills && bg.skills.length) rows.push(['Trained skill' + (bg.skills.length > 1 ? 's' : ''), bg.skills.map(skName).join(', ') + (bg.skillChoose ? ' (choose ' + bg.skillChoose + ')' : '')]);
    if (bg.loreSkill) rows.push(['Lore', bg.loreSkill]);
    if (bg.feat) rows.push(['Skill feat', bg.feat]);
    if (bg.tools && bg.tools.length) rows.push(['Tools', bg.tools.join(', ')]);
    if (bg.languages) rows.push(['Languages', bg.languages + ' of your choice']);
    if (bg.feature && bg.feature !== '—') rows.push(['Feature', bg.feature]);
    if (bg.equip && bg.equip.length) rows.push(['Equipment', bg.equip.join(', ')]);
    detail = `<div class="panel"><h2>${h(bg.name)}</h2>${kv(rows)}`;
    if (c.systemId === '4e' && bg.chooseFrom) {
      detail += `<div class="field" style="margin-top:12px"><label>Background skill benefit (+2 to this skill)</label>
        <select data-field="bgSkillBonus"><option value="">—</option>
        ${bg.chooseFrom.map(id => `<option value="${id}" ${c.bgSkillBonus === id ? 'selected' : ''}>${h(skName(id))}</option>`).join('')}</select></div>`;
    }
    detail += `</div>`;
  }
  const note = c.systemId === 'pf1'
    ? 'Pathfinder 1e uses traits rather than backgrounds. Most tables let you take two; pick the one that matters most here and note the second in Roleplay.'
    : c.systemId === '4e'
      ? 'Backgrounds are optional in 4e and grant a small benefit, usually +2 to an associated skill or adding it to your class skill list.'
      : '';
  return `<div class="panel"><h2>${h(S.backgroundLabel)}</h2>
    ${note ? `<p class="note">${h(note)}</p>` : ''}
    <div class="cards">${cards}</div></div>${detail}`;
}

/* ---------------- step: class ---------------- */
function stepClass(c) {
  const S = sys(c.systemId);
  const cls = byId(S.classes, c.classId);
  const cards = S.classes.map(cl => {
    const bits = [];
    if (c.systemId === 'pf2') { bits.push('HP ' + cl.hp + '/level', 'Key: ' + cl.keyAbility.map(k => k.toUpperCase()).join(' or ')); }
    else if (c.systemId === '4e') { bits.push(cl.role + ' · ' + cl.source, 'HP ' + cl.hpBase + ' + Con, ' + cl.hpPerLevel + '/level'); }
    else if (c.systemId === 'pf1') { bits.push('d' + cl.hitDie, cl.bab === 'full' ? 'Full BAB' : cl.bab === 'threeQuarter' ? '¾ BAB' : '½ BAB', cl.skillRanks + '+Int ranks'); }
    else { bits.push('d' + cl.hitDie + ' hit die', 'Saves: ' + cl.saves.map(x => x.toUpperCase()).join('/'), cl.skillCount + ' skills'); }
    if (cl.spellcasting) bits.push('Caster');
    return `<button class="card ${c.classId === cl.id ? 'sel' : ''}" data-act="pick" data-field="classId" data-val="${cl.id}">
      <span class="t">${h(cl.name)}</span><span class="s">${h(bits.join(' · '))}</span></button>`;
  }).join('');

  let detail = '';
  if (cls) {
    const rows = [];
    if (c.systemId === 'pf2') {
      rows.push(['Hit points', cls.hp + ' + Con per level'], ['Perception', cls.perception],
        ['Saves', 'Fort ' + cls.saves.fort + ', Ref ' + cls.saves.ref + ', Will ' + cls.saves.will],
        ['Skills', cls.skillCount + ' + Int modifier'], ['Weapons', cls.weapons],
        ['Armor', Object.keys(cls.armor).join(', ')]);
    } else if (c.systemId === '4e') {
      rows.push(['Role', cls.role], ['Power source', cls.source],
        ['Hit points', cls.hpBase + ' + Con score, +' + cls.hpPerLevel + ' per level'],
        ['Healing surges', cls.surgesBase + ' + Con modifier'],
        ['Armor', cls.armor.join(', ')], ['Weapons', cls.weapons.join(', ')],
        ['Trained skills', cls.skillCount + (cls.grantSkills ? ' (plus ' + cls.grantSkills.join(', ') + ')' : '')]);
    } else if (c.systemId === 'pf1') {
      rows.push(['Hit die', 'd' + cls.hitDie], ['Base attack', cls.bab === 'full' ? 'Full (level)' : cls.bab === 'threeQuarter' ? '¾ level' : '½ level'],
        ['Good saves', Object.keys(cls.saves).filter(k => cls.saves[k] === 'good').map(k => k.toUpperCase()).join(', ') || 'none'],
        ['Skill ranks', cls.skillRanks + ' + Int modifier per level'],
        ['Armor', cls.armor.length ? cls.armor.join(', ') : 'None'], ['Weapons', cls.weapons.join(', ')]);
      if (cls.startGold) rows.push(['Starting wealth', cls.startGold]);
    } else {
      rows.push(['Hit die', 'd' + cls.hitDie], ['Saving throws', cls.saves.map(x => ABIL_NAME[x]).join(' and ')],
        ['Armor', cls.armor.length ? cls.armor.join(', ') : 'None'], ['Weapons', cls.weapons.join(', ')],
        ['Tools', cls.tools.length ? cls.tools.join(', ') : 'None'], ['Skills', 'choose ' + cls.skillCount]);
      if (cls.spellcasting) rows.push(['Spellcasting', ABIL_NAME[cls.spellcasting.ability] + ', ' + cls.spellcasting.kind + (cls.spellcasting.prepares ? ' (prepared)' : ' (known)')]);
    }
    detail = `<div class="panel"><h2>${h(cls.name)}</h2>${kv(rows)}`;

    if (c.systemId === 'pf2' && cls.keyAbility.length > 1) {
      detail += `<div class="field" style="margin-top:12px"><label>Key ability (class boost)</label>
        <select data-field="keyAbility">${cls.keyAbility.map(k => `<option value="${k}" ${c.keyAbility === k ? 'selected' : ''}>${ABIL_NAME[k]}</option>`).join('')}</select></div>`;
    }
    if ((cls.subclasses || []).length) {
      const unlocked = c.level >= (cls.subclassLevel || 1);
      detail += `<h3 style="margin-top:14px">${h(S.subclassLabel)}${cls.subclassLevel && cls.subclassLevel > 1 ? ' <span class="tag">level ' + cls.subclassLevel + '</span>' : ''}</h3>
        ${unlocked ? '' : `<p class="note">You gain this at level ${cls.subclassLevel}. You can still plan ahead.</p>`}
        <div class="cards">${cls.subclasses.map(sb => `<button class="card ${c.subclassId === sb.id ? 'sel' : ''}" data-act="pick" data-field="subclassId" data-val="${sb.id}">
          <span class="t">${h(sb.name)}</span><span class="s">${h(sb.note || '')}</span></button>`).join('')}</div>`;
    }
    (cls.choices || []).forEach(ch => {
      detail += `<div class="field" style="margin-top:12px"><label>${h(ch.label)}</label>
        <select data-field="choices.${ch.key}"><option value="">—</option>
        ${ch.options.map(o => `<option ${(c.choices || {})[ch.key] === o ? 'selected' : ''}>${h(o)}</option>`).join('')}</select></div>`;
    });
    if (cls.choice) {
      detail += `<div class="field" style="margin-top:12px"><label>${h(cls.choice.label)}</label>
        <select data-field="choices.${cls.choice.key}"><option value="">—</option>
        ${cls.choice.options.map(o => `<option ${(c.choices || {})[cls.choice.key] === o ? 'selected' : ''}>${h(o)}</option>`).join('')}</select></div>`;
    }
    if (c.systemId === 'pf1') {
      detail += `<div class="field" style="margin-top:12px"><label>Favored class bonus (per level)</label>
        <select data-field="favoredClassBonus">
          <option value="hp" ${c.favoredClassBonus === 'hp' ? 'selected' : ''}>+1 hit point per level</option>
          <option value="skill" ${c.favoredClassBonus === 'skill' ? 'selected' : ''}>+1 skill rank per level</option>
          <option value="none" ${c.favoredClassBonus === 'none' ? 'selected' : ''}>Not my favored class</option>
        </select></div>`;
    }
    if (cls.startEquip) detail += `<div class="callout"><b>Suggested starting gear:</b> ${h(cls.startEquip.join('; '))}.</div>`;
    if (c.systemId === '4e' && cls.powers) {
      detail += `<h3 style="margin-top:12px">Level 1 powers</h3>${powerBlock(cls.powers)}`;
    }
    detail += `</div>`;
  }
  return `<div class="panel"><h2>${h(S.classLabel)}</h2><div class="cards">${cards}</div></div>${detail}`;
}
function powerBlock(p) {
  const sec = (label, arr) => arr && arr.length
    ? `<h4 style="margin:8px 0 2px;color:var(--gold2)">${label}</h4><ul class="powerlist">${arr.map(x => `<li>${h(x)}</li>`).join('')}</ul>` : '';
  return sec('At-Will', p.atwill) + sec('Encounter', p.encounter) + sec('Daily', p.daily) + sec('Level 2 Utility options', p.utility1);
}

/* ---------------- step: abilities ---------------- */
function stepAbilities(c) {
  const S = sys(c.systemId);
  const gen = S.abilityGen;
  const methods = [];
  if (gen.boosts) methods.push(['boosts', 'Boosts (standard)']);
  if (gen.pointBuy) methods.push(['pointbuy', 'Point buy']);
  if (gen.arrays && gen.arrays.length) methods.push(['array', 'Standard array']);
  if (gen.rolls && gen.rolls.length) methods.push(['roll', 'Roll dice']);
  methods.push(['manual', 'Enter manually']);

  let body = '';
  if (c.abilityMethod === 'boosts') body = uiBoosts(c);
  else if (c.abilityMethod === 'pointbuy') body = uiPointBuy(c);
  else if (c.abilityMethod === 'array') body = uiArray(c);
  else if (c.abilityMethod === 'roll') body = uiRoll(c);
  else body = uiManual(c);

  const s = c.finalScores;
  const finalRow = `<div class="abils" style="margin-top:14px">${ABIL6.map(a => {
    const parts = [];
    if (c.racialAdj && c.racialAdj[a]) parts.push(signed(c.racialAdj[a]) + ' race');
    if (c.levelAdj && c.levelAdj[a]) parts.push(signed(c.levelAdj[a]) + ' level');
    return `<div class="abil"><div class="n">${ABIL_NAME[a]}</div><div class="v">${s[a]}</div>
      <div class="m">${signed(mod(s[a]))}</div><div class="parts">${h(parts.join(' · '))}</div></div>`;
  }).join('')}</div>`;

  return `<div class="panel">
      <h2>Ability scores</h2>
      <div class="tabs">${methods.map(([id, label]) => `<button class="${c.abilityMethod === id ? 'on' : ''}" data-act="method" data-val="${id}">${h(label)}</button>`).join('')}</div>
      ${gen.note ? `<div class="callout">${h(gen.note)}</div>` : ''}
      ${body}
    </div>
    <div class="panel"><h2>Final scores <span class="hint">after every adjustment</span></h2>${finalRow}
      ${c.scoreTrace && c.scoreTrace.length ? `<div class="callout">${h(c.scoreTrace.join(' → '))}</div>` : ''}
    </div>`;
}

function uiPointBuy(c) {
  const S = sys(c.systemId);
  const pb = S.abilityGen.pointBuy;
  const budget = c.pointBudget || pb.points;
  const spent = pointBuySpend(c.baseScores, pb.table);
  const pct = clamp(Math.round(spent / budget * 100), 0, 100);
  const presets = pb.presets ? `<div class="field" style="max-width:220px"><label>Budget</label>
    <select data-field="pointBudget" data-num="1">${pb.presets.map(p => `<option value="${p.points}" ${budget === p.points ? 'selected' : ''}>${h(p.name)} — ${p.points} pts</option>`).join('')}</select></div>` : '';
  return `${presets}
    <div class="budget"><b>${spent} / ${budget}</b> points
      <div class="bar ${spent > budget ? 'over' : ''}"><i style="width:${pct}%"></i></div>
      <span class="note">range ${pb.min}–${pb.max}</span></div>
    <div class="abils">${ABIL6.map(a => {
    const v = c.baseScores[a];
    const cost = pb.table[v];
    return `<div class="abil"><div class="n">${ABIL_NAME[a]}</div><div class="v">${v}</div>
        <div class="m">${signed(mod(v))}</div>
        <div class="parts">cost ${cost === undefined ? '—' : cost}</div>
        <div class="stepper">
          <button class="btn sm" data-act="pbdec" data-abil="${a}" ${v <= pb.min ? 'disabled' : ''}>−</button>
          <button class="btn sm" data-act="pbinc" data-abil="${a}" ${v >= pb.max ? 'disabled' : ''}>+</button>
        </div></div>`;
  }).join('')}</div>
    <div style="margin-top:10px"><button class="btn sm" data-act="pbreset">Reset to ${pb.min}s</button></div>`;
}

function uiArray(c) {
  const S = sys(c.systemId);
  const arrays = S.abilityGen.arrays;
  const active = arrays.find(a => a.id === c.arrayId) || arrays[0];
  if (!c.arrayId) c.arrayId = active.id;
  const used = ABIL6.map(a => c.arrayAssign[a]).filter(x => x !== undefined && x !== null);
  return `<div class="cards" style="margin-bottom:12px">
      ${arrays.map(a => `<button class="card ${c.arrayId === a.id ? 'sel' : ''}" data-act="pickarray" data-val="${a.id}">
        <span class="t">${h(a.name)}</span><span class="s">${a.scores.join(', ')}</span></button>`).join('')}
    </div>
    <div class="pool">${active.scores.map((v, i) => `<span class="die ${used.includes(i) ? 'used' : ''}"><b>${v}</b></span>`).join('')}</div>
    <div class="abils">${ABIL6.map(a => `<div class="abil"><div class="n">${ABIL_NAME[a]}</div>
      <div class="v">${c.arrayAssign[a] !== undefined && c.arrayAssign[a] !== null ? active.scores[c.arrayAssign[a]] : '—'}</div>
      <select data-field="arrayAssign.${a}" data-num="1"><option value="">—</option>
      ${active.scores.map((v, i) => `<option value="${i}" ${c.arrayAssign[a] === i ? 'selected' : ''} ${used.includes(i) && c.arrayAssign[a] !== i ? 'disabled' : ''}>${v}</option>`).join('')}
      </select></div>`).join('')}</div>
    <div style="margin-top:10px"><button class="btn sm" data-act="autoarray">Auto-assign to class priorities</button>
      <button class="btn sm ghost" data-act="clearassign">Clear</button></div>`;
}

function uiRoll(c) {
  const S = sys(c.systemId);
  const opts = S.abilityGen.rolls;
  const used = ABIL6.map(a => c.rollAssign[a]).filter(x => x !== undefined && x !== null);
  return `<div class="grid2">
      <div class="field"><label>Method</label><select data-field="rollMethod">
        ${opts.map(o => `<option value="${o.id}" ${(c.rollMethod || opts[0].id) === o.id ? 'selected' : ''}>${h(o.name)}</option>`).join('')}
      </select></div>
      <div class="field"><label>&nbsp;</label>
        <button class="btn primary" data-act="rollscores">Roll six scores</button>
        <button class="btn" data-act="rollscores7">Roll seven, drop lowest</button></div>
    </div>
    ${(c.rolledPool || []).length ? `<div class="pool">${c.rolledPool.map((v, i) => `<span class="die ${used.includes(i) ? 'used' : ''}"><b>${v}</b>${c.rollDetail && c.rollDetail[i] ? ' <small>' + h(c.rollDetail[i]) + '</small>' : ''}</span>`).join('')}</div>
      <div class="abils">${ABIL6.map(a => `<div class="abil"><div class="n">${ABIL_NAME[a]}</div>
        <div class="v">${c.rollAssign[a] !== undefined && c.rollAssign[a] !== null ? c.rolledPool[c.rollAssign[a]] : '—'}</div>
        <select data-field="rollAssign.${a}" data-num="1"><option value="">—</option>
        ${c.rolledPool.map((v, i) => `<option value="${i}" ${c.rollAssign[a] === i ? 'selected' : ''} ${used.includes(i) && c.rollAssign[a] !== i ? 'disabled' : ''}>${v}</option>`).join('')}
        </select></div>`).join('')}</div>
      <div style="margin-top:10px"><button class="btn sm" data-act="autoroll">Auto-assign to class priorities</button>
        <button class="btn sm ghost" data-act="clearassign">Clear</button></div>`
      : `<p class="note">Roll a set, then drag the values where you want them by using the dropdowns.</p>`}`;
}

function uiManual(c) {
  const S = sys(c.systemId);
  const m = S.abilityGen.manual;
  return `<p class="note">Straight entry — useful for converting a character from elsewhere. Racial adjustments are still applied on top.</p>
    <div class="abils">${ABIL6.map(a => `<div class="abil"><div class="n">${ABIL_NAME[a]}</div>
      <input type="number" min="${m.min}" max="${m.max}" style="width:100%;text-align:center;font-size:1.3rem" data-field="baseScores.${a}" data-num="1" value="${c.baseScores[a]}">
      <div class="m">${signed(mod(c.baseScores[a]))}</div></div>`).join('')}</div>`;
}

function uiBoosts(c) {
  const S = SYS_PF2;
  const anc = byId(S.lineages, c.lineageId);
  const bg = byId(S.backgrounds, c.backgroundId);
  const cls = byId(S.classes, c.classId);
  const key = c.keyAbility || (cls ? cls.keyAbility[0] : null);
  const freeUsed = asArray(c.boosts.free).filter(Boolean);
  return `<div class="callout">Order of operations: ancestry flaw, then ancestry boosts, background, class key ability, then four free boosts. A boost is +2, or +1 if the score is already 18 or higher.</div>
    ${kv([
    ['Ancestry', anc ? ((anc.boosts || []).map(x => ABIL_NAME[x]).join(' + ') || 'two free') + (anc.flaw ? ' / flaw −2 ' + ABIL_NAME[anc.flaw] : '') : 'pick an ancestry'],
    ['Background', bg ? (bg.boosts || []).map(x => ABIL_NAME[x]).join(' + ') : 'pick a background'],
    ['Class key ability', key ? ABIL_NAME[key] : 'pick a class']
  ])}
    ${anc && anc.freeBoosts ? `<h3 style="margin-top:14px">Free ancestry boost${anc.freeBoosts > 1 ? 's' : ''}</h3>
      <div class="grid3">${Array.from({ length: anc.freeBoosts }, (_, i) => abilSelect(c, 'boosts.ancestryFree.' + i, asArray(c.boosts.ancestryFree)[i], [], 'Ancestry boost ' + (i + 1))).join('')}</div>` : ''}
    <h3 style="margin-top:14px">Four free boosts <span class="tag">must be four different abilities</span></h3>
    <div class="grid3">${Array.from({ length: 4 }, (_, i) => {
    const val = asArray(c.boosts.free)[i];
    const taken = freeUsed.filter((x, j) => j !== i);
    return `<div class="field"><label>Free boost ${i + 1}</label>
        <select data-field="boosts.free.${i}"><option value="">—</option>
        ${ABIL6.map(a => `<option value="${a}" ${val === a ? 'selected' : ''} ${taken.includes(a) ? 'disabled' : ''}>${ABIL_NAME[a]}</option>`).join('')}
        </select></div>`;
  }).join('')}</div>
    <div style="margin-top:10px"><button class="btn sm" data-act="autoboost">Suggest boosts for my class</button></div>`;
}

/* ---------------- step: skills ---------------- */
function stepSkills(c) {
  const S = sys(c.systemId);
  const d = derive(c);
  if (c.systemId === 'pf1') return skillsPf1(c, d);
  if (c.systemId === 'pf2') return skillsPf2(c, d);
  return skillsSimple(c, d);
}

function skillsSimple(c, d) {
  const S = sys(c.systemId);
  const b = skillBudget(c);
  const allowed = allowedSkillIds(c);
  const chosen = (c.skills || []).filter(s => !b.granted.includes(s));
  const cls = byId(S.classes, c.classId);
  const expWant = ((c.systemId === '5e' || c.systemId === '5.5e') && cls && cls.expertise && c.level >= cls.expertise.level)
    ? cls.expertise.count + (c.level >= 6 ? 2 : 0) : 0;

  const rows = S.skills.map(sk => {
    const info = d.skills.find(x => x.id === sk.id) || { value: 0 };
    const granted = b.granted.includes(sk.id);
    const on = (c.skills || []).includes(sk.id) || granted;
    const can = allowed.includes(sk.id) || granted;
    const exp = (c.expertise || []).includes(sk.id);
    return `<tr class="${on ? 'on' : ''}">
      <td><label class="chk"><input type="checkbox" data-act="toggleskill" data-id="${sk.id}" ${on ? 'checked' : ''} ${granted || (!can) ? 'disabled' : ''}>
        ${h(sk.name)}</label></td>
      <td class="note">${ABIL_NAME[sk.ability].slice(0, 3)}</td>
      <td>${granted ? '<span class="tag">granted</span>' : (!can ? '<span class="note">off-list</span>' : '')}</td>
      ${expWant ? `<td><input type="checkbox" data-act="toggleexp" data-id="${sk.id}" ${exp ? 'checked' : ''} ${!on ? 'disabled' : ''}></td>` : ''}
      <td class="num">${signed(info.value)}</td></tr>`;
  }).join('');

  return `<div class="panel">
    <h2>Skills <span class="hint">${chosen.length} / ${b.count} chosen${b.granted.length ? ' · ' + b.granted.length + ' granted' : ''}</span></h2>
    ${c.systemId === '4e' ? '<p class="note">4e skills are trained or untrained: trained gives a flat +5. Everything also gets half your level.</p>' : ''}
    ${expWant ? `<p class="note">Expertise doubles your proficiency bonus. You have ${expWant} pick${expWant > 1 ? 's' : ''} at level ${c.level}: ${(c.expertise || []).length} used.</p>` : ''}
    <table><thead><tr><th>Skill</th><th>Ability</th><th></th>${expWant ? '<th>Exp.</th>' : ''}<th class="num">Total</th></tr></thead>
    <tbody>${rows}</tbody></table></div>`;
}

function skillsPf1(c, d) {
  const S = SYS_PF1;
  const rows = S.skills.map(sk => {
    const info = d.skills.find(x => x.id === sk.id) || { value: 0, classSkill: false, detail: '' };
    const r = (c.ranks && c.ranks[sk.id]) || 0;
    return `<tr class="${r ? 'on' : ''}">
      <td>${h(sk.name)}${sk.trainedOnly ? ' <span class="tag">trained only</span>' : ''}</td>
      <td class="note">${ABIL_NAME[sk.ability].slice(0, 3)}</td>
      <td>${info.classSkill ? '<span class="tag">class skill</span>' : ''}</td>
      <td class="skillrow"><input type="number" min="0" max="${c.level}" value="${r}" data-act="setrank" data-id="${sk.id}"></td>
      <td class="note">${h(info.detail)}</td>
      <td class="num">${signed(info.value)}</td></tr>`;
  }).join('');
  const over = d.skillRanksSpent > d.skillRanksTotal;
  const pct = clamp(Math.round(d.skillRanksSpent / Math.max(1, d.skillRanksTotal) * 100), 0, 100);
  return `<div class="panel">
    <h2>Skill ranks</h2>
    <div class="budget"><b>${d.skillRanksSpent} / ${d.skillRanksTotal}</b> ranks
      <div class="bar ${over ? 'over' : ''}"><i style="width:${pct}%"></i></div>
      <span class="note">${d.skillRanksPerLevel} per level × ${c.level} levels · max ${c.level} ranks in any one skill</span></div>
    <table><thead><tr><th>Skill</th><th>Ability</th><th></th><th>Ranks</th><th>Breakdown</th><th class="num">Total</th></tr></thead>
    <tbody>${rows}</tbody></table>
    <div style="margin-top:10px"><button class="btn sm ghost" data-act="clearranks">Clear all ranks</button></div></div>`;
}

function skillsPf2(c, d) {
  const S = SYS_PF2;
  const ranks = ['untrained', 'trained', 'expert', 'master', 'legendary'];
  const maxRank = c.level >= 15 ? 'legendary' : c.level >= 7 ? 'master' : c.level >= 3 ? 'expert' : 'trained';
  const maxIdx = ranks.indexOf(maxRank);
  const trained = Object.keys(c.profs || {}).filter(k => c.profs[k] && c.profs[k] !== 'untrained').length;
  const cls = byId(S.classes, c.classId);
  const expected = (cls ? cls.skillCount : 2) + Math.max(0, mod(c.finalScores.int)) + ((byId(S.backgrounds, c.backgroundId) || {}).skills || []).length;
  const rows = S.skills.map(sk => {
    const info = d.skills.find(x => x.id === sk.id) || { value: 0 };
    const r = (c.profs && c.profs[sk.id]) || 'untrained';
    return `<tr class="${r !== 'untrained' ? 'on' : ''}">
      <td>${h(sk.name)}</td><td class="note">${ABIL_NAME[sk.ability].slice(0, 3)}</td>
      <td><select data-act="setprof" data-id="${sk.id}">
        ${ranks.slice(0, maxIdx + 1).map(x => `<option value="${x}" ${r === x ? 'selected' : ''}>${x}</option>`).join('')}
      </select></td>
      <td class="note">${h(info.detail || '')}</td>
      <td class="num">${signed(info.value)}</td></tr>`;
  }).join('');
  return `<div class="panel">
    <h2>Skill proficiencies <span class="hint">${trained} trained · about ${expected} expected at level 1</span></h2>
    <p class="note">Untrained skills get no level bonus at all in PF2 — that is the big difference from 5e. Skill increases at levels ${S.skillIncreaseLevels.join(', ')} let you push a skill to expert, then master at 7th and legendary at 15th. You have ${d.skillIncreases} increase${d.skillIncreases === 1 ? '' : 's'} so far.</p>
    <table><thead><tr><th>Skill</th><th>Ability</th><th>Rank</th><th>Breakdown</th><th class="num">Total</th></tr></thead>
    <tbody>${rows}</tbody></table>
    <div style="margin-top:10px"><button class="btn sm ghost" data-act="clearprofs">Reset all to untrained</button></div></div>`;
}

/* ---------------- step: advancement ---------------- */
function stepAdvance(c) {
  const S = sys(c.systemId);
  const cls = byId(S.classes, c.classId);
  const d = derive(c);

  let asiUI = '';
  if (c.systemId === '5e' && cls) {
    const levels = cls.asiLevels.filter(l => l <= c.level);
    asiUI = levels.length ? levels.map(l => `<div class="panel" style="background:var(--bg2)">
      <h3>Level ${l} — Ability Score Improvement</h3>
      <p class="note">+2 to one ability, or +1 to two. Leave blank if you took a feat instead.</p>
      <div class="grid3">${[0, 1].map(i => abilSelect(c, 'levelAsi.' + l + '.' + i, asArray(c.levelAsi[l])[i], [], 'Increase ' + (i + 1))).join('')}
        <div class="field"><label>Feat taken instead</label><input data-field="choices.feat${l}" value="${h((c.choices || {})['feat' + l] || '')}" placeholder="e.g. Sharpshooter"></div></div>
    </div>`).join('') : '<p class="note">No ability score improvements yet — your first is at level ' + cls.asiLevels[0] + '.</p>';
  } else if (c.systemId === '5.5e' && cls) {
    const levels = cls.asiLevels.filter(l => l <= c.level);
    asiUI = levels.length ? levels.map(l => `<div class="panel" style="background:var(--bg2)">
      <h3>Level ${l} — Ability Score Improvement</h3>
      <p class="note">+2 to one ability, or +1 to two. Leave blank if you took a feat instead.</p>
      <div class="grid3">${[0, 1].map(i => abilSelect(c, 'levelAsi.' + l + '.' + i, asArray(c.levelAsi[l])[i], [], 'Increase ' + (i + 1))).join('')}
        <div class="field"><label>Feat taken instead</label><input data-field="choices.feat${l}" value="${h((c.choices || {})['feat' + l] || '')}" placeholder="e.g. Sharpshooter"></div></div>
    </div>`).join('') : '<p class="note">No ability score improvements yet — your first is at level ' + cls.asiLevels[0] + '.</p>';
  } else if (c.systemId === 'pf1') {
    const levels = [4, 8, 12, 16, 20].filter(l => l <= c.level);
    asiUI = levels.length ? levels.map(l => `<div class="panel" style="background:var(--bg2)">
      <h3>Level ${l} — +1 ability score</h3>
      <div class="grid3">${abilSelect(c, 'levelAsi.' + l + '.0', asArray(c.levelAsi[l])[0], [], 'Increase')}</div></div>`).join('')
      : '<p class="note">Ability increases come at levels 4, 8, 12, 16, and 20.</p>';
  } else if (c.systemId === 'pf2') {
    const levels = [5, 10, 15, 20].filter(l => l <= c.level);
    asiUI = levels.length ? levels.map(l => {
      const cur = asArray((c.boosts.levels || {})[l]);
      return `<div class="panel" style="background:var(--bg2)"><h3>Level ${l} — four ability boosts</h3>
        <div class="grid3">${Array.from({ length: 4 }, (_, i) => {
        const taken = cur.filter((x, j) => j !== i && x);
        return `<div class="field"><label>Boost ${i + 1}</label>
            <select data-field="boosts.levels.${l}.${i}"><option value="">—</option>
            ${ABIL6.map(a => `<option value="${a}" ${cur[i] === a ? 'selected' : ''} ${taken.includes(a) ? 'disabled' : ''}>${ABIL_NAME[a]}</option>`).join('')}
            </select></div>`;
      }).join('')}</div></div>`;
    }).join('') : '<p class="note">Ability boosts arrive at levels 5, 10, 15, and 20.</p>';
  } else {
    asiUI = `<p class="note">4th Edition raises abilities on a fixed schedule: +1 to two abilities at 11th, 14th, 18th, 21st, 24th, and 28th, and +1 to four abilities at 4th, 8th, 14th, 18th, 24th, and 28th. Track those on the Abilities step using manual entry if you are above level 3.</p>`;
  }

  const featCount = c.systemId === 'pf2'
    ? Object.keys(d.featCounts || {}).map(k => `<div class="kv"><span>${h(k)}</span><span>${d.featCounts[k]}</span></div>`).join('')
    : kv([['Feats', d.featCount || 0]].concat(d.bonusCombatFeats ? [['Bonus combat feats', d.bonusCombatFeats]] : []));

  return `<div class="panel">
      <h2>Level & advancement</h2>
      <div class="grid2">
        <div class="field"><label>Current level</label>
          <input type="number" min="1" max="${S.maxLevel}" data-field="level" data-num="1" value="${c.level}"></div>
        <div class="field"><label>Quick level up</label>
          <button class="btn primary" data-act="levelup" ${c.level >= S.maxLevel ? 'disabled' : ''}>Gain a level →</button></div>
      </div>
      ${app.levelUpLog.length ? `<div class="callout"><b>Just gained:</b><ul class="powerlist">${app.levelUpLog.map(g => `<li>Level ${g.level}: ${h(g.text)}</li>`).join('')}</ul></div>` : ''}
      ${featCount}
    </div>
    <div class="panel"><h2>Ability increases</h2>${asiUI}</div>
    <div class="panel"><h2>Features gained so far <span class="hint">${d.features.length} entries</span></h2>
      ${d.features.length ? `<table><thead><tr><th>Lvl</th><th>Feature</th></tr></thead><tbody>
        ${d.features.map(f => `<tr><td class="num">${f.level}</td><td>${h(f.text)}</td></tr>`).join('')}</tbody></table>`
      : '<p class="note">Pick a class to see its features.</p>'}
    </div>
    ${c.systemId === '4e' && d.powersKnown ? `<div class="panel"><h2>Powers known</h2>${kv(Object.keys(d.powersKnown).map(k => [k, d.powersKnown[k]]))}</div>` : ''}
    ${c.systemId === 'pf2' && d.spell ? `<div class="panel"><h2>Spellcasting</h2>${kv([['Tradition', d.spell.tradition], ['Type', d.spell.kind], ['Proficiency', d.spell.rank], ['Highest rank', d.spell.maxRank], ['Slots', d.spell.slotsPerRank], ['Cantrips', d.spell.cantrips]])}</div>` : ''}
    ${(c.systemId === '5e' || c.systemId === '5.5e' || c.systemId === 'pf1') && d.spell ? `<div class="panel"><h2>Spellcasting</h2>${spellPanel(c, d)}</div>` : ''}
    <div class="panel"><h2>Feat and option notes</h2>
      <p class="note">Type whatever you picked; there is no validation here, so homebrew and third-party options are fine.</p>
      <textarea data-field="notes" placeholder="Feats, invocations, rage powers, discoveries, metamagic, item choices...">${h(c.notes)}</textarea>
      <div class="callout"><b>Common ${h(S.name)} options:</b> ${h((S.feats || []).slice(0, 14).join(', '))}…</div>
    </div>`;
}

function spellPanel(c, d) {
  if (!d.spell) return '';
  if (c.systemId === '5e' || c.systemId === '5.5e') {
    const rows = [['Ability', d.spell.ability], ['Save DC', d.spell.dc], ['Attack bonus', signed(d.spell.attack)]];
    if (d.spell.cantrips) rows.push(['Cantrips known', d.spell.cantrips]);
    if (d.spell.prepared) rows.push(['Spells prepared', d.spell.prepared]);
    if (d.spell.note) rows.push(['Pact magic', d.spell.note]);
    if (d.spell.slots && d.spell.slots.length) rows.push(['Slots', d.spell.slots.map((n, i) => (i + 1) + 'st:' + n).join('  ')]);
    return kv(rows);
  }
  const rows = [['Ability', d.spell.ability], ['Type', d.spell.kind], ['Caster level', d.spell.casterLevel],
  ['Highest spell level', d.spell.maxSpellLevel || 'none yet'], ['Concentration', signed(d.spell.concentration)],
  ['Base save DC', d.spell.saveDCbase + ' + spell level']];
  const bs = Object.keys(d.spell.bonusSlots || {});
  if (bs.length) rows.push(['Bonus slots', bs.map(k => 'lvl ' + k + ': +' + d.spell.bonusSlots[k]).join(', ')]);
  return kv(rows);
}

/* ---------------- step: gear ---------------- */
function stepGear(c) {
  const S = sys(c.systemId);
  const d = derive(c);
  const armors = S.armorList || [];
  let shieldUI = '';
  if (c.systemId === '5e' || c.systemId === '5.5e') {
    shieldUI = `<label class="chk"><input type="checkbox" data-act="toggleshield" ${c.shield ? 'checked' : ''}> Carrying a shield (+2 AC)</label>`;
  } else if (c.systemId === '4e') {
    shieldUI = `<div class="field"><label>Shield</label><select data-field="shield4e">
      ${S.shields.map(s => `<option ${c.shield4e === s.name ? 'selected' : ''}>${h(s.name)}</option>`).join('')}</select></div>`;
  } else if (c.systemId === 'pf1') {
    shieldUI = `<div class="field"><label>Shield</label><select data-field="shieldPf">
      ${S.shields.map(s => `<option ${c.shieldPf === s.name ? 'selected' : ''}>${h(s.name)}</option>`).join('')}</select></div>`;
  } else {
    shieldUI = `<div class="field"><label>Shield</label><select data-field="shieldPf2">
      ${S.shields.map(s => `<option ${c.shieldPf2 === s.name ? 'selected' : ''}>${h(s.name)}</option>`).join('')}</select></div>`;
  }

  return `<div class="panel">
      <h2>Armor & defense</h2>
      <div class="grid2">
        <div class="field"><label>Armor worn</label><select data-field="armor">
          ${armors.map(a => `<option ${(c.armor || armors[0].name) === a.name ? 'selected' : ''}>${h(a.name)}</option>`).join('')}
        </select></div>
        <div>${shieldUI}</div>
        <div class="field"><label>Misc. AC bonus (rings, magic, cover)</label>
          <input type="number" data-field="acBonus" data-num="1" value="${c.acBonus || 0}"></div>
        ${c.systemId === '4e' ? `<div class="field"><label>Weapon proficiency bonus</label>
          <input type="number" data-field="weaponProf" data-num="1" value="${c.weaponProf || 0}"></div>` : ''}
        ${c.systemId === 'pf1' ? `<div class="field"><label>Misc. initiative bonus</label>
          <input type="number" data-field="initBonus" data-num="1" value="${c.initBonus || 0}"></div>` : ''}
      </div>
      ${kv(defenseRows(c, d))}
    </div>
    <div class="panel"><h2>Equipment & wealth</h2>
      <div class="grid2">
        <div class="field"><label>Money</label><input data-field="gold" value="${h(c.gold)}" placeholder="e.g. 47 gp, 3 sp"></div>
        <div class="field"><label>Carrying capacity</label>
          <input value="${d.carry ? d.carry.carry + ' lb (push/drag ' + d.carry.push + ')' : (d.bulkLimit || '—')}" disabled></div>
      </div>
      <label>Gear, weapons, and magic items</label>
      <textarea data-field="gear" style="min-height:130px" placeholder="One item per line...">${h(c.gear)}</textarea>
      ${(byId(S.classes, c.classId) || {}).startEquip ? `<div class="callout"><b>Class starting kit:</b> ${h(byId(S.classes, c.classId).startEquip.join('; '))}.
        <button class="btn sm" data-act="fillgear" style="margin-left:8px">Copy into gear list</button></div>` : ''}
    </div>
    <div class="panel"><h2>Languages</h2>
      <div class="cards">${(S.languages || []).map(l => `<button class="card ${(c.languages || []).includes(l) ? 'sel' : ''}" data-act="togglelang" data-val="${h(l)}" style="padding:6px 9px">
        <span class="t" style="font-size:.9rem">${h(l)}</span></button>`).join('')}</div>
    </div>`;
}
function defenseRows(c, d) {
  if (c.systemId === '4e') return d.defenses.map(x => [x.name, x.value + (x.note ? '  (' + x.note + ')' : '')]);
  if (c.systemId === 'pf1') return [['AC', d.ac], ['Touch AC', d.touchAC], ['Flat-footed AC', d.flatFooted], ['Armor check penalty', d.acp], ['CMD', d.cmd]];
  if (c.systemId === 'pf2') return [['AC', d.ac], ['AC with shield raised', d.shieldAc || d.ac], ['Fortitude', d.fort], ['Reflex', d.ref], ['Will', d.will]];
  return [['AC', d.ac + ' (' + d.acNote + ')'], ['Initiative', signed(d.initiative)], ['Passive Perception', d.passivePerception], ['Speed', d.speed + ' ft.']];
}

/* ---------------- step: flavor ---------------- */
function stepFlavor(c) {
  const p = c.personality || {};
  const a = c.appearance || {};
  return `<div class="panel"><h2>Appearance</h2>
      <div class="grid3">
        ${['age', 'height', 'weight', 'eyes', 'hair', 'skin'].map(k =>
    `<div class="field"><label>${k}</label><input data-field="appearance.${k}" value="${h(a[k] || '')}"></div>`).join('')}
      </div></div>
    <div class="panel"><h2>Personality</h2>
      ${[['traits', 'Personality traits'], ['ideals', 'Ideals'], ['bonds', 'Bonds'], ['flaws', 'Flaws']].map(([k, label]) =>
      `<div class="field"><label>${label}</label><textarea data-field="personality.${k}" style="min-height:56px">${h(p[k] || '')}</textarea></div>`).join('')}
    </div>
    <div class="panel"><h2>Backstory</h2>
      <textarea data-field="personality.backstory" style="min-height:180px" placeholder="Where they came from, what they want, who they owe...">${h(p.backstory || '')}</textarea>
    </div>`;
}

/* ---------------- step: review ---------------- */
function stepReview(c) {
  const S = sys(c.systemId);
  const d = derive(c);
  const issues = validate(c);
  const errs = issues.filter(i => i.level === 'error');
  const lin = byId(S.lineages, c.lineageId);
  const cls = byId(S.classes, c.classId);
  return `<div class="panel">
      <h2>Review</h2>
      <p class="note">${h(c.name || 'Unnamed')} — level ${c.level} ${h(lin ? lin.name : '?')} ${h(cls ? cls.name : '?')} (${h(S.name)})</p>
      ${errs.length
      ? `<div class="callout" style="border-color:var(--red)"><b>${errs.length} thing${errs.length > 1 ? 's' : ''} still need attention:</b>
          <ul class="powerlist">${errs.map(i => `<li>${h(i.text)}</li>`).join('')}</ul>
          You can still print the sheet — these are reminders, not locks.</div>`
      : `<div class="callout" style="border-color:var(--green)">No blocking problems found. Ready to play.</div>`}
      <div class="footbar" style="justify-content:flex-start">
        <button class="btn primary" data-act="sheet">Open character sheet</button>
        <button class="btn" data-act="print">Print / save as PDF</button>
        <button class="btn" data-act="export">Export JSON</button>
      </div>
    </div>
    ${d.features.length ? `<div class="panel"><h2>Everything you have</h2>
      <table><thead><tr><th>Lvl</th><th>Feature</th></tr></thead><tbody>
      ${d.features.map(f => `<tr><td class="num">${f.level}</td><td>${h(f.text)}</td></tr>`).join('')}</tbody></table></div>` : ''}`;
}

/* The character sheet and play tracking live in 90-play.js and 91-sheet.js. */

/* ============================================================
   Event handling
   ============================================================ */
function autoAssignPriority(c) {
  const S = sys(c.systemId);
  const cls = byId(S.classes, c.classId);
  const prim = cls ? (cls.primary || cls.keyAbility || ['str']) : ['str'];
  const rest = ABIL6.filter(a => !prim.includes(a));
  const order = prim.concat(['con'].filter(a => !prim.includes(a))).concat(rest.filter(a => a !== 'con'));
  return [...new Set(order)];
}

document.addEventListener('click', function (ev) {
  const el = ev.target.closest('[data-act]');
  if (!el) return;
  // Stop the backdrop-close from firing when a click lands inside the dialog
  if (el.dataset.act === 'levelclose' && ev.target.closest('[data-stop]') && ev.target !== el) return;
  const act = el.dataset.act;
  const c = cur();
  app.flash = '';

  switch (act) {
    // "Create a character" — start the guided wizard at step one
    case 'create': case 'new': case 'newsys': {
      const sid = el.dataset.sys || '5e';
      const ch = blankCharacter(sid);
      app.roster.push(ch);
      app.currentId = ch.id;
      resetAllPanels();
      app.view = 'build';
      // a named system means the caller already chose one, so skip that step
      app.step = el.dataset.sys ? 1 : 0;
      persist(); render(); return;
    }
    // opening a character shows the character, not the wizard
    case 'open': case 'opensheet': {
      app.currentId = el.dataset.id || app.currentId;
      resetAllPanels();
      app.view = 'sheet';
      render(); return;
    }
    // "Modify character" drops into the wizard where you last left it
    case 'modify': case 'build': {
      if (el.dataset.id && el.dataset.id !== app.currentId) {
        app.currentId = el.dataset.id;
        resetAllPanels();
      }
      const ch = cur();
      if (!ch) return;
      app.view = 'build';
      app.step = clamp(Number(ch.wizardStep) || 1, 0, stepsFor(ch).length - 1);
      render(); return;
    }
    case 'dup': {
      const src = app.roster.find(x => x.id === el.dataset.id);
      if (src) {
        const copy = JSON.parse(JSON.stringify(src));
        copy.id = uid(); copy.name = (src.name || 'Character') + ' (copy)';
        app.roster.push(copy); persist(); render();
      } return;
    }
    case 'del': {
      const src = app.roster.find(x => x.id === el.dataset.id);
      if (src && confirm('Delete ' + (src.name || 'this character') + '? This cannot be undone.')) {
        app.roster = app.roster.filter(x => x.id !== src.id);
        if (app.currentId === src.id) { app.currentId = null; app.view = 'roster'; }
        persist();
        if (isConnected()) storeDelete(src.id);
        render();
      } return;
    }
    case 'home': {
      app.currentId = null;
      app.guest = null;
      app.preview = null;
      app.role = null;
      pruneBlank();
      app.view = 'home'; render(); return;
    }
    case 'roster': {
      // drop a character the user created but never touched
      app.currentId = null;
      app.guest = null;
      app.preview = null;
      pruneBlank();
      app.view = 'roster'; render(); return;
    }
    case 'homeplayer': {
      app.role = 'player';
      app.view = 'roster'; render(); return;
    }
    case 'homedm': {
      app.role = 'dm';
      const dmCamps = campaignList().filter(camp => camp.yourRole === 'dm');
      if (dmCamps.length === 1) { openCampaign(dmCamps[0].id); return; }
      // no campaign yet: show DM landing so they can create one
      campUI.creating = true;
      app.view = 'dm'; render(); return;
    }
    case 'sheet': app.view = 'sheet'; render(); return;
    case 'sheetpanel': app.view = el.dataset.panel; render(); return;
    case 'levelmodal': levelUI.open = true; levelUI.done = false; levelUI.from = cur() ? cur().level : 0; render(); return;
    case 'levelclose': levelUI.open = false; levelUI.done = false; render(); return;
    case 'levelgo': {
      const lc = cur();
      if (!lc) return;
      const was = lc.level;
      app.levelUpLog = levelUp(lc, lc.level + 1);
      logHistory(lc, 'Reached level ' + lc.level + (app.levelUpLog.length ? ' \u2014 ' + app.levelUpLog.map(g => g.text).join('; ') : ''));
      if (lc.level > was && typeof autoJournal === 'function') {
        autoJournal(lc, 'level', 'Reached level ' + lc.level, 'Went up from level ' + was + '.');
      }
      levelUI.done = true;
      persist(); render(); return;
    }
    case 'print': window.print(); return;
    case 'export': doExport(c); return;
    case 'import': doImport(); return;
    case 'nav': app.step = Number(el.dataset.step); rememberStep(c); render(); return;
    case 'next': app.step = clamp(app.step + 1, 0, stepsFor(c).length - 1); rememberStep(c); render(); return;
    case 'prev': app.step = clamp(app.step - 1, 0, stepsFor(c).length - 1); rememberStep(c); render(); return;

    case 'setsys': {
      const sid = el.dataset.sys;
      const untouched = !c.lineageId && !c.classId && !c.backgroundId && !(c.spells || []).length;
      if (sid === c.systemId) return;
      // nothing to lose on an untouched character, so don't nag
      if (!untouched && !confirm('Switch to ' + sys(sid).name + '? Race, class, background, skills, and ability assignments will be cleared.')) return;
      const keep = { id: c.id, name: c.name, player: c.player, level: 1, notes: c.notes, gear: c.gear, gold: c.gold, personality: c.personality, appearance: c.appearance, created: c.created };
      const swapped = blankCharacter(sid);
      Object.assign(swapped, keep);
      swapped.systemId = sid;
      const i = app.roster.findIndex(x => x.id === c.id);
      app.roster[i] = swapped;
      resetAllPanels();
      if (!untouched) app.flash = 'Switched to ' + sys(sid).name + '.';
      persist(); render(); return;
    }
    case 'pick': {
      const f = el.dataset.field, v = el.dataset.val;
      if (c[f] === v && (f === 'lineageSubId' || f === 'subclassId')) c[f] = null;
      else c[f] = v;
      if (f === 'lineageId') { c.lineageSubId = null; c.choiceAsi = []; if (c.boosts) c.boosts.ancestryFree = []; syncGranted(c); }
      if (f === 'classId') {
        c.subclassId = null; c.choices = {};
        const cls = byId(sys(c.systemId).classes, c.classId);
        if (cls && cls.keyAbility) c.keyAbility = cls.keyAbility[0];
        c.skills = []; c.expertise = [];
        c.spells = []; c.prepared = [];   // spell lists are class-specific
        resetAllPanels();
        syncGranted(c);
      }
      if (f === 'backgroundId') syncGranted(c);
      persist(); render(); return;
    }
    case 'method': c.abilityMethod = el.dataset.val; persist(); render(); return;
    case 'pbinc': case 'pbdec': {
      const pb = sys(c.systemId).abilityGen.pointBuy;
      const a = el.dataset.abil;
      c.baseScores[a] = clamp(c.baseScores[a] + (act === 'pbinc' ? 1 : -1), pb.min, pb.max);
      persist(); render(); return;
    }
    case 'pbreset': {
      const pb = sys(c.systemId).abilityGen.pointBuy;
      ABIL6.forEach(a => c.baseScores[a] = pb.min);
      persist(); render(); return;
    }
    case 'pickarray': c.arrayId = el.dataset.val; c.arrayAssign = {}; persist(); render(); return;
    case 'clearassign': c.arrayAssign = {}; c.rollAssign = {}; persist(); render(); return;
    case 'autoarray': {
      const S = sys(c.systemId);
      const arr = (S.abilityGen.arrays || []).find(a => a.id === c.arrayId) || S.abilityGen.arrays[0];
      const order = autoAssignPriority(c);
      const idxs = arr.scores.map((v, i) => i).sort((x, y) => arr.scores[y] - arr.scores[x]);
      c.arrayAssign = {};
      order.forEach((a, i) => { if (idxs[i] !== undefined) c.arrayAssign[a] = idxs[i]; });
      persist(); render(); return;
    }
    case 'autoroll': {
      const order = autoAssignPriority(c);
      const idxs = c.rolledPool.map((v, i) => i).sort((x, y) => c.rolledPool[y] - c.rolledPool[x]);
      c.rollAssign = {};
      order.forEach((a, i) => { if (idxs[i] !== undefined) c.rollAssign[a] = idxs[i]; });
      persist(); render(); return;
    }
    case 'rollscores': case 'rollscores7': {
      const S = sys(c.systemId);
      const method = (S.abilityGen.rolls || []).find(r => r.id === (c.rollMethod || S.abilityGen.rolls[0].id)) || S.abilityGen.rolls[0];
      const n = act === 'rollscores7' ? 7 : 6;
      const res = Array.from({ length: n }, () => method.fn());
      res.sort((a, b) => b.total - a.total);
      const keep = res.slice(0, 6);
      c.rolledPool = keep.map(r => r.total);
      c.rollDetail = keep.map(r => '(' + r.dice.join(',') + (r.dropped ? ' drop ' + r.dropped : '') + ')');
      c.rollAssign = {};
      app.flash = 'Rolled ' + c.rolledPool.join(', ') + ' — total ' + sum(c.rolledPool) + '.';
      persist(); render(); return;
    }
    case 'autoboost': {
      const order = autoAssignPriority(c);
      const anc = byId(SYS_PF2.lineages, c.lineageId);
      const already = [].concat(anc ? (anc.boosts || []) : [], (byId(SYS_PF2.backgrounds, c.backgroundId) || {}).boosts || [], [c.keyAbility]).filter(Boolean);
      const free = order.filter(a => !already.includes(a)).slice(0, 4);
      while (free.length < 4) { const extra = ABIL6.find(a => !free.includes(a)); if (!extra) break; free.push(extra); }
      c.boosts.free = free;
      if (anc && anc.freeBoosts) c.boosts.ancestryFree = order.filter(a => a !== anc.flaw).slice(0, anc.freeBoosts);
      persist(); render(); return;
    }
    case 'toggleskill': {
      const id = el.dataset.id;
      c.skills = c.skills || [];
      if (c.skills.includes(id)) { c.skills = c.skills.filter(x => x !== id); c.expertise = (c.expertise || []).filter(x => x !== id); }
      else c.skills.push(id);
      persist(); render(); return;
    }
    case 'toggleexp': {
      const id = el.dataset.id;
      c.expertise = c.expertise || [];
      if (c.expertise.includes(id)) c.expertise = c.expertise.filter(x => x !== id);
      else c.expertise.push(id);
      persist(); render(); return;
    }
    case 'clearranks': c.ranks = {}; persist(); render(); return;
    case 'clearprofs': c.profs = {}; syncGranted(c); persist(); render(); return;
    case 'toggleshield': c.shield = !c.shield; persist(); render(); return;
    case 'togglelang': {
      const v = el.dataset.val;
      c.languages = c.languages || [];
      c.languages = c.languages.includes(v) ? c.languages.filter(x => x !== v) : c.languages.concat(v);
      persist(); render(); return;
    }
    case 'fillgear': {
      const cls = byId(sys(c.systemId).classes, c.classId);
      const bg = byId(sys(c.systemId).backgrounds, c.backgroundId);
      const lines = [].concat(cls ? cls.startEquip || [] : [], bg ? bg.equip || [] : []);
      c.gear = (c.gear ? c.gear + '\n' : '') + lines.join('\n');
      persist(); render(); return;
    }
    case 'levelup': {
      const was = c.level;
      app.levelUpLog = levelUp(c, c.level + 1);
      if (c.level > was) {
        autoJournal(c, 'level', 'Reached level ' + c.level,
          'Went up from level ' + was + '.');
      }
      persist(); render(); return;
    }
    case 'rollhp': {
      const cls = byId(sys(c.systemId).classes, c.classId);
      const hd = cls ? cls.hitDie : 8;
      c.hpRolls = Array.from({ length: Math.max(0, c.level - 1) }, () => d(hd));
      app.flash = 'Rolled ' + c.hpRolls.join(', ') + ' on d' + hd + '.';
      persist(); render(); return;
    }
    case 'clearhp': c.hpRolls = []; persist(); render(); return;
  }
});

/* inputs */
document.addEventListener('input', onFieldChange);
document.addEventListener('change', onFieldChange);
function onFieldChange(ev) {
  const el = ev.target;
  const c = cur();
  if (!c) return;

  if (el.dataset.act === 'setrank') {
    const id = el.dataset.id;
    c.ranks = c.ranks || {};
    c.ranks[id] = clamp(Number(el.value) || 0, 0, c.level);
    persist();
    if (ev.type === 'change') render(); else refreshRail();
    return;
  }
  if (el.dataset.act === 'setprof') {
    c.profs = c.profs || {};
    c.profs[el.dataset.id] = el.value;
    persist(); render(); return;
  }
  const f = el.dataset.field;
  if (!f) return;
  let v = el.type === 'checkbox' ? el.checked : el.value;
  if (el.dataset.num) v = v === '' ? null : Number(v);
  if (f === 'level') {
    v = clamp(Number(v) || 1, 1, sys(c.systemId).maxLevel);
    if (c.hpMethod === 'roll') {
      const cls = byId(sys(c.systemId).classes, c.classId);
      const hd = cls ? cls.hitDie : 8;
      while (c.hpRolls.length < v - 1) c.hpRolls.push(d(hd));
      c.hpRolls = c.hpRolls.slice(0, Math.max(0, v - 1));
    }
  }
  setPath(c, f, v);
  if (f === 'armor' || f.startsWith('boosts') || f.startsWith('choiceAsi') || f.startsWith('levelAsi')
    || f === 'keyAbility' || f === 'level' || f === 'hpMethod' || f === 'abilityMethod'
    || f.startsWith('arrayAssign') || f.startsWith('rollAssign') || f === 'favoredClassBonus'
    || f === 'bgSkillBonus' || f === 'pointBudget' || f.startsWith('shield')) {
    persist();
    if (ev.type === 'change') { render(); return; }
  }
  persist();
  refreshRail();
}
function refreshRail() {
  const c = cur();
  if (!c || app.view !== 'build') return;
  const railEl = document.querySelector('.rail');
  if (railEl) railEl.innerHTML = rail(c);
}

/* granted skills sync */
function syncGranted(c) {
  const S = sys(c.systemId);
  const b = skillBudget(c);
  if (c.systemId === 'pf2') {
    c.profs = c.profs || {};
    b.granted.forEach(id => { if (!c.profs[id] || c.profs[id] === 'untrained') c.profs[id] = 'trained'; });
    const cls = byId(S.classes, c.classId);
    if (cls && cls.grantSkills) cls.grantSkills.forEach(id => { if (!c.profs[id] || c.profs[id] === 'untrained') c.profs[id] = 'trained'; });
    return;
  }
  if (c.systemId === 'pf1') return;
  c.skills = [...new Set((c.skills || []).concat(b.granted))];
}

/* import / export */
function doExport(c) {
  if (!c) return;
  const data = JSON.stringify(c, null, 2);
  const blob = new Blob([data], { type: 'application/json' });
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  const safe = (c.name || 'character').replace(/[^a-z0-9]+/gi, '-').toLowerCase();
  a.download = safe + '-' + c.systemId + '.json';
  document.body.appendChild(a); a.click(); a.remove();
  setTimeout(() => URL.revokeObjectURL(a.href), 1000);
}
function doImport() {
  const inp = document.createElement('input');
  inp.type = 'file'; inp.accept = '.json,application/json';
  inp.onchange = () => {
    const file = inp.files[0];
    if (!file) return;
    const fr = new FileReader();
    fr.onload = () => {
      try {
        const obj = JSON.parse(fr.result);
        const list = Array.isArray(obj) ? obj : [obj];
        let added = 0;
        list.forEach(o => {
          if (!o || !o.systemId || !SYSTEMS[o.systemId]) return;
          const fresh = newCharacter(o.systemId);
          const merged = Object.assign(fresh, o);
          merged.id = uid();
          if (!merged.boosts) merged.boosts = { ancestryFree: [], free: [], levels: {} };
          app.roster.push(merged); added++;
        });
        app.flash = added ? 'Imported ' + added + ' character' + (added > 1 ? 's' : '') + '.' : 'Nothing importable found in that file.';
        if (!added) alert('That file did not contain a recognisable character (needs a systemId of 5e, 4e, pf1, or pf2).');
        persist(); render();
      } catch (e) { alert('Could not read that file: ' + e.message); }
    };
    fr.readAsText(file);
  };
  inp.click();
}

/* boot */
async function boot() {
  // Decide where the data lives before drawing anything: local file, or a
  // server on the LAN. Either way this resolves; it never throws.
  await storeInit();

  if (isConnected() && !signedIn()) {
    app.view = 'signin';
    render();
    return;
  }
  app.roster = loadRoster();
  app.roster.forEach(migrateCharacter);
  // discard anything created but never filled in (e.g. the tab was closed mid-wizard)
  pruneBlank();
  render();
  // and from here on, keep up with whatever anyone else changes
  if (typeof storeWatch === 'function') storeWatch();
}

window.addEventListener('DOMContentLoaded', function () {
  // paint the shell straight away so a slow ping is not a blank screen
  boot();
});


/* ===== 80-spells-5e.js ===== */
/* ============================================================
   D&D 5e spell catalogue — SRD 5.1 + SRD 5.2.1 additions
   ------------------------------------------------------------
   System Reference Document 5.1 Copyright 2016, Wizards of the
   Coast, Inc.; Authors Mike Mearls, Jeremy Crawford, Chris Perkins,
   Rodney Thompson, Peter Lee, James Wyatt, Robert J. Schwalb,
   Bruce R. Cordell, Chris Sims, and Steve Townshend, based on
   original material by E. Gary Gygax and Dave Arneson.
   Available under the Open Gaming License / CC-BY-4.0.

   System Reference Document 5.2.1 © 2025 Wizards of the Coast.
   Available under Creative Commons Attribution 4.0 International (CC-BY-4.0).

   Rows are packed as arrays to keep this file small:
   [name, level, schoolIndex, castingTime, range, duration,
    components, material, concentration, ritual, [classIdx],
    description, higherLevel, damageType, saveType]

   School indices: 0 Abjuration, 1 Conjuration, 2 Divination,
   3 Enchantment, 4 Evocation, 5 Illusion, 6 Necromancy, 7 Transmutation.
   Class indices match SPELL_CLASSES_5E order.
   ============================================================ */

const SPELL_SCHOOLS_5E = ["Abjuration", "Conjuration", "Divination", "Enchantment", "Evocation", "Illusion", "Necromancy", "Transmutation"];
const SPELL_CLASSES_5E = ["bard", "cleric", "druid", "paladin", "ranger", "sorcerer", "warlock", "wizard"];
const SPELLDATA_5E = [
["Acid Splash",0,1,"1 action","60 feet","Instantaneous","VS","",0,0,[5, 7],"You hurl a bubble of acid. Choose one creature within range, or choose two creatures within range that are within 5 feet of each other. A target must succeed on a dexterity saving throw or take 1d6 acid damage.\n\nThis spell's damage increases by 1d6 when you reach 5th level (2d6), 11th level (3d6), and 17th level (4d6).","","Acid","DEX"],
["Chill Touch",0,6,"1 action","120 feet","1 round","VS","",0,0,[5, 6, 7],"You create a ghostly, skeletal hand in the space of a creature within range. Make a ranged spell attack against the creature to assail it with the chill of the grave. On a hit, the target takes 1d8 necrotic damage, and it can't regain hit points until the start of your next turn. Until then, the hand clings to the target.\n\nIf you hit an undead target, it also has disadvantage on attack rolls against you until the end of your next turn.\n\nThis spell's damage increases by 1d8 when you reach 5th level (2d8), 11th level (3d8), and 17th level (4d8).","","Necrotic",""],
["Dancing Lights",0,4,"1 action","120 feet","Up to 1 minute","VSM","A bit of phosphorus or wychwood, or a glowworm.",1,0,[0, 5, 7],"You create up to four torch-sized lights within range, making them appear as torches, lanterns, or glowing orbs that hover in the air for the duration. You can also combine the four lights into one glowing vaguely humanoid form of Medium size. Whichever form you choose, each light sheds dim light in a 10-foot radius.\n\nAs a bonus action on your turn, you can move the lights up to 60 feet to a new spot within range. A light must be within 20 feet of another light created by this spell, and a light winks out if it exceeds the spell's range.","","",""],
["Druidcraft",0,7,"1 action","30 feet","Instantaneous","VS","",0,0,[2],"Whispering to the spirits of nature, you create one of the following effects within 'range':\n\n- You create a tiny, harmless sensory effect that predicts what the weather will be at your location for the next 24 hours. The effect might manifest as a golden orb for clear skies, a cloud for rain, falling snowflakes for snow, and so on. This effect persists for 1 round.\n\n- You instantly make a flower bloom, a seed pod open, or a leaf bud bloom.\n\n- You create an instantaneous, harmless sensory effect, such as falling leaves, a puff of wind, the sound of a small animal, or the faint order of skunk. The effect must fit in a 5-foot cube.\n\n- You instantly light or snuff out a candle, a torch, or a small campfire.","","",""],
["Eldritch Blast",0,4,"1 action","120 feet","Instantaneous","VS","",0,0,[6],"A beam of crackling energy streaks toward a creature within range. Make a ranged spell attack against the target. On a hit, the target takes 1d10 force damage. The spell creates more than one beam when you reach higher levels: two beams at 5th level, three beams at 11th level, and four beams at 17th level. You can direct the beams at the same target or at different ones. Make a separate attack roll for each beam.","","Force",""],
["Fire Bolt",0,4,"1 action","120 feet","Instantaneous","VS","",0,0,[5, 7],"You hurl a mote of fire at a creature or object within range. Make a ranged spell attack against the target. On a hit, the target takes 1d10 fire damage. A flammable object hit by this spell ignites if it isn't being worn or carried.\n\nThis spell's damage increases by 1d10 when you reach 5th level (2d10), 11th level (3d10), and 17th level (4d10).","","Fire",""],
["Guidance",0,2,"1 action","Touch","Up to 1 minute","VS","",1,0,[1, 2],"You touch one willing creature. Once before the spell ends, the target can roll a d4 and add the number rolled to one ability check of its choice. It can roll the die before or after making the ability check. The spell then ends.","","",""],
["Light",0,4,"1 action","Touch","1 hour","VM","A firefly or phosphorescent moss.",0,0,[0, 1, 5, 7],"You touch one object that is no larger than 10 feet in any dimension. Until the spell ends, the object sheds bright light in a 20-foot radius and dim light for an additional 20 feet. The light can be colored as you like. Completely covering the object with something opaque blocks the light. The spell ends if you cast it again or dismiss it as an action.\n\nIf you target an object held or worn by a hostile creature, that creature must succeed on a dexterity saving throw to avoid the spell.","","","DEX"],
["Mage Hand",0,1,"1 action","30 feet","1 minute","VS","",0,0,[0, 5, 6, 7],"A spectral, floating hand appears at a point you choose within range. The hand lasts for the duration or until you dismiss it as an action. The hand vanishes if it is ever more than 30 feet away from you or if you cast this spell again.\n\nYou can use your action to control the hand. You can use the hand to manipulate an object, open an unlocked door or container, stow or retrieve an item from an open container, or pour the contents out of a vial. You can move the hand up to 30 feet each time you use it.\n\nThe hand can't attack, activate magic items, or carry more than 10 pounds.","","",""],
["Mending",0,7,"1 minute","Touch","Instantaneous","VSM","Two lodestones.",0,0,[0, 1, 2, 5, 7],"This spell repairs a single break or tear in an object you touch, such as a broken key, a torn cloak, or a leaking wineskin. As long as the break or tear is no longer than 1 foot in any dimension, you mend it, leaving no trace of the former damage.\n\nThis spell can physically repair a magic item or construct, but the spell can't restore magic to such an object.","","",""],
["Message",0,7,"1 action","120 feet","1 round","VSM","A short piece of copper wire.",0,0,[0, 5, 7],"You point your finger toward a creature within range and whisper a message. The target (and only the target) hears the message and can reply in a whisper that only you can hear.\n\nYou can cast this spell through solid objects if you are familiar with the target and know it is beyond the barrier. Magical silence, 1 foot of stone, 1 inch of common metal, a thin sheet of lead, or 3 feet of wood blocks the spell. The spell doesn't have to follow a straight line and can travel freely around corners or through openings.","","",""],
["Minor Illusion",0,5,"1 action","30 feet","1 minute","SM","A bit of fleece.",0,0,[0, 5, 6, 7],"You create a sound or an image of an object within range that lasts for the duration. The illusion also ends if you dismiss it as an action or cast this spell again.\n\nIf you create a sound, its volume can range from a whisper to a scream. It can be your voice, someone else's voice, a lion's roar, a beating of drums, or any other sound you choose. The sound continues unabated throughout the duration, or you can make discrete sounds at different times before the spell ends.\n\nIf you create an image of an object--such as a chair, muddy footprints, or a small chest--it must be no larger than a 5-foot cube. The image can't create sound, light, smell, or any other sensory effect. Physical interaction with the image reveals it to be an illusion, because things can pass through it.\n\nIf a creature uses its action to examine the sound or image, the creature can determine that it is an illusion with a successful Intelligence (Investigation) check against your spell save DC. If a creature discerns the illusion for what it is, the illusion becomes faint to the creature.","","",""],
["Poison Spray",0,1,"1 action","10 feet","Instantaneous","VS","",0,0,[2, 5, 6, 7],"You extend your hand toward a creature you can see within range and project a puff of noxious gas from your palm. The creature must succeed on a constitution saving throw or take 1d12 poison damage.\n\nThis spell's damage increases by 1d12 when you reach 5th level (2d12), 11th level (3d12), and 17th level (4d12).","","Poison","CON"],
["Prestidigitation",0,7,"1 action","10 feet","1 hour","VS","",0,0,[0, 5, 6, 7],"This spell is a minor magical trick that novice spellcasters use for practice. You create one of the following magical effects within 'range':\n\nYou create an instantaneous, harmless sensory effect, such as a shower of sparks, a puff of wind, faint musical notes, or an odd odor.\n\nYou instantaneously light or snuff out a candle, a torch, or a small campfire.\n\nYou instantaneously clean or soil an object no larger than 1 cubic foot.\n\nYou chill, warm, or flavor up to 1 cubic foot of nonliving material for 1 hour.\n\nYou make a color, a small mark, or a symbol appear on an object or a surface for 1 hour.\n\nYou create a nonmagical trinket or an illusory image that can fit in your hand and that lasts until the end of your next turn.\n\nIf you cast this spell multiple times, you can have up to three of its non-instantaneous effects active at a time, and you can dismiss such an effect as an action.","","",""],
["Produce Flame",0,1,"1 action","Self","10 minutes","VS","",0,0,[2],"A flickering flame appears in your hand. The flame remains there for the duration and harms neither you nor your equipment. The flame sheds bright light in a 10-foot radius and dim light for an additional 10 feet. The spell ends if you dismiss it as an action or if you cast it again.\n\nYou can also attack with the flame, although doing so ends the spell. When you cast this spell, or as an action on a later turn, you can hurl the flame at a creature within 30 feet of you. Make a ranged spell attack. On a hit, the target takes 1d8 fire damage.\n\nThis spell's damage increases by 1d8 when you reach 5th level (2d8), 11th level (3d8), and 17th level (4d8).","","Fire",""],
["Ray of Frost",0,4,"1 action","60 feet","Instantaneous","VS","",0,0,[5, 7],"A frigid beam of blue-white light streaks toward a creature within range. Make a ranged spell attack against the target. On a hit, it takes 1d8 cold damage, and its speed is reduced by 10 feet until the start of your next turn.\n\nThe spell's damage increases by 1d8 when you reach 5th level (2d8), 11th level (3d8), and 17th level (4d8).","","Cold",""],
["Resistance",0,0,"1 action","Touch","Up to 1 minute","VSM","A miniature cloak.",1,0,[1, 2],"You touch one willing creature. Once before the spell ends, the target can roll a d4 and add the number rolled to one saving throw of its choice. It can roll the die before or after making the saving throw. The spell then ends.","","",""],
["Sacred Flame",0,4,"1 action","60 feet","Instantaneous","VS","",0,0,[1],"Flame-like radiance descends on a creature that you can see within range. The target must succeed on a dexterity saving throw or take 1d8 radiant damage. The target gains no benefit from cover for this saving throw.\n\nThe spell's damage increases by 1d8 when you reach 5th level (2d8), 11th level (3d8), and 17th level (4d8).","","Radiant","DEX"],
["Shillelagh",0,7,"1 bonus action","Touch","1 minute","VSM","Mistletoe, a shamrock leaf, and a club or quarterstaff.",0,0,[2],"The wood of a club or a quarterstaff you are holding is imbued with nature's power. For the duration, you can use your spellcasting ability instead of Strength for the attack and damage rolls of melee attacks using that weapon, and the weapon's damage die becomes a d8. The weapon also becomes magical, if it isn't already. The spell ends if you cast it again or if you let go of the weapon.","","",""],
["Shocking Grasp",0,4,"1 action","Touch","Instantaneous","VS","",0,0,[5, 7],"Lightning springs from your hand to deliver a shock to a creature you try to touch. Make a melee spell attack against the target. You have advantage on the attack roll if the target is wearing armor made of metal. On a hit, the target takes 1d8 lightning damage, and it can't take reactions until the start of its next turn.\n\nThe spell's damage increases by 1d8 when you reach 5th level (2d8), 11th level (3d8), and 17th level (4d8).","","Lightning",""],
["Spare the Dying",0,6,"1 action","Touch","Instantaneous","VS","",0,0,[1],"You touch a living creature that has 0 hit points. The creature becomes stable. This spell has no effect on undead or constructs.","","",""],
["Thaumaturgy",0,7,"1 action","30 feet","1 minute","V","",0,0,[1],"You manifest a minor wonder, a sign of supernatural power, within range. You create one of the following magical effects within range.\n\n- Your voice booms up to three times as loud as normal for 1 minute.\n\n- You cause flames to flicker, brighten, dim, or change color for 1 minute.\n\n- You cause harmless tremors in the ground for 1 minute.\n\n- You create an instantaneous sound that originates from a point of your choice within range, such as a rumble of thunder, the cry of a raven, or ominous whispers.\n\n- You instantaneously cause an unlocked door or window to fly open or slam shut.\n\n- You alter the appearance of your eyes for 1 minute.\n\nIf you cast this spell multiple times, you can have up to three of its 1-minute effects active at a time, and you can dismiss such an effect as an action.","","",""],
["True Strike",0,2,"1 action","30 feet","Up to 1 round","S","",1,0,[0, 5, 6, 7],"You extend your hand and point a finger at a target in range. Your magic grants you a brief insight into the target's defenses. On your next turn, you gain advantage on your first attack roll against the target, provided that this spell hasn't ended.","","",""],
["Vicious Mockery",0,3,"1 action","60 feet","Instantaneous","V","",0,0,[0],"You unleash a string of insults laced with subtle enchantments at a creature you can see within range. If the target can hear you (though it need not understand you), it must succeed on a wisdom saving throw or take 1d4 psychic damage and have disadvantage on the next attack roll it makes before the end of its next turn.\n\nThis spell's damage increases by 1d4 when you reach 5th level (2d4), 11th level (3d4), and 17th level (4d4).","","Psychic","WIS"],
["Alarm",1,0,"1 minute","30 feet","8 hours","VSM","A tiny bell and a piece of fine silver wire.",0,1,[4, 7],"You set an alarm against unwanted intrusion. Choose a door, a window, or an area within range that is no larger than a 20-foot cube. Until the spell ends, an alarm alerts you whenever a Tiny or larger creature touches or enters the warded area. When you cast the spell, you can designate creatures that won't set off the alarm. You also choose whether the alarm is mental or audible.\n\nA mental alarm alerts you with a ping in your mind if you are within 1 mile of the warded area. This ping awakens you if you are sleeping.\n\nAn audible alarm produces the sound of a hand bell for 10 seconds within 60 feet.","","",""],
["Animal Friendship",1,3,"1 action","30 feet","24 hours","VSM","A morsel of food.",0,0,[0, 2, 4],"This spell lets you convince a beast that you mean it no harm. Choose a beast that you can see within range. It must see and hear you. If the beast's Intelligence is 4 or higher, the spell fails. Otherwise, the beast must succeed on a wisdom saving throw or be charmed by you for the spell's duration. If you or one of your companions harms the target, the spells ends.","","","WIS"],
["Bane",1,3,"1 action","30 feet","Up to 1 minute","VSM","A drop of blood.",1,0,[0, 1],"Up to three creatures of your choice that you can see within range must make charisma saving throws. Whenever a target that fails this saving throw makes an attack roll or a saving throw before the spell ends, the target must roll a d4 and subtract the number rolled from the attack roll or saving throw.","When you cast this spell using a spell slot of 2nd level or higher, you can target one additional creature for each slot level above 1st.","","CHA"],
["Bless",1,3,"1 action","30 feet","Up to 1 minute","VSM","A sprinkling of holy water.",1,0,[1, 3],"You bless up to three creatures of your choice within range. Whenever a target makes an attack roll or a saving throw before the spell ends, the target can roll a d4 and add the number rolled to the attack roll or saving throw.","When you cast this spell using a spell slot of 2nd level or higher, you can target one additional creature for each slot level above 1st.","",""],
["Burning Hands",1,4,"1 action","Self","Instantaneous","VS","",0,0,[5, 7],"As you hold your hands with thumbs touching and fingers spread, a thin sheet of flames shoots forth from your outstretched fingertips. Each creature in a 15-foot cone must make a dexterity saving throw. A creature takes 3d6 fire damage on a failed save, or half as much damage on a successful one.\n\nThe fire ignites any flammable objects in the area that aren't being worn or carried.","When you cast this spell using a spell slot of 2nd level or higher, the damage increases by 1d6 for each slot level above 1st.","Fire","DEX"],
["Charm Person",1,3,"1 action","30 feet","1 hour","VS","",0,0,[0, 2, 5, 6, 7],"You attempt to charm a humanoid you can see within range. It must make a wisdom saving throw, and does so with advantage if you or your companions are fighting it. If it fails the saving throw, it is charmed by you until the spell ends or until you or your companions do anything harmful to it. The charmed creature regards you as a friendly acquaintance. When the spell ends, the creature knows it was charmed by you.","When you cast this spell using a spell slot of 2nd level or higher, you can target one additional creature for each slot level above 1st. The creatures must be within 30 feet of each other when you target them.","","WIS"],
["Color Spray",1,5,"1 action","Self","1 round","VSM","A pinch of powder or sand that is colored red, yellow, and blue.",0,0,[5, 7],"A dazzling array of flashing, colored light springs from your hand. Roll 6d10; the total is how many hit points of creatures this spell can effect. Creatures in a 15-foot cone originating from you are affected in ascending order of their current hit points (ignoring unconscious creatures and creatures that can't see).\n\nStarting with the creature that has the lowest current hit points, each creature affected by this spell is blinded until the spell ends. Subtract each creature's hit points from the total before moving on to the creature with the next lowest hit points. A creature's hit points must be equal to or less than the remaining total for that creature to be affected.","When you cast this spell using a spell slot of 2nd level or higher, roll an additional 2d10 for each slot level above 1st.","",""],
["Command",1,3,"1 action","60 feet","1 round","V","",0,0,[1, 3],"You speak a one-word command to a creature you can see within range. The target must succeed on a wisdom saving throw or follow the command on its next turn. The spell has no effect if the target is undead, if it doesn't understand your language, or if your command is directly harmful to it.\n\nSome typical commands and their effects follow. You might issue a command other than one described here. If you do so, the GM determines how the target behaves. If the target can't follow your command, the spell ends.\n\n***Approach.*** The target moves toward you by the shortest and most direct route, ending its turn if it moves within 5 feet of you.\n\n***Drop.*** The target drops whatever it is holding and then ends its turn.\n\n***Flee.*** The target spends its turn moving away from you by the fastest available means.\n\n***Grovel.*** The target falls prone and then ends its turn.\n\n***Halt.*** The target doesn't move and takes no actions. A flying creature stays aloft, provided that it is able to do so. If it must move to stay aloft, it flies the minimum distance needed to remain in the air.","When you cast this spell using a spell slot of 2nd level or higher, you can affect one additional creature for each slot level above 1st. The creatures must be within 30 feet of each other when you target them.","","WIS"],
["Comprehend Languages",1,2,"1 action","Self","1 hour","VSM","A pinch of soot and salt.",0,1,[0, 5, 6, 7],"For the duration, you understand the literal meaning of any spoken language that you hear. You also understand any written language that you see, but you must be touching the surface on which the words are written. It takes about 1 minute to read one page of text.\n\nThis spell doesn't decode secret messages in a text or a glyph, such as an arcane sigil, that isn't part of a written language.","","",""],
["Create or Destroy Water",1,7,"1 action","30 feet","Instantaneous","VSM","A drop of water if creating water, or a few grains of sand if destroying it.",0,0,[1, 2],"You either create or destroy water.\n\n***Create Water.*** You create up to 10 gallons of clean water within range in an open container. Alternatively, the water falls as rain in a 30-foot cube within range.\n\n***Destroy Water.*** You destroy up to 10 gallons of water in an open container within range. Alternatively, you destroy fog in a 30-foot cube within range.","When you cast this spell using a spell slot of 2nd level or higher, you create or destroy 10 additional gallons of water, or the size of the cube increases by 5 feet, for each slot level above 1st.","",""],
["Cure Wounds",1,4,"1 action","Touch","Instantaneous","VS","",0,0,[0, 1, 2, 3, 4],"A creature you touch regains a number of hit points equal to 1d8 + your spellcasting ability modifier. This spell has no effect on undead or constructs.","When you cast this spell using a spell slot of 2nd level or higher, the healing increases by 1d8 for each slot level above 1st.","",""],
["Detect Evil and Good",1,2,"1 action","Self","Up to 10 minutes","VS","",1,0,[1, 3],"For the duration, you know if there is an aberration, celestial, elemental, fey, fiend, or undead within 30 feet of you, as well as where the creature is located. Similarly, you know if there is a place or object within 30 feet of you that has been magically consecrated or desecrated.\n\nThe spell can penetrate most barriers, but it is blocked by 1 foot of stone, 1 inch of common metal, a thin sheet of lead, or 3 feet of wood or dirt.","","",""],
["Detect Magic",1,2,"1 action","Self","Up to 10 minutes","VS","",1,1,[0, 1, 2, 3, 4, 5, 7],"For the duration, you sense the presence of magic within 30 feet of you. If you sense magic in this way, you can use your action to see a faint aura around any visible creature or object in the area that bears magic, and you learn its school of magic, if any.\n\nThe spell can penetrate most barriers, but it is blocked by 1 foot of stone, 1 inch of common metal, a thin sheet of lead, or 3 feet of wood or dirt.","","",""],
["Detect Poison and Disease",1,2,"1 action","Self","Up to 10 minutes","VSM","A yew leaf.",1,1,[1, 2, 3, 4],"For the duration, you can sense the presence and location of poisons, poisonous creatures, and diseases within 30 feet of you. You also identify the kind of poison, poisonous creature, or disease in each case.\n\nThe spell can penetrate most barriers, but it is blocked by 1 foot of stone, 1 inch of common metal, a thin sheet of lead, or 3 feet of wood or dirt.","","",""],
["Disguise Self",1,5,"1 action","Self","1 hour","VS","",0,0,[0, 5, 7],"You make yourself--including your clothing, armor, weapons, and other belongings on your person--look different until the spell ends or until you use your action to dismiss it. You can seem 1 foot shorter or taller and can appear thin, fat, or in between. You can't change your body type, so you must adopt a form that has the same basic arrangement of limbs. Otherwise, the extent of the illusion is up to you.\n\nThe changes wrought by this spell fail to hold up to physical inspection. For example, if you use this spell to add a hat to your outfit, objects pass through the hat, and anyone who touches it would feel nothing or would feel your head and hair. If you use this spell to appear thinner than you are, the hand of someone who reaches out to touch you would bump into you while it was seemingly still in midair.\n\nTo discern that you are disguised, a creature can use its action to inspect your appearance and must succeed on an Intelligence (Investigation) check against your spell save DC.","","",""],
["Divine Favor",1,4,"1 bonus action","Self","Up to 1 minute","VS","",1,0,[3],"Your prayer empowers you with divine radiance. Until the spell ends, your weapon attacks deal an extra 1d4 radiant damage on a hit.","","Radiant",""],
["Entangle",1,1,"1 action","90 feet","Up to 1 minute","VS","",1,0,[2],"Grasping weeds and vines sprout from the ground in a 20-foot square starting form a point within range. For the duration, these plants turn the ground in the area into difficult terrain.\n\nA creature in the area when you cast the spell must succeed on a strength saving throw or be restrained by the entangling plants until the spell ends. A creature restrained by the plants can use its action to make a Strength check against your spell save DC. On a success, it frees itself.\n\nWhen the spell ends, the conjured plants wilt away.","","","STR"],
["Expeditious Retreat",1,7,"1 bonus action","Self","Up to 10 minutes","VS","",1,0,[5, 6, 7],"This spell allows you to move at an incredible pace. When you cast this spell, and then as a bonus action on each of your turns until the spell ends, you can take the Dash action.","","",""],
["Faerie Fire",1,4,"1 action","60 feet","Up to 1 minute","V","",1,0,[2],"Each object in a 20-foot cube within range is outlined in blue, green, or violet light (your choice). Any creature in the area when the spell is cast is also outlined in light if it fails a dexterity saving throw. For the duration, objects and affected creatures shed dim light in a 10-foot radius.\n\nAny attack roll against an affected creature or object has advantage if the attacker can see it, and the affected creature or object can't benefit from being invisible.","","","DEX"],
["False Life",1,6,"1 action","Self","1 hour","VSM","A small amount of alcohol or distilled spirits.",0,0,[5, 7],"Bolstering yourself with a necromantic facsimile of life, you gain 1d4 + 4 temporary hit points for the duration.","When you cast this spell using a spell slot of 2nd level or higher, you gain 5 additional temporary hit points for each slot level above 1st.","",""],
["Feather Fall",1,7,"1 reaction","60 feet","1 minute","VM","A small feather or a piece of down.",0,0,[0, 5, 7],"Choose up to five falling creatures within range. A falling creature's rate of descent slows to 60 feet per round until the spell ends. If the creature lands before the spell ends, it takes no falling damage and can land on its feet, and the spell ends for that creature.","","",""],
["Find Familiar",1,1,"1 hour","10 feet","Instantaneous","VSM","10gp worth of charcoal, incense, and herbs that must be consumed by fire in a brass brazier.",0,1,[7],"You gain the service of a familiar, a spirit that takes an animal form you choose: bat, cat, crab, frog (toad), hawk, lizard, octopus, owl, poisonous snake, fish (quipper), rat, raven, sea horse, spider, or weasel. Appearing in an unoccupied space within range, the familiar has the statistics of the chosen form, though it is a celestial, fey, or fiend (your choice) instead of a beast.\n\nYour familiar acts independently of you, but it always obeys your commands. In combat, it rolls its own initiative and acts on its own turn. A familiar can't attack, but it can take other actions as normal.\n\nWhen the familiar drops to 0 hit points, it disappears, leaving behind no physical form. It reappears after you cast this spell again.\n\nWhile your familiar is within 100 feet of you, you can communicate with it telepathically. Additionally, as an action, you can see through your familiar's eyes and hear what it hears until the start of your next turn, gaining the benefits of any special senses that the familiar has. During this time, you are deaf and blind with regard to your own senses.\n\nAs an action, you can temporarily dismiss your familiar. It disappears into a pocket dimension where it awaits your summons. Alternatively, you can dismiss it forever. As an action while it is temporarily dismissed, you can cause it to reappear in any unoccupied space within 30 feet of you.\n\nYou can't have more than one familiar at a time. If you cast this spell while you already have a familiar, you instead cause it to adopt a new form. Choose one of the forms from the above list. Your familiar transforms into the chosen creature.\n\nFinally, when you cast a spell with a range of touch, your familiar can deliver the spell as if it had cast the spell. Your familiar must be within 100 feet of you, and it must use its reaction to deliver the spell when you cast it. If the spell requires an attack roll, you use your action modifier for the roll.","","",""],
["Floating Disk",1,1,"1 action","30 feet","1 hour","VSM","A drop of mercury.",0,1,[7],"This spell creates a circular, horizontal plane of force, 3 feet in diameter and 1 inch thick, that floats 3 feet above the ground in an unoccupied space of your choice that you can see within range. The disk remains for the duration, and can hold up to 500 pounds. If more weight is placed on it, the spell ends, and everything on the disk falls to the ground.\n\nThe disk is immobile while you are within 20 feet of it. If you move more than 20 feet away from it, the disk follows you so that it remains within 20 feet of you. If can move across uneven terrain, up or down stairs, slopes and the like, but it can't cross an elevation change of 10 feet or more. For example, the disk can't move across a 10-foot-deep pit, nor could it leave such a pit if it was created at the bottom.\n\nIf you move more than 100 feet away from the disk (typically because it can't move around an obstacle to follow you), the spell ends.","","",""],
["Fog Cloud",1,1,"1 action","120 feet","Up to 1 hour","VS","",1,0,[2, 4, 5, 7],"You create a 20-foot-radius sphere of fog centered on a point within range. The sphere spreads around corners, and its area is heavily obscured. It lasts for the duration or until a wind of moderate or greater speed (at least 10 miles per hour) disperses it.","When you cast this spell using a spell slot of 2nd level or higher, the radius of the fog increases by 20 feet for each slot level above 1st.","",""],
["Goodberry",1,7,"1 action","Touch","Instantaneous","VSM","A sprig of mistletoe.",0,0,[2, 4],"Up to ten berries appear in your hand and are infused with magic for the duration. A creature can use its action to eat one berry. Eating a berry restores 1 hit point, and the berry provides enough nourishment to sustain a creature for a day.\n\nThe berries lose their potency if they have not been consumed within 24 hours of the casting of this spell.","","",""],
["Grease",1,1,"1 action","60 feet","1 minute","VSM","A bit of pork rind or butter.",0,0,[7],"Slick grease covers the ground in a 10-foot square centered on a point within range and turns it into difficult terrain for the duration.\n\nWhen the grease appears, each creature standing in its area must succeed on a dexterity saving throw or fall prone. A creature that enters the area or ends its turn there must also succeed on a dexterity saving throw or fall prone.","","","DEX"],
["Guiding Bolt",1,4,"1 action","120 feet","1 round","VS","",0,0,[1],"A flash of light streaks toward a creature of your choice within range. Make a ranged spell attack against the target. On a hit, the target takes 4d6 radiant damage, and the next attack roll made against this target before the end of your next turn has advantage, thanks to the mystical dim light glittering on the target until then.","When you cast this spell using a spell slot of 2nd level or higher, the damage increases by 1d6 for each slot level above 1st.","Radiant",""],
["Healing Word",1,4,"1 bonus action","60 feet","Instantaneous","V","",0,0,[0, 1, 2],"A creature of your choice that you can see within range regains hit points equal to 1d4 + your spellcasting ability modifier. This spell has no effect on undead or constructs.","When you cast this spell using a spell slot of 2nd level or higher, the healing increases by 1d4 for each slot level above 1st.","",""],
["Hellish Rebuke",1,4,"1 reaction","60 feet","Instantaneous","VS","",0,0,[6],"You point your finger, and the creature that damaged you is momentarily surrounded by hellish flames. The creature must make a dexterity saving throw. It takes 2d10 fire damage on a failed save, or half as much damage on a successful one.","When you cast this spell using a spell slot of 2nd level or higher, the damage increases by 1d10 for each slot level above 1st.","Fire","DEX"],
["Heroism",1,3,"1 action","Touch","Up to 1 minute","VS","",1,0,[0, 3],"A willing creature you touch is imbued with bravery. Until the spell ends, the creature is immune to being frightened and gains temporary hit points equal to your spellcasting ability modifier at the start of each of its turns. When the spell ends, the target loses any remaining temporary hit points from this spell.","","",""],
["Hideous Laughter",1,3,"1 action","30 feet","Up to 1 minute","VSM","Tiny tarts and a feather that is waved in the air.",1,0,[0, 7],"A creature of your choice that you can see within range perceives everything as hilariously funny and falls into fits of laughter if this spell affects it. The target must succeed on a wisdom saving throw or fall prone, becoming incapacitated and unable to stand up for the duration. A creature with an Intelligence score of 4 or less isn't affected.\n\nAt the end of each of its turns, and each time it takes damage, the target can make another wisdom saving throw. The target had advantage on the saving throw if it's triggered by damage. On a success, the spell ends.","","","WIS"],
["Hunter's Mark",1,2,"1 bonus action","90 feet","Up to 1 hour","V","",1,0,[4],"You choose a creature you can see within range and mystically mark it as your quarry. Until the spell ends, you deal an extra 1d6 damage to the target whenever you hit it with a weapon attack, and you have advantage on any Wisdom (Perception) or Wisdom (Survival) check you make to find it. If the target drops to 0 hit points before this spell ends, you can use a bonus action on a subsequent turn of yours to mark a new creature.","When you cast this spell using a spell slot of 3rd or 4th level, you can maintain your concentration on the spell for up to 8 hours. When you use a spell slot of 5th level or higher, you can maintain your concentration on the spell for up to 24 hours.","",""],
["Identify",1,2,"1 minute","Touch","Instantaneous","VSM","A pearl worth at least 100gp and an owl feather.",0,1,[0, 7],"You choose one object that you must touch throughout the casting of the spell. If it is a magic item or some other magic-imbued object, you learn its properties and how to use them, whether it requires attunement to use, and how many charges it has, if any. You learn whether any spells are affecting the item and what they are. If the item was created by a spell, you learn which spell created it.\n\nIf you instead touch a creature throughout the casting, you learn what spells, if any, are currently affecting it.","","",""],
["Illusory Script",1,5,"1 minute","Touch","10 days","SM","A lead-based ink worth at least 10gp, which this spell consumes.",0,1,[0, 6, 7],"You write on parchment, paper, or some other suitable writing material and imbue it with a potent illusion that lasts for the duration.\n\nTo you and any creatures you designate when you cast the spell, the writing appears normal, written in your hand, and conveys whatever meaning you intended when you wrote the text. To all others, the writing appears as if it were written in an unknown or magical script that is unintelligible. Alternatively, you can cause the writing to appear to be an entirely different message, written in a different hand and language, though the language must be one you know.\n\nShould the spell be dispelled, the original script and the illusion both disappear.\n\nA creature with truesight can read the hidden message.","","",""],
["Inflict Wounds",1,6,"1 action","Touch","Instantaneous","VS","",0,0,[1],"Make a melee spell attack against a creature you can reach. On a hit, the target takes 3d10 necrotic damage.","When you cast this spell using a spell slot of 2nd level or higher, the damage increases by 1d10 for each slot level above 1st.","Necrotic",""],
["Jump",1,7,"1 action","Touch","1 minute","VSM","A grasshopper's hind leg.",0,0,[2, 4, 5, 7],"You touch a creature. The creature's jump distance is tripled until the spell ends.","","",""],
["Longstrider",1,7,"1 action","Touch","1 hour","VSM","A pinch of dirt.",0,0,[0, 2, 4, 7],"You touch a creature. The target's speed increases by 10 feet until the spell ends.","When you cast this spell using a spell slot of 2nd level or higher, you can target one additional creature for each spell slot above 1st.","",""],
["Mage Armor",1,0,"1 action","Touch","8 hours","VSM","A piece of cured leather.",0,0,[5, 7],"You touch a willing creature who isn't wearing armor, and a protective magical force surrounds it until the spell ends. The target's base AC becomes 13 + its Dexterity modifier. The spell ends if the target dons armor or if you dismiss the spell as an action.","","",""],
["Magic Missile",1,4,"1 action","120 feet","Instantaneous","VS","",0,0,[5, 7],"You create three glowing darts of magical force. Each dart hits a creature of your choice that you can see within range. A dart deals 1d4 + 1 force damage to its target. The darts all strike simultaneously, and you can direct them to hit one creature or several.","When you cast this spell using a spell slot of 2nd level or higher, the spell creates one more dart for each slot level above 1st.","Force",""],
["Protection from Evil and Good",1,0,"1 action","Touch","Up to 10 minutes","VSM","Holy water or powdered silver and iron, which the spell consumes.",1,0,[1, 3, 6, 7],"Until the spell ends, one willing creature you touch is protected against certain types of creatures: aberrations, celestials, elementals, fey, fiends, and undead.\n\nThe protection grants several benefits. Creatures of those types have disadvantage on attack rolls against the target. The target also can't be charmed, frightened, or possessed by them. If the target is already charmed, frightened, or possessed by such a creature, the target has advantage on any new saving throw against the relevant effect.","","",""],
["Purify Food and Drink",1,7,"1 action","10 feet","Instantaneous","VS","",0,1,[1, 2, 3],"All nonmagical food and drink within a 5-foot radius sphere centered on a point of your choice within range is purified and rendered free of poison and disease.","","",""],
["Sanctuary",1,0,"1 bonus action","30 feet","1 minute","VSM","A small silver mirror.",0,0,[1],"You ward a creature within range against attack. Until the spell ends, any creature who targets the warded creature with an attack or a harmful spell must first make a wisdom saving throw. On a failed save, the creature must choose a new target or lose the attack or spell. This spell doesn't protect the warded creature from area effects, such as the explosion of a fireball.\n\nIf the warded creature makes an attack or casts a spell that affects an enemy creature, this spell ends.","","",""],
["Shield",1,0,"1 reaction","Self","1 round","VS","",0,0,[5, 7],"An invisible barrier of magical force appears and protects you. Until the start of your next turn, you have a +5 bonus to AC, including against the triggering attack, and you take no damage from magic missile.","","",""],
["Shield of Faith",1,0,"1 bonus action","60 feet","Up to 10 minutes","VSM","A small parchment with a bit of holy text written on it.",1,0,[1, 3],"A shimmering field appears and surrounds a creature of your choice within range, granting it a +2 bonus to AC for the duration.","","",""],
["Silent Image",1,5,"1 action","60 feet","Up to 10 minutes","VSM","A bit of fleece.",1,0,[0, 5, 7],"You create the image of an object, a creature, or some other visible phenomenon that is no larger than a 15-foot cube. The image appears at a spot within range and lasts for the duration. The image is purely visual; it isn't accompanied by sound, smell, or other sensory effects.\n\nYou can use your action to cause the image to move to any spot within range. As the image changes location, you can alter its appearance so that its movements appear natural for the image. For example, if you create an image of a creature and move it, you can alter the image so that it appears to be walking.\n\nPhysical interaction with the image reveals it to be an illusion, because things can pass through it. A creature that uses its action to examine the image can determine that it is an illusion with a successful Intelligence (Investigation) check against your spell save DC. If a creature discerns the illusion for what it is, the creature can see through the image.","","",""],
["Sleep",1,3,"1 action","90 feet","1 minute","VSM","A pinch of fine sand, rose petals, or a cricket.",0,0,[0, 5, 7],"This spell sends creatures into a magical slumber. Roll 5d8; the total is how many hit points of creatures this spell can affect. Creatures within 20 feet of a point you choose within range are affected in ascending order of their current hit points (ignoring unconscious creatures).\n\nStarting with the creature that has the lowest current hit points, each creature affected by this spell falls unconscious until the spell ends, the sleeper takes damage, or someone uses an action to shake or slap the sleeper awake. Subtract each creature's hit points from the total before moving on to the creature with the next lowest hit points. A creature's hit points must be equal to or less than the remaining total for that creature to be affected.\n\nUndead and creatures immune to being charmed aren't affected by this spell.","When you cast this spell using a spell slot of 2nd level or higher, roll an additional 2d8 for each slot level above 1st.","",""],
["Speak with Animals",1,2,"1 action","Self","10 minutes","VS","",0,1,[0, 2, 4],"You gain the ability to comprehend and verbally communicate with beasts for the duration. The knowledge and awareness of many beasts is limited by their intelligence, but at a minimum, beasts can give you information about nearby locations and monsters, including whatever they can perceive or have perceived within the past day. You might be able to persuade a beast to perform a small favor for you, at the GM's discretion.","","",""],
["Thunderwave",1,4,"1 action","Self","Instantaneous","VS","",0,0,[0, 2, 5, 7],"A wave of thunderous force sweeps out from you. Each creature in a 15-foot cube originating from you must make a constitution saving throw. On a failed save, a creature takes 2d8 thunder damage and is pushed 10 feet away from you. On a successful save, the creature takes half as much damage and isn't pushed.\n\nIn addition, unsecured objects that are completely within the area of effect are automatically pushed 10 feet away from you by the spell's effect, and the spell emits a thunderous boom audible out to 300 feet.","When you cast this spell using a spell slot of 2nd level or higher, the damage increases by 1d8 for each slot level above 1st.","Thunder","CON"],
["Unseen Servant",1,1,"1 action","60 feet","1 hour","VSM","A piece of string and a bit of wood.",0,1,[0, 6, 7],"This spell creates an invisible, mindless, shapeless force that performs simple tasks at your command until the spell ends. The servant springs into existence in an unoccupied space on the ground within range. It has AC 10, 1 hit point, and a Strength of 2, and it can't attack. If it drops to 0 hit points, the spell ends.\n\nOnce on each of your turns as a bonus action, you can mentally command the servant to move up to 15 feet and interact with an object. The servant can perform simple tasks that a human servant could do, such as fetching things, cleaning, mending, folding clothes, lighting fires, serving food, and pouring wine. Once you give the command, the servant performs the task to the best of its ability until it completes the task, then waits for your next command.\n\nIf you command the servant to perform a task that would move it more than 60 feet away from you, the spell ends.","","",""],
["Acid Arrow",2,4,"1 action","90 feet","Instantaneous","VSM","Powdered rhubarb leaf and an adder's stomach.",0,0,[7],"A shimmering green arrow streaks toward a target within range and bursts in a spray of acid. Make a ranged spell attack against the target. On a hit, the target takes 4d4 acid damage immediately and 2d4 acid damage at the end of its next turn. On a miss, the arrow splashes the target with acid for half as much of the initial damage and no damage at the end of its next turn.","When you cast this spell using a spell slot of 3rd level or higher, the damage (both initial and later) increases by 1d4 for each slot level above 2nd.","Acid",""],
["Aid",2,0,"1 action","30 feet","8 hours","VSM","A tiny strip of white cloth.",0,0,[1, 3],"Your spell bolsters your allies with toughness and resolve. Choose up to three creatures within range. Each target's hit point maximum and current hit points increase by 5 for the duration.","When you cast this spell using a spell slot of 3rd level or higher, a target's hit points increase by an additional 5 for each slot level above 2nd.","",""],
["Alter Self",2,7,"1 action","Self","Up to 1 hour","VS","",1,0,[5, 7],"You assume a different form. When you cast the spell, choose one of the following options, the effects of which last for the duration of the spell. While the spell lasts, you can end one option as an action to gain the benefits of a different one.\n\n***Aquatic Adaptation.*** You adapt your body to an aquatic environment, sprouting gills and growing webbing between your fingers. You can breathe underwater and gain a swimming speed equal to your walking speed.\n\n***Change Appearance.*** You transform your appearance. You decide what you look like, including your height, weight, facial features, sound of your voice, hair length, coloration, and distinguishing characteristics, if any. You can make yourself appear as a member of another race, though none of your statistics change. You also can't appear as a creature of a different size than you, and your basic shape stays the same; if you're bipedal, you can't use this spell to become quadrupedal, for instance. At any time for the duration of the spell, you can use your action to change your appearance in this way again.\n\n***Natural Weapons.*** You grow claws, fangs, spines, horns, or a different natural weapon of your choice. Your unarmed strikes deal 1d6 bludgeoning, piercing, or slashing damage, as appropriate to the natural weapon you chose, and you are proficient with your unarmed strikes. Finally, the natural weapon is magic and you have a +1 bonus to the attack and damage rolls you make using it.","","",""],
["Animal Messenger",2,3,"1 action","30 feet","24 hours","VSM","A morsel of food.",0,1,[0, 2, 4],"By means of this spell, you use an animal to deliver a message. Choose a Tiny beast you can see within range, such as a squirrel, a blue jay, or a bat. You specify a location, which you must have visited, and a recipient who matches a general description, such as \"a man or woman dressed in the uniform of the town guard\" or \"a red-haired dwarf wearing a pointed hat.\" You also speak a message of up to twenty-five words. The target beast travels for the duration of the spell toward the specified location, covering about 50 miles per 24 hours for a flying messenger, or 25 miles for other animals.\n\nWhen the messenger arrives, it delivers your message to the creature that you described, replicating the sound of your voice. The messenger speaks only to a creature matching the description you gave. If the messenger doesn't reach its destination before the spell ends, the message is lost, and the beast makes its way back to where you cast this spell.","If you cast this spell using a spell slot of 3nd level or higher, the duration of the spell increases by 48 hours for each slot level above 2nd.","",""],
["Arcane Lock",2,0,"1 action","Touch","Until dispelled","VSM","Gold dust worth at least 25gp, which the spell consumes.",0,0,[7],"You touch a closed door, window, gate, chest, or other entryway, and it becomes locked for the duration. You and the creatures you designate when you cast this spell can open the object normally. You can also set a password that, when spoken within 5 feet of the object, suppresses this spell for 1 minute. Otherwise, it is impassable until it is broken or the spell is dispelled or suppressed. Casting knock on the object suppresses arcane lock for 10 minutes.\n\nWhile affected by this spell, the object is more difficult to break or force open; the DC to break it or pick any locks on it increases by 10.","","",""],
["Arcanist's Magic Aura",2,5,"1 action","Touch","24 hours","VSM","A small square of silk.",0,0,[7],"You place an illusion on a creature or an object you touch so that divination spells reveal false information about it. The target can be a willing creature or an object that isn't being carried or worn by another creature.\n\nWhen you cast the spell, choose one or both of the following effects. The effect lasts for the duration. If you cast this spell on the same creature or object every day for 30 days, placing the same effect on it each time, the illusion lasts until it is dispelled.\n\n***False Aura.*** You change the way the target appears to spells and magical effects, such as detect magic, that detect magical auras. You can make a nonmagical object appear magical, a magical object appear nonmagical, or change the object's magical aura so that it appears to belong to a specific school of magic that you choose. When you use this effect on an object, you can make the false magic apparent to any creature that handles the item.\n\n***Mask.*** You change the way the target appears to spells and magical effects that detect creature types, such as a paladin's Divine Sense or the trigger of a symbol spell. You choose a creature type and other spells and magical effects treat the target as if it were a creature of that type or of that alignment.","","",""],
["Augury",2,2,"1 minute","Self","Instantaneous","VSM","Specially marked sticks, bones, or similar tokens worth at least 25gp.",0,1,[1],"By casting gem-inlaid sticks, rolling dragon bones, laying out ornate cards, or employing some other divining tool, you receive an omen from an otherworldly entity about the results of a specific course of action that you plan to take within the next 30 minutes. The GM chooses from the following possible omens:\n\n- Weal, for good results\n\n- Woe, for bad results\n\n- Weal and woe, for both good and bad results\n\n- Nothing, for results that aren't especially good or bad\n\nThe spell doesn't take into account any possible circumstances that might change the outcome, such as the casting of additional spells or the loss or gain of a companion.\n\nIf you cast the spell two or more times before completing your next long rest, there is a cumulative 25 percent chance for each casting after the first that you get a random reading. The GM makes this roll in secret.","","",""],
["Barkskin",2,7,"1 action","Touch","Up to 1 hour","VSM","A handful of oak bark.",1,0,[2, 4],"You touch a willing creature. Until the spell ends, the target's skin has a rough, bark-like appearance, and the target's AC can't be less than 16, regardless of what kind of armor it is wearing.","","",""],
["Blindness/Deafness",2,6,"1 action","30 feet","1 minute","V","",0,0,[0, 1, 5, 7],"You can blind or deafen a foe. Choose one creature that you can see within range to make a constitution saving throw. If it fails, the target is either blinded or deafened (your choice) for the duration. At the end of each of its turns, the target can make a constitution saving throw. On a success, the spell ends.","When you cast this spell using a spell slot of 3rd level or higher, you can target one additional creature for each slot level above 2nd.","","CON"],
["Blur",2,5,"1 action","Self","Up to 1 minute","V","",1,0,[5, 7],"Your body becomes blurred, shifting and wavering to all who can see you. For the duration, any creature has disadvantage on attack rolls against you. An attacker is immune to this effect if it doesn't rely on sight, as with blindsight, or can see through illusions, as with truesight.","","",""],
["Branding Smite",2,4,"1 bonus action","Self","Up to 1 minute","V","",1,0,[3],"The next time you hit a creature with a weapon attack before this spell ends, the weapon gleams with astral radiance as you strike. The attack deals an extra 2d6 radiant damage to the target, which becomes visible if it's invisible, and the target sheds dim light in a 5-foot radius and can't become invisible until the spell ends.","When you cast this spell using a spell slot of 3rd level or higher, the extra damage increases by 1d6 for each slot level above 2nd.","Radiant",""],
["Calm Emotions",2,3,"1 action","60 feet","Up to 1 minute","VS","",1,0,[0, 1],"You attempt to suppress strong emotions in a group of people. Each humanoid in a 20-foot-radius sphere centered on a point you choose within range must make a charisma saving throw; a creature can choose to fail this saving throw if it wishes. If a creature fails its saving throw, choose one of the following two effects. You can suppress any effect causing a target to be charmed or frightened. When this spell ends, any suppressed effect resumes, provided that its duration has not expired in the meantime.\n\nAlternatively, you can make a target indifferent about creatures of your choice that it is hostile toward. This indifference ends if the target is attacked or harmed by a spell or if it witnesses any of its friends being harmed. When the spell ends, the creature becomes hostile again, unless the GM rules otherwise.","","","CHA"],
["Continual Flame",2,4,"1 action","Touch","Until dispelled","VSM","Ruby dust worth 50 gp, which the spell consumes.",0,0,[1, 7],"A flame, equivalent in brightness to a torch, springs forth from an object that you touch. The effect looks like a regular flame, but it creates no heat and doesn't use oxygen. A continual flame can be covered or hidden but not smothered or quenched.","","",""],
["Darkness",2,4,"1 action","60 feet","Up to 10 minutes","VM","Bat fur and a drop of pitch or piece of coal.",1,0,[5, 6, 7],"Magical darkness spreads from a point you choose within range to fill a 15-foot-radius sphere for the duration. The darkness spreads around corners. A creature with darkvision can't see through this darkness, and nonmagical light can't illuminate it.\n\nIf the point you choose is on an object you are holding or one that isn't being worn or carried, the darkness emanates from the object and moves with it. Completely covering the source of the darkness with an opaque object, such as a bowl or a helm, blocks the darkness.\n\nIf any of this spell's area overlaps with an area of light created by a spell of 2nd level or lower, the spell that created the light is dispelled.","","",""],
["Darkvision",2,7,"1 action","Touch","8 hours","VSM","Either a pinch of dried carrot or an agate.",0,0,[2, 4, 5, 7],"You touch a willing creature to grant it the ability to see in the dark. For the duration, that creature has darkvision out to a range of 60 feet.","","",""],
["Detect Thoughts",2,2,"1 action","Self","Up to 1 minute","VSM","A copper coin.",1,0,[0, 5, 7],"For the duration, you can read the thoughts of certain creatures. When you cast the spell and as your action on each turn until the spell ends, you can focus your mind on any one creature that you can see within 30 feet of you. If the creature you choose has an Intelligence of 3 or lower or doesn't speak any language, the creature is unaffected.\n\nYou initially learn the surface thoughts of the creature - what is most on its mind in that moment. As an action, you can either shift your attention to another creature's thoughts or attempt to probe deeper into the same creature's mind. If you probe deeper, the target must make a Wisdom saving throw. If it fails, you gain insight into its reasoning (if any), its emotional state, and something that looms large in its mind (such as something it worries over, loves, or hates). If it succeeds, the spell ends. Either way, the target knows that you are probing into its mind, and unless you shift your attention to another creature's thoughts, the creature can use its action on its turn to make an Intelligence check contested by your Intelligence check; if it succeeds, the spell ends.\n\nQuestions verbally directed at the target creature naturally shape the course of its thoughts, so this spell is particularly effective as part of an interrogation.\n\nYou can also use this spell to detect the presence of thinking creatures you can't see. When you cast the spell or as your action during the duration, you can search for thoughts within 30 feet of you. The spell can penetrate barriers, but 2 feet of rock, 2 inches of any metal other than lead, or a thin sheet of lead blocks you. You can't detect a creature with an Intelligence of 3 or lower or one that doesn't speak any language.\n\nOnce you detect the presence of a creature in this way, you can read its thoughts for the rest of the duration as described above, even if you can't see it, but it must still be within range.","","",""],
["Enhance Ability",2,7,"1 action","Touch","Up to 1 hour","VSM","Fur or a feather from a beast.",1,0,[0, 1, 2, 5],"You touch a creature and bestow upon it a magical enhancement. Choose one of the following effects; the target gains that effect until the spell ends.\n\n***Bear's Endurance.*** The target has advantage on constitution checks. It also gains 2d6 temporary hit points, which are lost when the spell ends.\n\n***Bull's Strength.*** The target has advantage on strength checks, and his or her carrying capacity doubles.\n\n***Cat's Grace.*** The target has advantage on dexterity checks. It also doesn't take damage from falling 20 feet or less if it isn't incapacitated.\n\n***Eagle's Splendor.*** The target has advantage on Charisma checks.\n\n***Fox's Cunning.*** The target has advantage on intelligence checks.\n\n***Owl's Wisdom.*** The target has advantage on wisdom checks.","When you cast this spell using a spell slot of 3rd level or higher, you can target one additional creature for each slot level above 2nd.","",""],
["Enlarge/Reduce",2,7,"1 action","30 feet","Up to 1 minute","VSM","A pinch iron powder.",1,0,[5, 7],"You cause a creature or an object you can see within range to grow larger or smaller for the duration. Choose either a creature or an object that is neither worn nor carried. If the target is unwilling, it can make a Constitution saving throw. On a success, the spell has no effect.\n\nIf the target is a creature, everything it is wearing and carrying changes size with it. Any item dropped by an affected creature returns to normal size at once.\n\n***Enlarge.*** The target's size doubles in all dimensions, and its weight is multiplied by eight. This growth increases its size by one category-from Medium to Large, for example. If there isn't enough room for the target to double its size, the creature or object attains the maximum possible size in the space available. Until the spell ends, the target also has advantage on Strength checks and Strength saving throws. The target's weapons also grow to match its new size. While these weapons are enlarged, the target's attacks with them deal 1d4 extra damage.\n\n***Reduce.*** The target's size is halved in all dimensions, and its weight is reduced to one-eighth of normal. This reduction decreases its size by one category-from Medium to Small, for example. Until the spell ends, the target also has disadvantage on Strength checks and Strength saving throws. The target's weapons also shrink to match its new size. While these weapons are reduced, the target's attacks with them deal 1d4 less damage (this can't reduce the damage below 1).","","","CON"],
["Enthrall",2,3,"1 action","60 feet","1 minute","VS","",0,0,[0, 6],"You weave a distracting string of words, causing creatures of your choice that you can see within range and that can hear you to make a wisdom saving throw. Any creature that can't be charmed succeeds on this saving throw automatically, and if you or your companions are fighting a creature, it has advantage on the save. On a failed save, the target has disadvantage on Wisdom (Perception) checks made to perceive any creature other than you until the spell ends or until the target can no longer hear you. The spell ends if you are incapacitated or can no longer speak.","","","WIS"],
["Find Steed",2,1,"10 minutes","30 feet","Instantaneous","VS","",0,0,[3],"You summon a spirit that assumes the form of an unusually intelligent, strong, and loyal steed, creating a long-lasting bond with it. Appearing in an unoccupied space within range, the steed takes on a form that you choose, such as a warhorse, a pony, a camel, an elk, or a mastiff. (Your GM might allow other animals to be summoned as steeds.) The steed has the statistics of the chosen form, though it is a celestial, fey, or fiend (your choice) instead of its normal type. Additionally, if your steed has an Intelligence of 5 or less, its Intelligence becomes 6, and it gains the ability to understand one language of your choice that you speak.\n\nYour steed serves you as a mount, both in combat and out, and you have an instinctive bond with it that allows you to fight as a seamless unit. While mounted on your steed, you can make any spell you cast that targets only you also target your steed.\n\nWhen the steed drops to 0 hit points, it disappears, leaving behind no physical form. You can also dismiss your steed at any time as an action, causing it to disappear. In either case, casting this spell again summons the same steed, restored to its hit point maximum.\n\nWhile your steed is within 1 mile of you, you can communicate with it telepathically.\n\nYou can't have more than one steed bonded by this spell at a time. As an action, you can release the steed from its bond at any time, causing it to disappear.","","",""],
["Find Traps",2,2,"1 action","120 feet","Instantaneous","VS","",0,0,[1, 2, 4],"You sense the presence of any trap within range that is within line of sight. A trap, for the purpose of this spell, includes anything that would inflict a sudden or unexpected effect you consider harmful or undesirable, which was specifically intended as such by its creator. Thus, the spell would sense an area affected by the alarm spell, a glyph of warding, or a mechanical pit trap, but it would not reveal a natural weakness in the floor, an unstable ceiling, or a hidden sinkhole.\n\nThis spell merely reveals that a trap is present. You don't learn the location of each trap, but you do learn the general nature of the danger posed by a trap you sense.","","",""],
["Flame Blade",2,4,"1 bonus action","Self","Up to 10 minutes","VSM","Leaf of sumac.",1,0,[2],"You evoke a fiery blade in your free hand. The blade is similar in size and shape to a scimitar, and it lasts for the duration. If you let go of the blade, it disappears, but you can evoke the blade again as a bonus action.\n\nYou can use your action to make a melee spell attack with the fiery blade. On a hit, the target takes 3d6 fire damage.\n\nThe flaming blade sheds bright light in a 10-foot radius and dim light for an additional 10 feet.","When you cast this spell using a spell slot of 4th level or higher, the damage increases by 1d6 for every two slot levels above 2nd.","Fire",""],
["Flaming Sphere",2,1,"1 action","60 feet","Up to 1 minute","VSM","A bit of tallow, a pinch of brimstone, and a dusting of powdered iron.",1,0,[2, 7],"A 5-foot-diameter sphere of fire appears in an unoccupied space of your choice within range and lasts for the duration. Any creature that ends its turn within 5 feet of the sphere must make a dexterity saving throw. The creature takes 2d6 fire damage on a failed save, or half as much damage on a successful one.\n\nAs a bonus action, you can move the sphere up to 30 feet. If you ram the sphere into a creature, that creature must make the saving throw against the sphere's damage, and the sphere stops moving this turn.\n\nWhen you move the sphere, you can direct it over barriers up to 5 feet tall and jump it across pits up to 10 feet wide. The sphere ignites flammable objects not being worn or carried, and it sheds bright light in a 20-foot radius and dim light for an additional 20 feet.","When you cast this spell using a spell slot of 3rd level or higher, the damage increases by 1d6 for each slot level above 2nd.","Fire",""],
["Gentle Repose",2,6,"1 action","Touch","10 days","VSM","A pinch of salt and one copper piece placed on each of the corpse's eyes, which must remain there for the duration.",0,1,[1, 7],"You touch a corpse or other remains. For the duration, the target is protected from decay and can't become undead.\n\nThe spell also effectively extends the time limit on raising the target from the dead, since days spent under the influence of this spell don't count against the time limit of spells such as raise dead.","","",""],
["Gust of Wind",2,4,"1 action","Self","Up to 1 minute","VSM","A legume seed.",1,0,[2, 5, 7],"A line of strong wind 60 feet long and 10 feet wide blasts from you in a direction you choose for the spell's duration. Each creature that starts its turn in the line must succeed on a strength saving throw or be pushed 15 feet away from you in a direction following the line.\n\nAny creature in the line must spend 2 feet of movement for every 1 foot it moves when moving closer to you.\n\nThe gust disperses gas or vapor, and it extinguishes candles, torches, and similar unprotected flames in the area. It causes protected flames, such as those of lanterns, to dance wildly and has a 50 percent chance to extinguish them.\n\nAs a bonus action on each of your turns before the spell ends, you can change the direction in which the line blasts from you.","","","STR"],
["Heat Metal",2,7,"1 action","60 feet","Up to 1 minute","VSM","A piece of iron and a flame.",1,0,[0, 2],"Choose a manufactured metal object, such as a metal weapon or a suit of heavy or medium metal armor, that you can see within range. You cause the object to glow red-hot. Any creature in physical contact with the object takes 2d8 fire damage when you cast the spell. Until the spell ends, you can use a bonus action on each of your subsequent turns to cause this damage again.\n\nIf a creature is holding or wearing the object and takes the damage from it, the creature must succeed on a constitution saving throw or drop the object if it can. If it doesn't drop the object, it has disadvantage on attack rolls and ability checks until the start of your next turn.","When you cast this spell using a spell slot of 3rd level or higher, the damage increases by 1d8 for each slot level above 2nd.","Fire","CON"],
["Hold Person",2,3,"1 action","60 feet","Up to 1 minute","VSM","A small, straight piece of iron.",1,0,[0, 1, 2, 5, 6, 7],"Choose a humanoid that you can see within range. The target must succeed on a wisdom saving throw or be paralyzed for the duration. At the end of each of its turns, the target can make another wisdom saving throw. On a success, the spell ends on the target.","When you cast this spell using a spell slot of 3rd level or higher, you can target one additional humanoid for each slot level above 2nd. The humanoids must be within 30 feet of each other when you target them.","","WIS"],
["Invisibility",2,5,"1 action","Touch","Up to 1 hour","VSM","An eyelash encased in gum arabic.",1,0,[0, 5, 6, 7],"A creature you touch becomes invisible until the spell ends. Anything the target is wearing or carrying is invisible as long as it is on the target's person. The spell ends for a target that attacks or casts a spell.","When you cast this spell using a spell slot of 3rd level or higher, you can target one additional creature for each slot level above 2nd.","",""],
["Knock",2,7,"1 action","60 feet","Instantaneous","V","",0,0,[0, 5, 7],"Choose an object that you can see within range. The object can be a door, a box, a chest, a set of manacles, a padlock, or another object that contains a mundane or magical means that prevents access.\n\nA target that is held shut by a mundane lock or that is stuck or barred becomes unlocked, unstuck, or unbarred. If the object has multiple locks, only one of them is unlocked.\n\nIf you choose a target that is held shut with arcane lock, that spell is suppressed for 10 minutes, during which time the target can be opened and shut normally.\n\nWhen you cast the spell, a loud knock, audible from as far away as 300 feet, emanates from the target object.","","",""],
["Lesser Restoration",2,0,"1 action","Touch","Instantaneous","VS","",0,0,[0, 1, 2, 3, 4],"You touch a creature and can end either one disease or one condition afflicting it. The condition can be blinded, deafened, paralyzed, or poisoned.","","",""],
["Levitate",2,7,"1 action","60 feet","Up to 10 minutes","VSM","Either a small leather loop or a piece of golden wire bent into a cup shape with a long shank on one end.",1,0,[5, 7],"One creature or object of your choice that you can see within range rises vertically, up to 20 feet, and remains suspended there for the duration. The spell can levitate a target that weighs up to 500 pounds. An unwilling creature that succeeds on a constitution saving throw is unaffected.\n\nThe target can move only by pushing or pulling against a fixed object or surface within reach (such as a wall or a ceiling), which allows it to move as if it were climbing. You can change the target's altitude by up to 20 feet in either direction on your turn. If you are the target, you can move up or down as part of your move. Otherwise, you can use your action to move the target, which must remain within the spell's range.\n\nWhen the spell ends, the target floats gently to the ground if it is still aloft.","","",""],
["Locate Animals or Plants",2,2,"1 action","Self","Instantaneous","VSM","A bit of fur from a bloodhound.",0,1,[0, 2, 4],"Describe or name a specific kind of beast or plant. Concentrating on the voice of nature in your surroundings, you learn the direction and distance to the closest creature or plant of that kind within 5 miles, if any are present.","","",""],
["Locate Object",2,2,"1 action","Self","Up to 10 minutes","VSM","A forked twig.",1,0,[0, 1, 2, 3, 4, 7],"Describe or name an object that is familiar to you. You sense the direction to the object's location, as long as that object is within 1,000 feet of you. If the object is in motion, you know the direction of its movement.\n\nThe spell can locate a specific object known to you, as long as you have seen it up close--within 30 feet--at least once. Alternatively, the spell can locate the nearest object of a particular kind, such as a certain kind of apparel, jewelry, furniture, tool, or weapon.\n\nThis spell can't locate an object if any thickness of lead, even a thin sheet, blocks a direct path between you and the object.","","",""],
["Magic Mouth",2,5,"1 minute","30 feet","Until dispelled","VSM","A honeycomb and jade dust of at least 10 inches, the spell consumes.",0,1,[0, 7],"You plant a message to an object in the range of the spell. The message is verbalized when the trigger conditions are met. Choose an object that you see, and that is not worn or carried by another creature. Then say the message, which should not exceed 25 words but listening can take up to 10 minutes. Finally, establish the circumstances that trigger the spell to deliver your message.\n\nWhen these conditions are satisfied, a magical mouth appears on the object and it articulates the message imitating your voice, the same tone used during implantation of the message. If the selected object has a mouth or something that approaches such as the mouth of a statue, the magic mouth come alive at this point, giving the illusion that the words come from the mouth of the object.\n\nWhen you cast this spell, you may decide that the spell ends when the message is delivered or it can persist and repeat the message whenever circumstances occur.\n\nThe triggering circumstance can be as general or as detailed as you like, though it must be based on visual or audible conditions that occur within 30 feet of the object. For example, you could instruct the mouth to speak when any creature moves within 30 feet of the object or when a silver bell rings within 30 feet of it.","","",""],
["Magic Weapon",2,7,"1 bonus action","Touch","Up to 1 hour","VS","",1,0,[3, 7],"You touch a nonmagical weapon. Until the spell ends, that weapon becomes a magic weapon with a +1 bonus to attack rolls and damage rolls.","When you cast this spell using a spell slot of 4th level or higher, the bonus increases to +2. When you use a spell slot of 6th level or higher, the bonus increases to +3.","",""],
["Mirror Image",2,5,"1 action","Self","1 minute","VS","",0,0,[5, 6, 7],"Three illusory duplicates of yourself appear in your space. Until the spell ends, the duplicates move with you and mimic your actions, shifting position so it's impossible to track which image is real. You can use your action to dismiss the illusory duplicates.\n\nEach time a creature targets you with an attack during the spell's duration, roll a d20 to determine whether the attack instead targets one of your duplicates.\n\nIf you have three duplicates, you must roll a 6 or higher to change the attack's target to a duplicate. With two duplicates, you must roll an 8 or higher. With one duplicate, you must roll an 11 or higher.\n\nA duplicate's AC equals 10 + your Dexterity modifier. If an attack hits a duplicate, the duplicate is destroyed. A duplicate can be destroyed only by an attack that hits it. It ignores all other damage and effects. The spell ends when all three duplicates are destroyed.\n\nA creature is unaffected by this spell if it can't see, if it relies on senses other than sight, such as blindsight, or if it can perceive illusions as false, as with truesight.","","",""],
["Misty Step",2,1,"1 bonus action","Self","Instantaneous","V","",0,0,[5, 6, 7],"Briefly surrounded by silvery mist, you teleport up to 30 feet to an unoccupied space that you can see.","","",""],
["Moonbeam",2,4,"1 action","120 feet","Up to 1 minute","VSM","Several seeds of any moonseed plant and a piece of opalescent feldspar.",1,0,[2],"A silvery beam of pale light shines down in a 5-foot radius, 40-foot-high cylinder centered on a point within range. Until the spell ends, dim light fills the cylinder.\n\nWhen a creature enters the spell's area for the first time on a turn or starts its turn there, it is engulfed in ghostly flames that cause searing pain, and it must make a constitution saving throw. It takes 2d10 radiant damage on a failed save, or half as much damage on a successful one.\n\nA shapechanger makes its saving throw with disadvantage. If it fails, it also instantly reverts to its original form and can't assume a different form until it leaves the spell's light.\n\nOn each of your turns after you cast this spell, you can use an action to move the beam 60 feet in any direction.","When you cast this spell using a spell slot of 3rd level or higher, the damage increases by 1dl0 for each slot level above 2nd.","Radiant","CON"],
["Pass Without Trace",2,0,"1 action","Self","Up to 1 hour","VSM","Ashes from a burned leaf of mistletoe and a sprig of spruce.",1,0,[2, 4],"A veil of shadows and silence radiates from you, masking you and your companions from detection. For the duration, each creature you choose within 30 feet of you (including you) has a +10 bonus to Dexterity (Stealth) checks and can't be tracked except by magical means. A creature that receives this bonus leaves behind no tracks or other traces of its passage.","","",""],
["Prayer of Healing",2,4,"10 minutes","30 feet","Instantaneous","V","",0,0,[1],"Up to six creatures of your choice that you can see within range each regain hit points equal to 2d8 + your spellcasting ability modifier. This spell has no effect on undead or constructs.","When you cast this spell using a spell slot of 3rd level or higher, the healing increases by 1d8 for each slot level above 2nd.","",""],
["Protection from Poison",2,0,"1 action","Touch","1 hour","VS","",0,0,[1, 2, 3, 4],"You touch a creature. If it is poisoned, you neutralize the poison. If more than one poison afflicts the target, you neutralize one poison that you know is present, or you neutralize one at random.\n\nFor the duration, the target has advantage on saving throws against being poisoned, and it has resistance to poison damage.","","",""],
["Ray of Enfeeblement",2,6,"1 action","60 feet","Up to 1 minute","VS","",1,0,[6, 7],"A black beam of enervating energy springs from your finger toward a creature within range. Make a ranged spell attack against the target. On a hit, the target deals only half damage with weapon attacks that use Strength until the spell ends.\n\nAt the end of each of the target's turns, it can make a constitution saving throw against the spell. On a success, the spell ends.","","","CON"],
["Rope Trick",2,7,"1 action","Touch","1 hour","VSM","Powdered corn extract and a twisted loop of parchment.",0,0,[7],"You touch a length of rope that is up to 60 feet long. One end of the rope then rises into the air until the whole rope hangs perpendicular to the ground. At the upper end of the rope, an invisible entrance opens to an extradimensional space that lasts until the spell ends.\n\nThe extradimensional space can be reached by climbing to the top of the rope. The space can hold as many as eight Medium or smaller creatures. The rope can be pulled into the space, making the rope disappear from view outside the space.\n\nAttacks and spells can't cross through the entrance into or out of the extradimensional space, but those inside can see out of it as if through a 3-foot-by-5-foot window centered on the rope.\n\nAnything inside the extradimensional space drops out when the spell ends.","","",""],
["Scorching Ray",2,4,"1 action","120 feet","Instantaneous","VS","",0,0,[5, 7],"You create three rays of fire and hurl them at targets within range. You can hurl them at one target or several.\n\nMake a ranged spell attack for each ray. On a hit, the target takes 2d6 fire damage.","When you cast this spell using a spell slot of 3rd level or higher, you create one additional ray for each slot level above 2nd.","Fire",""],
["See Invisibility",2,2,"1 action","Self","1 hour","VSM","A dash of talc and a small amount of silver powder.",0,0,[0, 5, 7],"For the duration of the spell, you see invisible creatures and objects as if they were visible, and you can see through Ethereal. The ethereal objects and creatures appear ghostly translucent.","","",""],
["Shatter",2,4,"1 action","60 feet","Instantaneous","VSM","A burst of mica.",0,0,[0, 5, 6, 7],"A sudden loud ringing noise, painfully intense, erupts from a point of your choice within range. Each creature in a 10-foot-radius sphere centered on that point must make a Constitution saving throw. A creature takes 3d8 thunder damage on a failed save, or half as much damage on a successful one. A creature made of inorganic material such as stone, crystal, or metal has disadvantage on this saving throw.\n\nA non-magical item that is not worn or carried also suffers damage if it is in the area of the spell.","When you cast this spell using a 3 or higher level spell slot, the damage of the spell increases by 1d8 for each level of higher spell slot 2.","Thunder","CON"],
["Silence",2,5,"1 action","120 feet","Up to 10 minutes","VS","",1,1,[0, 1, 4],"For the duration, no sound can be created within or pass through a 20-foot-radius sphere centered on a point you choose within range. Any creature or object entirely inside the sphere is immune to thunder damage, and creatures are deafened while entirely inside it.\n\nCasting a spell that includes a verbal component is impossible there.","","",""],
["Spider Climb",2,7,"1 action","Touch","Up to 1 hour","VSM","A drop of bitumen and a spider.",1,0,[5, 6, 7],"Until the spell ends, one willing creature you touch gains the ability to move up, down, and across vertical surfaces and upside down along ceilings, while leaving its hands free. The target also gains a climbing speed equal to its walking speed.","","",""],
["Spike Growth",2,7,"1 action","150 feet","Up to 10 minutes","VSM","Seven sharp thorns or seven small twigs, each sharpened to a point.",1,0,[2, 4],"The ground in a 20-foot radius centered on a point within range twists and sprouts hard spikes and thorns. The area becomes difficult terrain for the duration. When a creature moves into or within the area, it takes 2d4 piercing damage for every 5 feet it travels.\n\nThe transformation of the ground is camouflaged to look natural. Any creature that can't see the area at the time the spell is cast can make a Wisdom (Perception) check against your spell save DC to recognize the terrain as hazardous before entering it.","","",""],
["Spiritual Weapon",2,4,"1 bonus action","60 feet","1 minute","VS","",0,0,[1],"You create a floating, spectral weapon within range that lasts for the duration or until you cast this spell again. When you cast the spell, you can make a melee spell attack against a creature within 5 feet of the weapon. On a hit, the target takes force damage equal to 1d8 + your spellcasting ability modifier.\n\nAs a bonus action on your turn, you can move the weapon up to 20 feet and repeat the attack against a creature within 5 feet of it.\n\nThe weapon can take whatever form you choose. Clerics of deities who are associated with a particular weapon (as St. Cuthbert is known for his mace and Thor for his hammer) make this spell's effect resemble that weapon.","When you cast this spell using a spell slot of 3rd level or higher, the damage increases by 1d8 for every two slot levels above the 2nd.","Force",""],
["Suggestion",2,3,"1 action","30 feet","Up to 8 hours","VM","A snake's tongue and either a bit of honeycomb or a drop of sweet oil.",1,0,[0, 5, 6, 7],"You suggest a course of activity (limited to a sentence or two) and magically influence a creature you can see within range that can hear and understand you. Creatures that can't be charmed are immune to this effect. The suggestion must be worded in such a manner as to make the course of action sound reasonable. Asking the creature to stab itself, throw itself onto a spear, immolate itself, or do some other obviously harmful act ends the spell.\n\nThe target must make a wisdom saving throw. On a failed save, it pursues the course of action you described to the best of its ability. The suggested course of action can continue for the entire duration. If the suggested activity can be completed in a shorter time, the spell ends when the subject finishes what it was asked to do.\n\nYou can also specify conditions that will trigger a special activity during the duration. For example, you might suggest that a knight give her warhorse to the first beggar she meets. If the condition isn't met before the spell expires, the activity isn't performed.\n\nIf you or any of your companions damage the target, the spell ends.","","","WIS"],
["Warding Bond",2,0,"1 action","Touch","1 hour","VSM","A pair of platinum rings worth at least 50gp each, which you and the target must wear for the duration.",0,0,[1],"This spell wards a willing creature you touch and creates a mystic connection between you and the target until the spell ends. While the target is within 60 feet of you, it gains a +1 bonus to AC and saving throws, and it has resistance to all damage. Also, each time it takes damage, you take the same amount of damage.\n\nThe spell ends if you drop to 0 hit points or if you and the target become separated by more than 60 feet.\n\nIt also ends if the spell is cast again on either of the connected creatures. You can also dismiss the spell as an action.","","",""],
["Web",2,1,"1 action","60 feet","Up to 1 hour","VSM","A bit of spiderweb.",1,0,[5, 7],"You conjure a mass of thick, sticky webbing at a point of your choice within range. The webs fill a 20-foot cube from that point for the duration. The webs are difficult terrain and lightly obscure their area.\n\nIf the webs aren't anchored between two solid masses (such as walls or trees) or layered across a floor, wall, or ceiling, the conjured web collapses on itself, and the spell ends at the start of your next turn. Webs layered over a flat surface have a depth of 5 feet.\n\nEach creature that starts its turn in the webs or that enters them during its turn must make a dexterity saving throw. On a failed save, the creature is restrained as long as it remains in the webs or until it breaks free.\n\nA creature restrained by the webs can use its action to make a Strength check against your spell save DC. If it succeeds, it is no longer restrained.\n\nThe webs are flammable. Any 5-foot cube of webs exposed to fire burns away in 1 round, dealing 2d4 fire damage to any creature that starts its turn in the fire.","","",""],
["Zone of Truth",2,3,"1 action","60 feet","10 minutes","VS","",0,0,[0, 1, 3],"You create a magical zone that guards against deception in a 15-foot-radius sphere centered on a point of your choice within range. Until the spell ends, a creature that enters the spell's area for the first time on a turn or starts its turn there must make a Charisma saving throw. On a failed save, a creature can't speak a deliberate lie while in the radius. You know whether each creature succeeds or fails on its saving throw.\n\nAn affected creature is aware of the spell and can thus avoid answering questions to which it would normally respond with a lie. Such a creature can remain evasive in its answers as long as it remains within the boundaries of the truth.","","",""],
["Animate Dead",3,6,"1 minute","10 feet","Instantaneous","VSM","A drop of blood, a piece of flesh, and a pinch of bone dust.",0,0,[1, 7],"This spell creates an undead servant. Choose a pile of bones or a corpse of a Medium or Small humanoid within range. Your spell imbues the target with a foul mimicry of life, raising it as an undead creature. The target becomes a skeleton if you chose bones or a zombie if you chose a corpse (the GM has the creature's game statistics).\n\nOn each of your turns, you can use a bonus action to mentally command any creature you made with this spell if the creature is within 60 feet of you (if you control multiple creatures, you can command any or all of them at the same time, issuing the same command to each one). You decide what action the creature will take and where it will move during its next turn, or you can issue a general command, such as to guard a particular chamber or corridor. If you issue no commands, the creature only defends itself against hostile creatures. Once given an order, the creature continues to follow it until its task is complete.\n\nThe creature is under your control for 24 hours, after which it stops obeying any command you've given it. To maintain control of the creature for another 24 hours, you must cast this spell on the creature again before the current 24-hour period ends. This use of the spell reasserts your control over up to four creatures you have animated with this spell, rather than animating a new one.","When you cast this spell using a spell slot of 4th level or higher, you animate or reassert control over two additional undead creatures for each slot level above 3rd. Each of the creatures must come from a different corpse or pile of bones.","",""],
["Beacon of Hope",3,0,"1 action","30 feet","Up to 1 minute","VS","",1,0,[1],"This spell bestows hope and vitality. Choose any number of creatures within range. For the duration, each target has advantage on wisdom saving throws and death saving throws, and regains the maximum number of hit points possible from any healing.","","",""],
["Bestow Curse",3,6,"1 action","Touch","Up to 1 minute","VS","",1,0,[0, 1, 7],"You touch a creature, and that creature must succeed on a wisdom saving throw or become cursed for the duration of the spell. When you cast this spell, choose the nature of the curse from the following options:\n\n- Choose one ability score. While cursed, the target has disadvantage on ability checks and saving throws made with that ability score.\n\n- While cursed, the target has disadvantage on attack rolls against you.\n\n- While cursed, the target must make a wisdom saving throw at the start of each of its turns. If it fails, it wastes its action that turn doing nothing.\n\n- While the target is cursed, your attacks and spells deal an extra 1d8 necrotic damage to the target.\n\nA remove curse spell ends this effect. At the GM's option, you may choose an alternative curse effect, but it should be no more powerful than those described above. The GM has final say on such a curse's effect.","If you cast this spell using a spell slot of 4th level or higher, the duration is concentration, up to 10 minutes. If you use a spell slot of 5th level or higher, the duration is 8 hours. If you use a spell slot of 7th level or higher, the duration is 24 hours. If you use a 9th level spell slot, the spell lasts until it is dispelled. Using a spell slot of 5th level or higher grants a duration that doesn't require concentration.","","WIS"],
["Blink",3,7,"1 action","Self","1 minute","VS","",0,0,[5, 7],"Roll a d20 at the end of each of your turns for the duration of the spell. On a roll of 11 or higher, you vanish from your current plane of existence and appear in the Ethereal Plane (the spell fails and the casting is wasted if you were already on that plane). At the start of your next turn, and when the spell ends if you are on the Ethereal Plane, you return to an unoccupied space of your choice that you can see within 10 feet of the space you vanished from. If no unoccupied space is available within that range, you appear in the nearest unoccupied space (chosen at random if more than one space is equally near). You can dismiss this spell as an action.\n\nWhile on the Ethereal Plane, you can see and hear the plane you originated from, which is cast in shades of gray, and you can't see anything there more than 60 feet away. You can only affect and be affected by other creatures on the Ethereal Plane. Creatures that aren't there can't perceive you or interact with you, unless they have the ability to do so.","","",""],
["Call Lightning",3,1,"1 action","120 feet","Up to 10 minutes","VS","",1,0,[2],"A storm cloud appears in the shape of a cylinder that is 10 feet tall with a 60-foot radius, centered on a point you can see 100 feet directly above you. The spell fails if you can't see a point in the air where the storm cloud could appear (for example, if you are in a room that can't accommodate the cloud).\n\nWhen you cast the spell, choose a point you can see within range. A bolt of lightning flashes down from the cloud to that point. Each creature within 5 feet of that point must make a dexterity saving throw. A creature takes 3d10 lightning damage on a failed save, or half as much damage on a successful one. On each of your turns until the spell ends, you can use your action to call down lightning in this way again, targeting the same point or a different one.\n\nIf you are outdoors in stormy conditions when you cast this spell, the spell gives you control over the existing storm instead of creating a new one. Under such conditions, the spell's damage increases by 1d10.","When you cast this spell using a spell slot of 4th or higher level, the damage increases by 1d10 for each slot level above 3rd.","Lightning",""],
["Clairvoyance",3,2,"10 minutes","1 mile","Up to 10 minutes","VSM","A focus worth at least 100gp, either a jeweled horn for hearing or a glass eye for seeing.",1,0,[0, 1, 5, 7],"You create an invisible sensor within range in a location familiar to you (a place you have visited or seen before) or in an obvious location that is unfamiliar to you (such as behind a door, around a corner, or in a grove of trees). The sensor remains in place for the duration, and it can't be attacked or otherwise interacted with.\n\nWhen you cast the spell, you choose seeing or hearing. You can use the chosen sense through the sensor as if you were in its space. As your action, you can switch between seeing and hearing.\n\nA creature that can see the sensor (such as a creature benefiting from see invisibility or truesight) sees a luminous, intangible orb about the size of your fist.","","",""],
["Conjure Animals",3,1,"1 action","60 feet","Up to 1 hour","VS","",1,0,[2, 4],"You summon fey spirits that take the form of beasts and appear in unoccupied spaces that you can see within range. Choose one of the following options for what appears:\n\n- One beast of challenge rating 2 or lower\n\n- Two beasts of challenge rating 1 or lower\n\n- Four beasts of challenge rating 1/2 or lower\n\n- Eight beasts of challenge rating 1/4 or lower\n\n- Each beast is also considered fey, and it disappears when it drops to 0 hit points or when the spell ends.\n\nThe summoned creatures are friendly to you and your companions. Roll initiative for the summoned creatures as a group, which has its own turns. They obey any verbal commands that you issue to them (no action required by you). If you don't issue any commands to them, they defend themselves from hostile creatures, but otherwise take no actions.\n\nThe GM has the creatures' statistics.","When you cast this spell using certain higher-level spell slots, you choose one of the summoning options above, and more creatures appear: twice as many with a 5th-level slot, three times as many with a 7th-level.","",""],
["Counterspell",3,0,"1 reaction","60 feet","Instantaneous","S","",0,0,[5, 6, 7],"You attempt to interrupt a creature in the process of casting a spell. If the creature is casting a spell of 3rd level or lower, its spell fails and has no effect. If it is casting a spell of 4th level or higher, make an ability check using your spellcasting ability. The DC equals 10 + the spell's level. On a success, the creature's spell fails and has no effect.","When you cast this spell using a spell slot of 4th level or higher, the interrupted spell has no effect if its level is less than or equal to the level of the spell slot you used.","",""],
["Create Food and Water",3,1,"1 action","30 feet","Instantaneous","VS","",0,0,[1, 2, 3],"You create 45 pounds of food and 30 gallons of water on the ground or in containers within range, enough to sustain up to fifteen humanoids or five steeds for 24 hours. The food is bland but nourishing, and spoils if uneaten after 24 hours. The water is clean and doesn't go bad.","","",""],
["Daylight",3,4,"1 action","60 feet","1 hour","VS","",0,0,[1, 2, 3, 4, 5],"A 60-foot-radius sphere of light spreads out from a point you choose within range. The sphere is bright light and sheds dim light for an additional 60 feet.\n\nIf you chose a point on an object you are holding or one that isn't being worn or carried, the light shines from the object and moves with it. Completely covering the affected object with an opaque object, such as a bowl or a helm, blocks the light.\n\nIf any of this spell's area overlaps with an area of darkness created by a spell of 3rd level or lower, the spell that created the darkness is dispelled.","","",""],
["Dispel Magic",3,0,"1 action","120 feet","Instantaneous","VS","",0,0,[0, 1, 2, 3, 5, 6, 7],"Choose one creature, object, or magical effect within range. Any spell of 3rd level or lower on the target ends. For each spell of 4th level or higher on the target, make an ability check using your spellcasting ability. The DC equals 10 + the spell's level. On a successful check, the spell ends.","When you cast this spell using a spell slot of 4th level or higher, you automatically end the effects of a spell on the target if the spell's level is equal to or less than the level of the spell slot you used.","",""],
["Fear",3,5,"1 action","Self","Up to 1 minute","VSM","A white feather or the heart of a hen.",1,0,[0, 5, 6, 7],"You project a phantasmal image of a creature's worst fears. Each creature in a 30-foot cone must succeed on a wisdom saving throw or drop whatever it is holding and become frightened for the duration.\n\nWhile frightened by this spell, a creature must take the Dash action and move away from you by the safest available route on each of its turns, unless there is nowhere to move. If the creature ends its turn in a location where it doesn't have line of sight to you, the creature can make a wisdom saving throw. On a successful save, the spell ends for that creature.","","","WIS"],
["Fireball",3,4,"1 action","150 feet","Instantaneous","VSM","A tiny ball of bat guano and sulfur.",0,0,[5, 7],"A bright streak flashes from your pointing finger to a point you choose within range and then blossoms with a low roar into an explosion of flame. Each creature in a 20-foot-radius sphere centered on that point must make a dexterity saving throw. A target takes 8d6 fire damage on a failed save, or half as much damage on a successful one.\n\nThe fire spreads around corners. It ignites flammable objects in the area that aren't being worn or carried.","When you cast this spell using a spell slot of 4th level or higher, the damage increases by 1d6 for each slot level above 3rd.","Fire","DEX"],
["Fly",3,7,"1 action","Touch","Up to 10 minutes","VSM","A wing feather from any bird.",1,0,[5, 6, 7],"You touch a willing creature. The target gains a flying speed of 60 feet for the duration. When the spell ends, the target falls if it is still aloft, unless it can stop the fall.","When you cast this spell using a spell slot of 4th level or higher, you can target one additional creature for each slot level above 3rd.","",""],
["Gaseous Form",3,7,"1 action","Touch","Up to 1 hour","VSM","A bit of gauze and a wisp of smoke.",1,0,[5, 6, 7],"You transform a willing creature you touch, along with everything it's wearing and carrying, into a misty cloud for the duration. The spell ends if the creature drops to 0 hit points. An incorporeal creature isn't affected.\n\nWhile in this form, the target's only method of movement is a flying speed of 10 feet. The target can enter and occupy the space of another creature. The target has resistance to nonmagical damage, and it has advantage on Strength, Dexterity, and constitution saving throws. The target can pass through small holes, narrow openings, and even mere cracks, though it treats liquids as though they were solid surfaces. The target can't fall and remains hovering in the air even when stunned or otherwise incapacitated.\n\nWhile in the form of a misty cloud, the target can't talk or manipulate objects, and any objects it was carrying or holding can't be dropped, used, or otherwise interacted with. The target can't attack or cast spells.","","",""],
["Glyph of Warding",3,0,"1 hour","Touch","Until dispelled","VSM","Incense and powdered diamond worth at least 200 gp, which the spell consumes.",0,0,[0, 1, 7],"When you cast this spell, you inscribe a glyph that harms other creatures, either upon a surface (such as a table or a section of floor or wall) or within an object that can be closed (such as a book, a scroll, or a treasure chest) to conceal the glyph. If you choose a surface, the glyph can cover an area of the surface no larger than 10 feet in diameter. If you choose an object, that object must remain in its place; if the object is moved more than 10 feet from where you cast this spell, the glyph is broken, and the spell ends without being triggered.\n\nThe glyph is nearly invisible and requires a successful Intelligence (Investigation) check against your spell save DC to be found.\n\nYou decide what triggers the glyph when you cast the spell. For glyphs inscribed on a surface, the most typical triggers include touching or standing on the glyph, removing another object covering the glyph, approaching within a certain distance of the glyph, or manipulating the object on which the glyph is inscribed. For glyphs inscribed within an object, the most common triggers include opening that object, approaching within a certain distance of the object, or seeing or reading the glyph. Once a glyph is triggered, this spell ends.\n\nYou can further refine the trigger so the spell activates only under certain circumstances or according to physical characteristics (such as height or weight), creature kind (for example, the ward could be set to affect aberrations or drow), or alignment. You can also set conditions for creatures that don't trigger the glyph, such as those who say a certain password.\n\nWhen you inscribe the glyph, choose *explosive runes* or a *spell glyph*.\n\n***Explosive Runes.*** When triggered, the glyph erupts with magical energy in a 20-foot-radius sphere centered on the glyph. The sphere spreads around corners. Each creature in the area must make a Dexterity saving throw. A creature takes 5d8 acid, cold, fire, lightning, or thunder damage on a failed saving throw (your choice when you create the glyph), or half as much damage on a successful one.\n\n***Spell Glyph.*** You can store a prepared spell of 3rd level or lower in the glyph by casting it as part of creating the glyph. The spell must target a single creature or an area. The spell being stored has no immediate effect when cast in this way. When the glyph is triggered, the stored spell is cast. If the spell has a target, it targets the creature that triggered the glyph. If the spell affects an area, the area is centered on that creature. If the spell summons hostile creatures or creates harmful objects or traps, they appear as close as possible to the intruder and attack it. If the spell requires concentration, it lasts until the end of its full duration.","When you cast this spell using a spell slot of 4th level or higher, the damage of an explosive runes glyph increases by 1d8 for each slot level above 3rd. If you create a spell glyph, you can store any spell of up to the same level as the slot you use for the glyph of warding.","",""],
["Haste",3,7,"1 action","30 feet","Up to 1 minute","VSM","A shaving of licorice root.",1,0,[5, 7],"Choose a willing creature that you can see within range. Until the spell ends, the target's speed is doubled, it gains a +2 bonus to AC, it has advantage on dexterity saving throws, and it gains an additional action on each of its turns. That action can be used only to take the Attack (one weapon attack only), Dash, Disengage, Hide, or Use an Object action.\n\nWhen the spell ends, the target can't move or take actions until after its next turn, as a wave of lethargy sweeps over it.","","",""],
["Hypnotic Pattern",3,5,"1 action","120 feet","Up to 1 minute","SM","A glowing stick of incense or a crystal vial filled with phosphorescent material.",1,0,[0, 5, 6, 7],"You create a twisting pattern of colors that weaves through the air inside a 30-foot cube within range. The pattern appears for a moment and vanishes. Each creature in the area who sees the pattern must make a wisdom saving throw. On a failed save, the creature becomes charmed for the duration. While charmed by this spell, the creature is incapacitated and has a speed of 0.\n\nThe spell ends for an affected creature if it takes any damage or if someone else uses an action to shake the creature out of its stupor.","","","WIS"],
["Lightning Bolt",3,4,"1 action","Self","Instantaneous","VSM","A bit of fur and a rod of amber, crystal, or glass.",0,0,[5, 7],"A stroke of lightning forming a line 100 feet long and 5 feet wide blasts out from you in a direction you choose. Each creature in the line must make a dexterity saving throw. A creature takes 8d6 lightning damage on a failed save, or half as much damage on a successful one.\n\nThe lightning ignites flammable objects in the area that aren't being worn or carried.","When you cast this spell using a spell slot of 4th level or higher, the damage increases by 1d6 for each slot level above 3rd.","Lightning","DEX"],
["Magic Circle",3,0,"1 minute","10 feet","1 hour","VSM","Holy water or powdered silver and iron worth at least 100 gp, which the spell consumes.",0,0,[1, 3, 6, 7],"You create a 10-foot radius, 20-foot-tall cylinder of magical energy centered on a point on the ground that you can see within range. Glowing runes appear whenever the cylinder intersects with the floor or other surface.\n\nChoose one or more of the following types of creatures: celestials, elementals, fey, fiends, or undead. The circle affects a creature of the chosen type in the following ways:\n\n- The creature can't willingly enter the cylinder by nonmagical means. If the creature tries to use teleportation or interplanar travel to do so, it must first succeed on a charisma saving throw.\n\n- The creature has disadvantage on attack rolls against targets within the cylinder.\n\n- Targets within the cylinder can't be charmed, frightened, or possessed by the creature.\n\nWhen you cast this spell, you can elect to cause its magic to operate in the reverse direction, preventing a creature of the specified type from leaving the cylinder and protecting targets outside it.","When you cast this spell using a spell slot of 4th level or higher, the duration increases by 1 hour for each slot level above 3rd.","","CHA"],
["Major Image",3,5,"1 action","120 feet","Up to 10 minutes","VSM","A bit of fleece.",1,0,[0, 5, 6, 7],"You create the image of an object, a creature, or some other visible phenomenon that is no larger than a 20-foot cube. The image appears at a spot that you can see within range and lasts for the duration. It seems completely real, including sounds, smells, and temperature appropriate to the thing depicted. You can't create sufficient heat or cold to cause damage, a sound loud enough to deal thunder damage or deafen a creature, or a smell that might sicken a creature (like a troglodyte's stench).\n\nAs long as you are within range of the illusion, you can use your action to cause the image to move to any other spot within range. As the image changes location, you can alter its appearance so that its movements appear natural for the image. For example, if you create an image of a creature and move it, you can alter the image so that it appears to be walking. Similarly, you can cause the illusion to make different sounds at different times, even making it carry on a conversation, for example.\n\nPhysical interaction with the image reveals it to be an illusion, because things can pass through it. A creature that uses its action to examine the image can determine that it is an illusion with a successful Intelligence (Investigation) check against your spell save DC. If a creature discerns the illusion for what it is, the creature can see through the image, and its other sensory qualities become faint to the creature.","When you cast this spell using a spell slot of 6th level or higher, the spell lasts until dispelled, without requiring your concentration.","",""],
["Mass Healing Word",3,4,"1 bonus action","60 feet","Instantaneous","V","",0,0,[1],"As you call out words of restoration, up to six creatures of your choice that you can see within range regain hit points equal to 1d4 + your spellcasting ability modifier. This spell has no effect on undead or constructs.","When you cast this spell using a spell slot of 4th level or higher, the healing increases by 1d4 for each slot level above 3rd.","",""],
["Meld Into Stone",3,7,"1 action","Touch","8 hours","VS","",0,1,[1],"You step into a stone object or surface large enough to fully contain your body, melding yourself and all the equipment you carry with the stone for the duration. Using your movement, you step into the stone at a point you can touch. Nothing of your presence remains visible or otherwise detectable by nonmagical senses.\n\nWhile merged with the stone, you can't see what occurs outside it, and any Wisdom (Perception) checks you make to hear sounds outside it are made with disadvantage. You remain aware of the passage of time and can cast spells on yourself while merged in the stone. You can use your movement to leave the stone where you entered it, which ends the spell. You otherwise can't move.\n\nMinor physical damage to the stone doesn't harm you, but its partial destruction or a change in its shape (to the extent that you no longer fit within it) expels you and deals 6d6 bludgeoning damage to you. The stone's complete destruction (or transmutation into a different substance) expels you and deals 50 bludgeoning damage to you. If expelled, you fall prone in an unoccupied space closest to where you first entered.","","",""],
["Nondetection",3,0,"1 action","Touch","8 hours","VSM","A pinch of diamond dust worth 25 gp sprinkled over the target, which the spell consumes.",0,0,[0, 4, 7],"For the duration, you hide a target that you touch from divination magic. The target can be a willing creature or a place or an object no larger than 10 feet in any dimension. The target can't be targeted by any divination magic or perceived through magical scrying sensors.","","",""],
["Phantom Steed",3,5,"1 minute","30 feet","1 hour","VS","",0,1,[7],"A Large quasi-real, horselike creature appears on the ground in an unoccupied space of your choice within range. You decide the creature's appearance, but it is equipped with a saddle, bit, and bridle. Any of the equipment created by the spell vanishes in a puff of smoke if it is carried more than 10 feet away from the steed.\n\nFor the duration, you or a creature you choose can ride the steed. The creature uses the statistics for a riding horse, except it has a speed of 100 feet and can travel 10 miles in an hour, or 13 miles at a fast pace. When the spell ends, the steed gradually fades, giving the rider 1 minute to dismount. The spell ends if you use an action to dismiss it or if the steed takes any damage.","","",""],
["Plant Growth",3,7,"1 action","150 feet","Instantaneous","VS","",0,0,[0, 2, 4],"This spell channels vitality into plants within a specific area. There are two possible uses for the spell, granting either immediate or long-term benefits.\n\nIf you cast this spell using 1 action, choose a point within range. All normal plants in a 100-foot radius centered on that point become thick and overgrown. A creature moving through the area must spend 4 feet of movement for every 1 foot it moves.\n\nYou can exclude one or more areas of any size within the spell's area from being affected.\n\nIf you cast this spell over 8 hours, you enrich the land. All plants in a half-mile radius centered on a point within range become enriched for 1 year. The plants yield twice the normal amount of food when harvested.","","",""],
["Protection From Energy",3,0,"1 action","Touch","Up to 1 hour","VS","",1,0,[1, 2, 4, 5, 7],"For the duration, the willing creature you touch has resistance to one damage type of your choice: acid, cold, fire, lightning, or thunder.","","",""],
["Remove Curse",3,0,"1 action","Touch","Instantaneous","VS","",0,0,[1, 3, 6, 7],"At your touch, all curses affecting one creature or object end. If the object is a cursed magic item, its curse remains, but the spell breaks its owner's attunement to the object so it can be removed or discarded.","","",""],
["Revivify",3,1,"1 action","Touch","Instantaneous","VSM","Diamonds worth 300gp, which the spell consumes.",0,0,[1, 3],"You touch a creature that has died within the last minute. That creature returns to life with 1 hit point. This spell can't return to life a creature that has died of old age, nor can it restore any missing body parts.","","",""],
["Sending",3,4,"1 action","Unlimited","1 round","VSM","A short piece of fine copper wire.",0,0,[0, 1, 7],"You send a short message of twenty-five words or less to a creature with which you are familiar. The creature hears the message in its mind, recognizes you as the sender if it knows you, and can answer in a like manner immediately. The spell enables creatures with Intelligence scores of at least 1 to understand the meaning of your message.\n\nYou can send the message across any distance and even to other planes of existence, but if the target is on a different plane than you, there is a 5 percent chance that the message doesn't arrive.","","",""],
["Sleet Storm",3,1,"1 action","150 feet","Up to 1 minute","VSM","A pinch of dust and a few drops of water.",1,0,[2, 5, 7],"Until the spell ends, freezing rain and sleet fall in a 20-foot-tall cylinder with a 40-foot radius centered on a point you choose within range. The area is heavily obscured, and exposed flames in the area are doused.\n\nThe ground in the area is covered with slick ice, making it difficult terrain. When a creature enters the spell's area for the first time on a turn or starts its turn there, it must make a dexterity saving throw. On a failed save, it falls prone.\n\nIf a creature is concentrating in the spell's area, the creature must make a successful constitution saving throw against your spell save DC or lose concentration.","","",""],
["Slow",3,7,"1 action","120 feet","Up to 1 minute","VSM","A drop of molasses.",1,0,[5, 7],"You alter time around up to six creatures of your choice in a 40-foot cube within range. Each target must succeed on a wisdom saving throw or be affected by this spell for the duration.\n\nAn affected target's speed is halved, it takes a -2 penalty to AC and dexterity saving throws, and it can't use reactions. On its turn, it can use either an action or a bonus action, not both. Regardless of the creature's abilities or magic items, it can't make more than one melee or ranged attack during its turn.\n\nIf the creature attempts to cast a spell with a casting time of 1 action, roll a d20. On an 11 or higher, the spell doesn't take effect until the creature's next turn, and the creature must use its action on that turn to complete the spell. If it can't, the spell is wasted.\n\nA creature affected by this spell makes another wisdom saving throw at the end of its turn. On a successful save, the effect ends for it.","","","WIS"],
["Speak with Dead",3,6,"1 action","10 feet","10 minutes","VSM","Burning incense.",0,0,[0, 1],"You grant the semblance of life and intelligence to a corpse of your choice within range, allowing it to answer the questions you pose. The corpse must still have a mouth and can't be undead. The spell fails if the corpse was the target of this spell within the last 10 days.\n\nUntil the spell ends, you can ask the corpse up to five questions. The corpse knows only what it knew in life, including the languages it knew. Answers are usually brief, cryptic, or repetitive, and the corpse is under no compulsion to offer a truthful answer if you are hostile to it or it recognizes you as an enemy. This spell doesn't return the creature's soul to its body, only its animating spirit. Thus, the corpse can't learn new information, doesn't comprehend anything that has happened since it died, and can't speculate about future events.","","",""],
["Speak with Plants",3,7,"1 action","Self","10 minutes","VS","",0,0,[0, 2, 4],"You imbue plants within 30 feet of you with limited sentience and animation, giving them the ability to communicate with you and follow your simple commands. You can question plants about events in the spell's area within the past day, gaining information about creatures that have passed, weather, and other circumstances.\n\nYou can also turn difficult terrain caused by plant growth (such as thickets and undergrowth) into ordinary terrain that lasts for the duration. Or you can turn ordinary terrain where plants are present into difficult terrain that lasts for the duration, causing vines and branches to hinder pursuers, for example.\n\nPlants might be able to perform other tasks on your behalf, at the GM's discretion. The spell doesn't enable plants to uproot themselves and move about, but they can freely move branches, tendrils, and stalks.\n\nIf a plant creature is in the area, you can communicate with it as if you shared a common language, but you gain no magical ability to influence it.\n\nThis spell can cause the plants created by the entangle spell to release a restrained creature.","","",""],
["Spirit Guardians",3,1,"1 action","Self","Up to 10 minutes","VSM","A holy symbol.",1,0,[1],"You call forth spirits to protect you. They flit around you to a distance of 15 feet for the duration. If you are good or neutral, their spectral form appears angelic or fey (your choice). If you are evil, they appear fiendish.\n\nWhen you cast this spell, you can designate any number of creatures you can see to be unaffected by it. An affected creature's speed is halved in the area, and when the creature enters the area for the first time on a turn or starts its turn there, it must make a wisdom saving throw. On a failed save, the creature takes 3d8 radiant damage (if you are good or neutral) or 3d8 necrotic damage (if you are evil). On a successful save, the creature takes half as much damage.","When you cast this spell using a spell slot of 4th level or higher, the damage increases by 1d8 for each slot level above 3rd.","",""],
["Stinking Cloud",3,1,"1 action","90 feet","Up to 1 minute","VSM","A rotten egg or several skunk cabbage leaves.",1,0,[0, 5, 7],"You create a 20-foot-radius sphere of yellow, nauseating gas centered on a point within range. The cloud spreads around corners, and its area is heavily obscured. The cloud lingers in the air for the duration.\n\nEach creature that is completely within the cloud at the start of its turn must make a constitution saving throw against poison. On a failed save, the creature spends its action that turn retching and reeling. Creatures that don't need to breathe or are immune to poison automatically succeed on this saving throw.\n\nA moderate wind (at least 10 miles per hour) disperses the cloud after 4 rounds. A strong wind (at least 20 miles per hour) disperses it after 1 round.","","","CON"],
["Tiny Hut",3,4,"1 minute","Self","8 hours","VSM","A small crystal bead.",0,1,[0, 7],"A 10-foot-radius immobile dome of force springs into existence around and above you and remains stationary for the duration. The spell ends if you leave its area.\n\nNine creatures of Medium size or smaller can fit inside the dome with you. The spell fails if its area includes a larger creature or more than nine creatures. Creatures and objects within the dome when you cast this spell can move through it freely. All other creatures and objects are barred from passing through it. Spells and other magical effects can't extend through the dome or be cast through it. The atmosphere inside the space is comfortable and dry, regardless of the weather outside.\n\nUntil the spell ends, you can command the interior to become dimly lit or dark. The dome is opaque from the outside, of any color you choose, but it is transparent from the inside.","","",""],
["Tongues",3,2,"1 action","Touch","1 hour","VM","A small clay model of a ziggurat.",0,0,[0, 1, 5, 6, 7],"This spell grants the creature you touch the ability to understand any spoken language it hears. Moreover, when the target speaks, any creature that knows at least one language and can hear the target understands what it says.","","",""],
["Vampiric Touch",3,6,"1 action","Self","Up to 1 minute","VS","",1,0,[6, 7],"The touch of your shadow-wreathed hand can siphon life force from others to heal your wounds. Make a melee spell attack against a creature within your reach. On a hit, the target takes 3d6 necrotic damage, and you regain hit points equal to half the amount of necrotic damage dealt. Until the spell ends, you can make the attack again on each of your turns as an action.","When you cast this spell using a spell slot of 4th level or higher, the damage increases by 1d6 for each slot level above 3rd.","Necrotic",""],
["Water Breathing",3,7,"1 action","30 feet","24 hours","VSM","A short piece of reed or straw.",0,1,[2, 4, 5, 7],"This spell gives a maximum of ten willing creatures within range and you can see, the ability to breathe underwater until the end of its term. Affected creatures also retain their normal breathing pattern.","","",""],
["Water Walk",3,7,"1 action","30 feet","1 hour","VSM","A piece of cork.",0,1,[1, 2, 4, 5],"This spell grants the ability to move across any liquid surface--such as water, acid, mud, snow, quicksand, or lava--as if it were harmless solid ground (creatures crossing molten lava can still take damage from the heat). Up to ten willing creatures you can see within range gain this ability for the duration.\n\nIf you target a creature submerged in a liquid, the spell carries the target to the surface of the liquid at a rate of 60 feet per round.","","",""],
["Wind Wall",3,4,"1 action","120 feet","Up to 1 minute","VSM","A tiny fan and a feather of exotic origin.",1,0,[2, 4],"A wall of strong wind rises from the ground at a point you choose within range. You can make the wall up to 50 feet long, 15 feet high, and 1 foot thick. You can shape the wall in any way you choose so long as it makes one continuous path along the ground. The wall lasts for the duration.\n\nWhen the wall appears, each creature within its area must make a strength saving throw. A creature takes 3d8 bludgeoning damage on a failed save, or half as much damage on a successful one.\n\nThe strong wind keeps fog, smoke, and other gases at bay. Small or smaller flying creatures or objects can't pass through the wall. Loose, lightweight materials brought into the wall fly upward. Arrows, bolts, and other ordinary projectiles launched at targets behind the wall are deflected upward and automatically miss. (Boulders hurled by giants or siege engines, and similar projectiles, are unaffected.) Creatures in gaseous form can't pass through it.","","Bludgeoning","STR"],
["Arcane Eye",4,2,"1 action","30 feet","Up to 1 hour","VSM","A bit of bat fur.",1,0,[1, 7],"You create an invisible, magical eye within range that hovers in the air for the duration.\n\nYou mentally receive visual information from the eye, which has normal vision and darkvision out to 30 feet. The eye can look in every direction.\n\nAs an action, you can move the eye up to 30 feet in any direction. There is no limit to how far away from you the eye can move, but it can't enter another plane of existence. A solid barrier blocks the eye's movement, but the eye can pass through an opening as small as 1 inch in diameter.","","",""],
["Banishment",4,0,"1 action","60 feet","Up to 1 minute","VSM","An item distasteful to the target.",1,0,[1, 3, 5, 6, 7],"You attempt to send one creature that you can see within range to another plane of existence. The target must succeed on a charisma saving throw or be banished.\n\nIf the target is native to the plane of existence you're on, you banish the target to a harmless demiplane. While there, the target is incapacitated. The target remains there until the spell ends, at which point the target reappears in the space it left or in the nearest unoccupied space if that space is occupied.\n\nIf the target is native to a different plane of existence than the one you're on, the target is banished with a faint popping noise, returning to its home plane. If the spell ends before 1 minute has passed, the target reappears in the space it left or in the nearest unoccupied space if that space is occupied. Otherwise, the target doesn't return.","When you cast this spell using a spell slot of 5th level or higher, you can target one additional creature for each slot level above 4th.","","CHA"],
["Black Tentacles",4,1,"1 action","90 feet","Up to 1 minute","VSM","A piece of tentacle from a giant octopus or a giant squid",1,0,[7],"Squirming, ebony tentacles fill a 20-foot square on ground that you can see within range. For the duration, these tentacles turn the ground in the area into difficult terrain.\n\nWhen a creature enters the affected area for the first time on a turn or starts its turn there, the creature must succeed on a Dexterity saving throw or take 3d6 bludgeoning damage and be restrained by the tentacles until the spell ends. A creature that starts its turn in the area and is already restrained by the tentacles takes 3d6 bludgeoning damage.\n\nA creature restrained by the tentacles can use its action to make a Strength or Dexterity check (its choice) against your spell save DC. On a success, it frees itself.","","Bludgeoning","DEX"],
["Blight",4,6,"1 action","30 feet","Instantaneous","VS","",0,0,[2, 5, 6, 7],"Necromantic energy washes over a creature of your choice that you can see within range, draining moisture and vitality from it. The target must make a constitution saving throw. The target takes 8d8 necrotic damage on a failed save, or half as much damage on a successful one. The spell has no effect on undead or constructs.\n\nIf you target a plant creature or a magical plant, it makes the saving throw with disadvantage, and the spell deals maximum damage to it.\n\nIf you target a nonmagical plant that isn't a creature, such as a tree or shrub, it doesn't make a saving throw; it simply withers and dies.","When you cast this spell using a spell slot of 5th level of higher, the damage increases by 1d8 for each slot level above 4th.","Necrotic","CON"],
["Compulsion",4,3,"1 action","30 feet","Up to 1 minute","VS","",1,0,[0],"Creatures of your choice that you can see within range and that can hear you must make a wisdom saving throw. A target automatically succeeds on this saving throw if it can't be charmed. On a failed save, a target is affected by this spell. Until the spell ends, you can use a bonus action on each of your turns to designate a direction that is horizontal to you. Each affected target must use as much of its movement as possible to move in that direction on its next turn. It can take any action before it moves. After moving in this way, it can make another Wisdom save to try to end the effect.\n\nA target isn't compelled to move into an obviously deadly hazard, such as a fire or a pit, but it will provoke opportunity attacks to move in the designated direction.","","","WIS"],
["Confusion",4,3,"1 action","90 feet","Up to 1 minute","VSM","Three walnut shells.",1,0,[0, 2, 5, 7],"This spell assaults and twists creatures' minds, spawning delusions and provoking uncontrolled action. Each creature in a 10-foot-radius sphere centered on a point you choose within range must succeed on a Wisdom saving throw when you cast this spell or be affected by it.\n\nAn affected target can't take reactions and must roll a d10 at the start of each of its turns to determine its behavior for that turn.\n\n| d10 | Behavior |\n\n|---|---|\n\n| 1 | The creature uses all its movement to move in a random direction. To determine the direction, roll a d8 and assign a direction to each die face. The creature doesn't take an action this turn. |\n\n| 2-6 | The creature doesn't move or take actions this turn. |\n\n| 7-8 | The creature uses its action to make a melee attack against a randomly determined creature within its reach. If there is no creature within its reach, the creature does nothing this turn. |\n\n| 9-10 | The creature can act and move normally. |\n\nAt the end of each of its turns, an affected target can make a Wisdom saving throw. If it succeeds, this effect ends for that target.","When you cast this spell using a spell slot of 5th level or higher, the radius of the sphere increases by 5 feet for each slot level above 4th.","","WIS"],
["Conjure Minor Elementals",4,1,"1 minute","90 feet","Up to 1 hour","VS","",1,0,[2, 7],"You summon elementals that appear in unoccupied spaces that you can see within range. You choose one the following options for what appears:\n\n- One elemental of challenge rating 2 or lower\n\n- Two elementals of challenge rating 1 or lower\n\n- Four elementals of challenge rating 1/2 or lower\n\n- Eight elementals of challenge rating 1/4 or lower.\n\nAn elemental summoned by this spell disappears when it drops to 0 hit points or when the spell ends.\n\nThe summoned creatures are friendly to you and your companions. Roll initiative for the summoned creatures as a group, which has its own turns. They obey any verbal commands that you issue to them (no action required by you). If you don't issue any commands to them, they defend themselves from hostile creatures, but otherwise take no actions.\n\nThe GM has the creatures' statistics.","When you cast this spell using certain higher-level spell slots, you choose one of the summoning options above, and more creatures appear: twice as many with a 6th-level slot and three times as many with an 8th-level slot.","",""],
["Conjure Woodland Beings",4,1,"1 action","60 feet","Up to 1 hour","VSM","One holly berry per creature summoned.",1,0,[2, 4],"You summon fey creatures that appear in unoccupied spaces that you can see within range. Choose one of the following options for what appears:\n\n- One fey creature of challenge rating 2 or lower\n\n- Two fey creatures of challenge rating 1 or lower\n\n- Four fey creatures of challenge rating 1/2 or lower\n\n- Eight fey creatures of challenge rating 1/4 or lower\n\nA summoned creature disappears when it drops to 0 hit points or when the spell ends.\n\nThe summoned creatures are friendly to you and your companions. Roll initiative for the summoned creatures as a group, which have their own turns. They obey any verbal commands that you issue to them (no action required by you). If you don't issue any commands to them, they defend themselves from hostile creatures, but otherwise take no actions.\n\nThe GM has the creatures' statistics.","When you cast this spell using certain higher-level spell slots, you choose one of the summoning options above, and more creatures appear: twice as many with a 6th-level slot and three times as many with an 8th-level slot.","",""],
["Control Water",4,7,"1 action","300 feet","Up to 10 minutes","VSM","A drop of water and a pinch of dust.",1,0,[1, 2, 7],"Until the spell ends, you control any freestanding water inside an area you choose that is a cube up to 100 feet on a side. You can choose from any of the following effects when you cast this spell. As an action on your turn, you can repeat the same effect or choose a different one.\n\n***Flood.*** You cause the water level of all standing water in the area to rise by as much as 20 feet. If the area includes a shore, the flooding water spills over onto dry land.\n\nIf you choose an area in a large body of water, you instead create a 20-foot tall wave that travels from one side of the area to the other and then crashes down. Any Huge or smaller vehicles in the wave's path are carried with it to the other side. Any Huge or smaller vehicles struck by the wave have a 25 percent chance of capsizing.\n\nThe water level remains elevated until the spell ends or you choose a different effect. If this effect produced a wave, the wave repeats on the start of your next turn while the flood effect lasts.\n\n***Part Water.*** You cause water in the area to move apart and create a trench. The trench extends across the spell's area, and the separated water forms a wall to either side. The trench remains until the spell ends or you choose a different effect. The water then slowly fills in the trench over the course of the next round until the normal water level is restored.\n\n***Redirect Flow.*** You cause flowing water in the area to move in a direction you choose, even if the water has to flow over obstacles, up walls, or in other unlikely directions. The water in the area moves as you direct it, but once it moves beyond the spell's area, it resumes its flow based on the terrain conditions. The water continues to move in the direction you chose until the spell ends or you choose a different effect.\n\n***Whirlpool.*** This effect requires a body of water at least 50 feet square and 25 feet deep. You cause a whirlpool to form in the center of the area. The whirlpool forms a vortex that is 5 feet wide at the base, up to 50 feet wide at the top, and 25 feet tall. Any creature or object in the water and within 25 feet of the vortex is pulled 10 feet toward it. A creature can swim away from the vortex by making a Strength (Athletics) check against your spell save DC.\n\nWhen a creature enters the vortex for the first time on a turn or starts its turn there, it must make a strength saving throw. On a failed save, the creature takes 2d8 bludgeoning damage and is caught in the vortex until the spell ends. On a successful save, the creature takes half damage, and isn't caught in the vortex. A creature caught in the vortex can use its action to try to swim away from the vortex as described above, but has disadvantage on the Strength (Athletics) check to do so.\n\nThe first time each turn that an object enters the vortex, the object takes 2d8 bludgeoning damage; this damage occurs each round it remains in the vortex.","","Bludgeoning","STR"],
["Death Ward",4,0,"1 action","Touch","8 hours","VS","",0,0,[1, 3],"You touch a creature and grant it a measure of protection from death.\n\nThe first time the target would drop to 0 hit points as a result of taking damage, the target instead drops to 1 hit point, and the spell ends.\n\nIf the spell is still in effect when the target is subjected to an effect that would kill it instantaneously without dealing damage, that effect is instead negated against the target, and the spell ends.","","",""],
["Dimension Door",4,1,"1 action","500 feet","Instantaneous","V","",0,0,[0, 5, 6, 7],"You teleport yourself from your current location to any other spot within range. You arrive at exactly the spot desired. It can be a place you can see, one you can visualize, or one you can describe by stating distance and direction, such as \"200 feet straight downward\" or \"upward to the northwest at a 45-degree angle, 300 feet.\"\n\nYou can bring along objects as long as their weight doesn't exceed what you can carry. You can also bring one willing creature of your size or smaller who is carrying gear up to its carrying capacity. The creature must be within 5 feet of you when you cast this spell.\n\nIf you would arrive in a place already occupied by an object or a creature, you and any creature traveling with you each take 4d6 force damage, and the spell fails to teleport you.","","Force",""],
["Divination",4,2,"1 action","Self","Instantaneous","VSM","Incense and a sacrificial offering appropriate to your religion, together worth at least 25gp, which the spell consumes.",0,1,[2],"Your magic and an offering put you in contact with a god or a god's servants. You ask a single question concerning a specific goal, event, or activity to occur within 7 days. The GM offers a truthful reply. The reply might be a short phrase, a cryptic rhyme, or an omen.\n\nThe spell doesn't take into account any possible circumstances that might change the outcome, such as the casting of additional spells or the loss or gain of a companion.\n\nIf you cast the spell two or more times before finishing your next long rest, there is a cumulative 25 percent chance for each casting after the first that you get a random reading. The GM makes this roll in secret.","","",""],
["Dominate Beast",4,3,"1 action","60 feet","Up to 1 minute","VS","",1,0,[2, 5],"You attempt to beguile a creature that you can see within range. It must succeed on a wisdom saving throw or be charmed by you for the duration. If you or creatures that are friendly to you are fighting it, it has advantage on the saving throw.\n\nWhile the creature is charmed, you have a telepathic link with it as long as the two of you are on the same plane of existence. You can use this telepathic link to issue commands to the creature while you are conscious (no action required), which it does its best to obey. You can specify a simple and general course of action, such as \"Attack that creature,\" \"Run over there,\" or \"Fetch that object.\" If the creature completes the order and doesn't receive further direction from you, it defends and preserves itself to the best of its ability.\n\nYou can use your action to take total and precise control of the target. Until the end of your next turn, the creature takes only the actions you choose, and doesn't do anything that you don't allow it to do. During this time, you can also cause the creature to use a reaction, but this requires you to use your own reaction as well. Each time the target takes damage, it makes a new wisdom saving throw against the spell. If the saving throw succeeds, the spell ends.","When you cast this spell with a 9th level spell slot, the duration is concentration, up to 8 hours.","","WIS"],
["Fabricate",4,7,"10 minutes","120 feet","Instantaneous","VS","",0,0,[7],"You convert raw materials into products of the same material. For example, you can fabricate a wooden bridge from a clump of trees, a rope from a patch of hemp, and clothes from flax or wool.\n\nChoose raw materials that you can see within range. You can fabricate a Large or smaller object (contained within a 10-foot cube, or eight connected 5-foot cubes), given a sufficient quantity of raw material. If you are working with metal, stone, or another mineral substance, however, the fabricated object can be no larger than Medium (contained within a single 5-foot cube). The quality of objects made by the spell is commensurate with the quality of the raw materials.\n\nCreatures or magic items can't be created or transmuted by this spell. You also can't use it to create items that ordinarily require a high degree of craftsmanship, such as jewelry, weapons, glass, or armor, unless you have proficiency with the type of artisan's tools used to craft such objects.","","",""],
["Faithful Hound",4,1,"1 action","30 feet","8 hours","VSM","A tiny silver whistle, a piece of bone, and a thread",0,0,[7],"You conjure a phantom watchdog in an unoccupied space that you can see within range, where it remains for the duration, until you dismiss it as an action, or until you move more than 100 feet away from it.\n\nThe hound is invisible to all creatures except you and can't be harmed. When a Small or larger creature comes within 30 feet of it without first speaking the password that you specify when you cast this spell, the hound starts barking loudly. The hound sees invisible creatures and can see into the Ethereal Plane. It ignores illusions.\n\nAt the start of each of your turns, the hound attempts to bite one creature within 5 feet of it that is hostile to you. The hound's attack bonus is equal to your spellcasting ability modifier + your proficiency bonus. On a hit, it deals 4d8 piercing damage.","","Piercing",""],
["Fire Shield",4,4,"1 action","Self","10 minutes","VSM","A little phosphorus or a firefly.",0,0,[7],"Thin and vaporous flame surround your body for the duration of the spell, radiating a bright light bright light in a 10-foot radius and dim light for an additional 10 feet. You can end the spell using an action to make it disappear.\n\nThe flames are around you a heat shield or cold, your choice. The heat shield gives you cold damage resistance and the cold resistance to fire damage.\n\nIn addition, whenever a creature within 5 feet of you hits you with a melee attack, flames spring from the shield. The attacker then suffers 2d8 points of fire damage or cold, depending on the model.","","Fire",""],
["Freedom of Movement",4,0,"1 action","Touch","1 hour","VSM","A leather strap, bound around the arm or a similar appendage.",0,0,[0, 1, 2, 4],"You touch a willing creature. For the duration, the target's movement is unaffected by difficult terrain, and spells and other magical effects can neither reduce the target's speed nor cause the target to be paralyzed or restrained.\n\nThe target can also spend 5 feet of movement to automatically escape from nonmagical restraints, such as manacles or a creature that has it grappled. Finally, being underwater imposes no penalties on the target's movement or attacks.","","",""],
["Giant Insect",4,7,"1 action","30 feet","Up to 10 minutes","VS","",1,0,[2],"You transform up to ten centipedes, three spiders, five wasps, or one scorpion within range into giant versions of their natural forms for the duration. A centipede becomes a giant centipede, a spider becomes a giant spider, a wasp becomes a giant wasp, and a scorpion becomes a giant scorpion.\n\nEach creature obeys your verbal commands, and in combat, they act on your turn each round. The GM has the statistics for these creatures and resolves their actions and movement.\n\nA creature remains in its giant size for the duration, until it drops to 0 hit points, or until you use an action to dismiss the effect on it.\n\nThe GM might allow you to choose different targets. For example, if you transform a bee, its giant version might have the same statistics as a giant wasp.","","",""],
["Greater Invisibility",4,5,"1 action","Touch","Up to 1 minute","VS","",1,0,[0, 5, 7],"You or a creature you touch becomes invisible until the spell ends. Anything the target is wearing or carrying is invisible as long as it is on the target's person.","","",""],
["Guardian of Faith",4,1,"1 action","30 feet","8 hours","V","",0,0,[1],"A Large spectral guardian appears and hovers for the duration in an unoccupied space of your choice that you can see within range. The guardian occupies that space and is indistinct except for a gleaming sword and shield emblazoned with the symbol of your deity.\n\nAny creature hostile to you that moves to a space within 10 feet of the guardian for the first time on a turn must succeed on a dexterity saving throw. The creature takes 20 radiant damage on a failed save, or half as much damage on a successful one. The guardian vanishes when it has dealt a total of 60 damage.","","Radiant","DEX"],
["Hallucinatory Terrain",4,5,"10 minutes","300 feet","24 hours","VSM","A stone, a twig, and a bit of green plant.",0,0,[0, 2, 6, 7],"You make natural terrain in a 150-foot cube in range look, sound, and smell like some other sort of natural terrain. Thus, open fields or a road can be made to resemble a swamp, hill, crevasse, or some other difficult or impassable terrain. A pond can be made to seem like a grassy meadow, a precipice like a gentle slope, or a rock-strewn gully like a wide and smooth road. Manufactured structures, equipment, and creatures within the area aren't changed in appearance.\n\nThe tactile characteristics of the terrain are unchanged, so creatures entering the area are likely to see through the illusion. If the difference isn't obvious by touch, a creature carefully examining the illusion can attempt an Intelligence (Investigation) check against your spell save DC to disbelieve it. A creature who discerns the illusion for what it is, sees it as a vague image superimposed on the terrain.","","",""],
["Ice Storm",4,4,"1 action","300 feet","Instantaneous","VSM","A pinch of dust and a few drops of water.",0,0,[2, 5, 7],"A hail of rock-hard ice pounds to the ground in a 20-foot-radius, 40-foot-high cylinder centered on a point within range. Each creature in the cylinder must make a dexterity saving throw. A creature takes 2d8 bludgeoning damage and 4d6 cold damage on a failed save, or half as much damage on a successful one.\n\nHailstones turn the storm's area of effect into difficult terrain until the end of your next turn.","When you cast this spell using a spell slot of 5th level or higher, the bludgeoning damage increases by 1d8 for each slot level above 4th.","Bludgeoning","DEX"],
["Locate Creature",4,2,"1 action","Self","Up to 1 hour","VSM","A bit of fur from a bloodhound.",1,0,[0, 1, 2, 3, 4, 7],"Describe or name a creature that is familiar to you. You sense the direction to the creature's location, as long as that creature is within 1,000 feet of you. If the creature is moving, you know the direction of its movement.\n\nThe spell can locate a specific creature known to you, or the nearest creature of a specific kind (such as a human or a unicorn), so long as you have seen such a creature up close--within 30 feet--at least once. If the creature you described or named is in a different form, such as being under the effects of a polymorph spell, this spell doesn't locate the creature.\n\nThis spell can't locate a creature if running water at least 10 feet wide blocks a direct path between you and the creature.","","",""],
["Phantasmal Killer",4,5,"1 action","120 feet","Up to 1 minute","VS","",1,0,[7],"You tap into the nightmares of a creature you can see within range and create an illusory manifestation of its deepest fears, visible only to that creature. The target must make a wisdom saving throw. On a failed save, the target becomes frightened for the duration. At the start of each of the target's turns before the spell ends, the target must succeed on a wisdom saving throw or take 4d10 psychic damage. On a successful save, the spell ends.","When you cast this spell using a spell slot of 5th level or higher, the damage increases by 1d10 for each slot level above 4th.","Psychic","WIS"],
["Polymorph",4,7,"1 action","60 feet","Up to 1 hour","VSM","A caterpillar cocoon.",1,0,[0, 2, 5, 7],"This spell transforms a creature that you can see within range into a new form. An unwilling creature must make a wisdom saving throw to avoid the effect. A shapechanger automatically succeeds on this saving throw.\n\nThe transformation lasts for the duration, or until the target drops to 0 hit points or dies. The new form can be any beast whose challenge rating is equal to or less than the target's (or the target's level, if it doesn't have a challenge rating). The target's game statistics, including mental ability scores, are replaced by the statistics of the chosen beast. It retains its alignment and personality.\n\nThe target assumes the hit points of its new form. When it reverts to its normal form, the creature returns to the number of hit points it had before it transformed. If it reverts as a result of dropping to 0 hit points, any excess damage carries over to its normal form. As long as the excess damage doesn't reduce the creature's normal form to 0 hit points, it isn't knocked unconscious.\n\nThe creature is limited in the actions it can perform by the nature of its new form, and it can't speak, cast spells, or take any other action that requires hands or speech.\n\nThe target's gear melds into the new form. The creature can't activate, use, wield, or otherwise benefit from any of its equipment.","","","WIS"],
["Private Sanctum",4,0,"10 minutes","120 feet","24 hours","VSM","A thin sheet of lead, a piece of opaque glass, a wad of cotton or cloth, and powdered chrysolite.",0,0,[7],"You make an area within range magically secure. The area is a cube that can be as small as 5 feet to as large as 100 feet on each side. The spell lasts for the duration or until you use an action to dismiss it.\n\nWhen you cast the spell, you decide what sort of security the spell provides, choosing any or all of the following properties:\n\n- Sound can't pass through the barrier at the edge of the warded area.\n\n- The barrier of the warded area appears dark and foggy, preventing vision (including darkvision) through it.\n\n- Sensors created by divination spells can't appear inside the protected area or pass through the barrier at its perimeter.\n\n- Creatures in the area can't be targeted by divination spells.\n\n- Nothing can teleport into or out of the warded area.\n\n- Planar travel is blocked within the warded area.\n\nCasting this spell on the same spot every day for a year makes this effect permanent.","When you cast this spell using a spell slot of 5th level or higher, you can increase the size of the cube by 100 feet for each slot level beyond 4th. Thus you could protect a cube that can be up to 200 feet on one side by using a spell slot of 5th level.","",""],
["Resilient Sphere",4,4,"1 action","30 feet","Up to 1 minute","VSM","A hemispherical piece of clear crystal and a matching hemispherical piece of gum arabic.",1,0,[7],"A sphere of shimmering force encloses a creature or object of Large size or smaller within range. An unwilling creature must make a dexterity saving throw. On a failed save, the creature is enclosed for the duration.\n\nNothing--not physical objects, energy, or other spell effects--can pass through the barrier, in or out, though a creature in the sphere can breathe there. The sphere is immune to all damage, and a creature or object inside can't be damaged by attacks or effects originating from outside, nor can a creature inside the sphere damage anything outside it.\n\nThe sphere is weightless and just large enough to contain the creature or object inside. An enclosed creature can use its action to push against the sphere's walls and thus roll the sphere at up to half the creature's speed. Similarly, the globe can be picked up and moved by other creatures.\n\nA disintegrate spell targeting the globe destroys it without harming anything inside it.","","","DEX"],
["Secret Chest",4,1,"1 action","Touch","Instantaneous","VSM","An exquisite chest, 3 feet by 2 feet by 2 feet, constructed from rare materials worth at least 5,000 gp, and a Tiny replica made from the same materials worth at least 50 gp.",0,0,[7],"You hide a chest, and all its contents, on the Ethereal Plane. You must touch the chest and the miniature replica that serves as a material component for the spell. The chest can contain up to 12 cubic feet of nonliving material (3 feet by 2 feet by 2 feet).\n\nWhile the chest remains on the Ethereal Plane, you can use an action and touch the replica to recall the chest. It appears in an unoccupied space on the ground within 5 feet of you. You can send the chest back to the Ethereal Plane by using an action and touching both the chest and the replica.\n\nAfter 60 days, there is a cumulative 5 percent chance per day that the spell's effect ends. This effect ends if you cast this spell again, if the smaller replica chest is destroyed, or if you choose to end the spell as an action. If the spell ends and the larger chest is on the Ethereal Plane, it is irretrievably lost.","","",""],
["Stone Shape",4,7,"1 action","Touch","Instantaneous","VSM","Soft clay, to be crudely worked into the desired shape for the stone object.",0,0,[1, 2, 7],"You touch a stone object of Medium size or smaller or a section of stone no more than 5 feet in any dimension and form it into any shape that suits your purpose. So, for example, you could shape a large rock into a weapon, idol, or coffer, or make a small passage through a wall, as long as the wall is less than 5 feet thick. You could also shape a stone door or its frame to seal the door shut. The object you create can have up to two hinges and a latch, but finer mechanical detail isn't possible.","","",""],
["Stoneskin",4,0,"1 action","Touch","Up to 1 hour","VSM","Diamond dust worth 100 gp, which the spell consumes.",1,0,[2, 4, 5, 7],"This spell turns the flesh of a willing creature you touch as hard as stone. Until the spell ends, the target has resistance to nonmagical bludgeoning, piercing, and slashing damage.","","",""],
["Wall of Fire",4,4,"1 action","120 feet","Up to 1 minute","VSM","A small piece of phosphorus.",1,0,[2, 5, 7],"You create a wall of fire on a solid surface within range. You can make the wall up to 60 feet long, 20 feet high, and 1 foot thick, or a ringed wall up to 20 feet in diameter, 20 feet high, and 1 foot thick. The wall is opaque and lasts for the duration.\n\nWhen the wall appears, each creature within its area must make a Dexterity saving throw. On a failed save, a creature takes 5d8 fire damage, or half as much damage on a successful save.\n\nOne side of the wall, selected by you when you cast this spell, deals 5d8 fire damage to each creature that ends its turn within 10 feet o f that side or inside the wall. A creature takes the same damage when it enters the wall for the first time on a turn or ends its turn there. The other side of the wall deals no damage.\n\nThe other side of the wall deals no damage.","When you cast this spell using a spell slot of 5th level or higher, the damage increases by 1d8 for each slot level above 4th.","Fire","DEX"],
["Animate Objects",5,7,"1 action","120 feet","Up to 1 minute","VS","",1,0,[0, 5, 7],"Objects come to life at your command. Choose up to ten nonmagical objects within range that are not being worn or carried. Medium targets count as two objects, Large targets count as four objects, Huge targets count as eight objects. You can't animate any object larger than Huge. Each target animates and becomes a creature under your control until the spell ends or until reduced to 0 hit points.\n\nAs a bonus action, you can mentally command any creature you made with this spell if the creature is within 500 feet of you (if you control multiple creatures, you can command any or all of them at the same time, issuing the same command to each one). You decide what action the creature will take and where it will move during its next turn, or you can issue a general command, such as to guard a particular chamber or corridor. If you issue no commands, the creature only defends itself against hostile creatures. Once given an order, the creature continues to follow it until its task is complete.\n\n##### Animated Object Statistics\n\n| Size | HP | AC | Attack | Str | Dex |\n\n|---|---|---|---|---|---|\n\n| Tiny | 20 | 18 | +8 to hit, 1d4 + 4 damage | 4 | 18 |\n\n| Small | 25 | 16 | +6 to hit, 1d8 + 2 damage | 6 | 14 |\n\n| Medium | 40 | 13 | +5 to hit, 2d6 + 1 damage | 10 | 12 |\n\n| Large | 50 | 10 | +6 to hit, 2d10 + 2 damage | 14 | 10 |\n\n| Huge | 80 | 10 | +8 to hit, 2d12 + 4 damage | 18 | 6 |\n\nAn animated object is a construct with AC, hit points, attacks, Strength, and Dexterity determined by its size. Its Constitution is 10 and its Intelligence and Wisdom are 3, and its Charisma is 1. Its speed is 30 feet; if the object lacks legs or other appendages it can use for locomotion, it instead has a flying speed of 30 feet and can hover. If the object is securely attached to a surface or a larger object, such as a chain bolted to a wall, its speed is 0. It has blindsight with a radius of 30 feet and is blind beyond that distance. When the animated object drops to 0 hit points, it reverts to its original object form, and any remaining damage carries over to its original object form.\n\nIf you command an object to attack, it can make a single melee attack against a creature within 5 feet of it. It makes a slam attack with an attack bonus and bludgeoning damage determined by its size. The GM might rule that a specific object inflicts slashing or piercing damage based on its form.","If you cast this spell using a spell slot of 6th level or higher, you can animate two additional objects for each slot level above 5th.","",""],
["Antilife Shell",5,0,"1 action","Self","Up to 1 hour","VS","",1,0,[2],"A shimmering barrier extends out from you in a 10-foot radius and moves with you, remaining centered on you and hedging out creatures other than undead and constructs. The barrier lasts for the duration.\n\nThe barrier prevents an affected creature from passing or reaching through. An affected creature can cast spells or make attacks with ranged or reach weapons through the barrier.\n\nIf you move so that an affected creature is forced to pass through the barrier, the spell ends.","","",""],
["Arcane Hand",5,4,"1 action","120 feet","Up to 1 minute","VSM","An eggshell and a snakeskin glove.",1,0,[7],"You create a Large hand of shimmering, translucent force in an unoccupied space that you can see within range. The hand lasts for the spell's duration, and it moves at your command, mimicking the movements of your own hand.\n\nThe hand is an object that has AC 20 and hit points equal to your hit point maximum. If it drops to 0 hit points, the spell ends. It has a Strength of 26 (+8) and a Dexterity of 10 (+0). The hand doesn't fill its space.\n\nWhen you cast the spell and as a bonus action on your subsequent turns, you can move the hand up to 60 feet and then cause one of the following effects with it.\n\n***Clenched Fist.*** The hand strikes one creature or object within 5 feet of it. Make a melee spell attack for the hand using your game statistics. On a hit, the target takes 4d8 force damage.\n\n***Forceful Hand.*** The hand attempts to push a creature within 5 feet of it in a direction you choose. Make a check with the hand's Strength contested by the Strength (Athletics) check of the target. If the target is Medium or smaller, you have advantage on the check. If you succeed, the hand pushes the target up to 5 feet plus a number of feet equal to five times your spellcasting ability modifier. The hand moves with the target to remain within 5 feet of it.\n\n***Grasping Hand.*** The hand attempts to grapple a Huge or smaller creature within 5 feet of it. You use the hand's Strength score to resolve the grapple. If the target is Medium or smaller, you have advantage on the check. While the hand is grappling the target, you can use a bonus action to have the hand crush it. When you do so, the target takes bludgeoning damage equal to 2d6 + your spellcasting ability modifier.\n\n***Interposing Hand.*** The hand interposes itself between you and a creature you choose until you give the hand a different command. The hand moves to stay between you and the target, providing you with half cover against the target. The target can't move through the hand's space if its Strength score is less than or equal to the hand's Strength score. If its Strength score is higher than the hand's Strength score, the target can move toward you through the hand's space, but that space is difficult terrain for the target.","When you cast this spell using a spell slot of 6th level or higher, the damage from the clenched fist option increases by 2d8 and the damage from the grasping hand increases by 2d6 for each slot level above 5th.","",""],
["Awaken",5,7,"8 hours","Touch","Instantaneous","VSM","An agate worth at least 1,000 gp, which the spell consumes.",0,0,[0, 2],"After spending the casting time tracing magical pathways within a precious gemstone, you touch a Huge or smaller beast or plant. The target must have either no Intelligence score or an Intelligence of 3 or less. The target gains an Intelligence of 10. The target also gains the ability to speak one language you know. If the target is a plant, it gains the ability to move its limbs, roots, vines, creepers, and so forth, and it gains senses similar to a human's. Your GM chooses statistics appropriate for the awakened plant, such as the statistics for the awakened shrub or the awakened tree.\n\nThe awakened beast or plant is charmed by you for 30 days or until you or your companions do anything harmful to it. When the charmed condition ends, the awakened creature chooses whether to remain friendly to you, based on how you treated it while it was charmed.","","",""],
["Cloudkill",5,1,"1 action","120 feet","Up to 10 minutes","VS","",1,0,[5, 7],"You create a 20-foot-radius sphere of poisonous, yellow-green fog centered on a point you choose within range. The fog spreads around corners. It lasts for the duration or until strong wind disperses the fog, ending the spell. Its area is heavily obscured.\n\nWhen a creature enters the spell's area for the first time on a turn or starts its turn there, that creature must make a constitution saving throw. The creature takes 5d8 poison damage on a failed save, or half as much damage on a successful one. Creatures are affected even if they hold their breath or don't need to breathe.\n\nThe fog moves 10 feet away from you at the start of each of your turns, rolling along the surface of the ground. The vapors, being heavier than air, sink to the lowest level of the land, even pouring down openings.","When you cast this spell using a spell slot of 6th level or higher, the damage increases by 1d8 for each slot level above 5th.","Poison","CON"],
["Commune",5,2,"1 minute","Self","1 minute","VSM","Incense and a vial of holy or unholy water.",0,1,[1],"You contact your deity or a divine proxy and ask up to three questions that can be answered with a yes or no. You must ask your questions before the spell ends. You receive a correct answer for each question.\n\nDivine beings aren't necessarily omniscient, so you might receive \"unclear\" as an answer if a question pertains to information that lies beyond the deity's knowledge. In a case where a one-word answer could be misleading or contrary to the deity's interests, the GM might offer a short phrase as an answer instead.\n\nIf you cast the spell two or more times before finishing your next long rest, there is a cumulative 25 percent chance for each casting after the first that you get no answer. The GM makes this roll in secret.","","",""],
["Commune With Nature",5,2,"1 minute","Self","Instantaneous","VS","",0,1,[2, 4],"You briefly become one with nature and gain knowledge of the surrounding territory. In the outdoors, the spell gives you knowledge of the land within 3 miles of you. In caves and other natural underground settings, the radius is limited to 300 feet. The spell doesn't function where nature has been replaced by construction, such as in dungeons and towns.\n\nYou instantly gain knowledge of up to three facts of your choice about any of the following subjects as they relate to the area:\n\n- terrain and bodies of water\n\n- prevalent plants, minerals, animals, or peoples\n\n- powerful celestials, fey, fiends, elementals, or undead\n\n- influence from other planes of existence\n\n- buildings\n\nFor example, you could determine the location of powerful undead in the area, the location of major sources of safe drinking water, and the location of any nearby towns.","","",""],
["Cone of Cold",5,4,"1 action","Self","Instantaneous","VSM","A small crystal or glass cone.",0,0,[5, 7],"A blast of cold air erupts from your hands. Each creature in a 60-foot cone must make a constitution saving throw. A creature takes 8d8 cold damage on a failed save, or half as much damage on a successful one.\n\nA creature killed by this spell becomes a frozen statue until it thaws.","When you cast this spell using a spell slot of 6th level or higher, the damage increases by 1d8 for each slot level above 5th.","Cold","CON"],
["Conjure Elemental",5,1,"1 minute","90 feet","Up to 1 hour","VSM","Burning incense for air, soft clay for earth, sulfur and phosphorus for fire, or water and sand for water.",1,0,[2, 7],"You call forth an elemental servant. Choose an area of air, earth, fire, or water that fills a 10-foot cube within range. An elemental of challenge rating 5 or lower appropriate to the area you chose appears in an unoccupied space within 10 feet of it. For example, a fire elemental emerges from a bonfire, and an earth elemental rises up from the ground. The elemental disappears when it drops to 0 hit points or when the spell ends.\n\nThe elemental is friendly to you and your companions for the duration. Roll initiative for the elemental, which has its own turns. It obeys any verbal commands that you issue to it (no action required by you). If you don't issue any commands to the elemental, it defends itself from hostile creatures but otherwise takes no actions.\n\nIf your concentration is broken, the elemental doesn't disappear. Instead, you lose control of the elemental, it becomes hostile toward you and your companions, and it might attack. An uncontrolled elemental can't be dismissed by you, and it disappears 1 hour after you summoned it.\n\nThe GM has the elemental's statistics.","When you cast this spell using a spell slot of 6th level or higher, the challenge rating increases by 1 for each slot level above 5th.","",""],
["Contact Other Plane",5,2,"1 minute","Self","1 minute","V","",0,1,[6, 7],"You mentally contact a demigod, the spirit of a long-dead sage, or some other mysterious entity from another plane. Contacting this extraplanar intelligence can strain or even break your mind. When you cast this spell, make a DC 15 intelligence saving throw. On a failure, you take 6d6 psychic damage and are insane until you finish a long rest. While insane, you can't take actions, can't understand what other creatures say, can't read, and speak only in gibberish. A greater restoration spell cast on you ends this effect.\n\nOn a successful save, you can ask the entity up to five questions. You must ask your questions before the spell ends. The GM answers each question with one word, such as \"yes,\" \"no,\" \"maybe,\" \"never,\" \"irrelevant,\" or \"unclear\" (if the entity doesn't know the answer to the question). If a one-word answer would be misleading, the GM might instead offer a short phrase as an answer.","","","INT"],
["Contagion",5,6,"1 action","Touch","7 days","VS","",0,0,[1, 2],"Your touch inflicts disease. Make a melee spell attack against a creature within your reach. On a hit, you afflict the creature with a disease of your choice from any of the ones described below.\n\nAt the end of each of the target's turns, it must make a constitution saving throw. After failing three of these saving throws, the disease's effects last for the duration, and the creature stops making these saves. After succeeding on three of these saving throws, the creature recovers from the disease, and the spell ends.\n\nSince this spell induces a natural disease in its target, any effect that removes a disease or otherwise ameliorates a disease's effects apply to it.\n\n***Blinding Sickness.*** Pain grips the creature's mind, and its eyes turn milky white. The creature has disadvantage on wisdom checks and wisdom saving throws and is blinded.\n\n***Filth Fever.*** A raging fever sweeps through the creature's body. The creature has disadvantage on strength checks, strength saving throws, and attack rolls that use Strength.\n\n***Flesh Rot.*** The creature's flesh decays. The creature has disadvantage on Charisma checks and vulnerability to all damage.\n\n***Mindfire.*** The creature's mind becomes feverish. The creature has disadvantage on intelligence checks and intelligence saving throws, and the creature behaves as if under the effects of the confusion spell during combat.\n\n***Seizure.*** The creature is overcome with shaking. The creature has disadvantage on dexterity checks, dexterity saving throws, and attack rolls that use Dexterity.\n\n***Slimy Doom.*** The creature begins to bleed uncontrollably. The creature has disadvantage on constitution checks and constitution saving throws. In addition, whenever the creature takes damage, it is stunned until the end of its next turn.","","","CON"],
["Creation",5,5,"1 minute","30 feet","Special","VSM","A tiny piece of matter of the same type of the item you plan to create.",0,0,[5, 7],"You pull wisps of shadow material from the Shadowfell to create a nonliving object of vegetable matter within range: soft goods, rope, wood, or something similar. You can also use this spell to create mineral objects such as stone, crystal, or metal. The object created must be no larger than a 5-foot cube, and the object must be of a form and material that you have seen before.\n\nThe duration depends on the object's material. If the object is composed of multiple materials, use the shortest duration.\n\n| Material | Duration |\n\n|---|---|\n\n| Vegetable matter | 1 day |\n\n| Stone or crystal | 12 hours |\n\n| Precious metals | 1 hour |\n\n| Gems | 10 minutes |\n\n| Adamantine or mithral | 1 minute |\n\nUsing any material created by this spell as another spell's material component causes that spell to fail.","When you cast this spell using a spell slot of 6th level or higher, the cube increases by 5 feet for each slot level above 5th.","",""],
["Dispel Evil and Good",5,0,"1 action","Self","Up to 1 minute","VSM","Holy water or powdered silver and iron.",1,0,[1, 3],"Shimmering energy surrounds and protects you from fey, undead, and creatures originating from beyond the Material Plane. For the duration, celestials, elementals, fey, fiends, and undead have disadvantage on attack rolls against you.\n\nYou can end the spell early by using either of the following special functions.\n\n***Break Enchantment.*** As your action, you touch a creature you can reach that is charmed, frightened, or possessed by a celestial, an elemental, a fey, a fiend, or an undead. The creature you touch is no longer charmed, frightened, or possessed by such creatures.\n\n***Dismissal.*** As your action, make a melee spell attack against a celestial, an elemental, a fey, a fiend, or an undead you can reach. On a hit, you attempt to drive the creature back to its home plane. The creature must succeed on a charisma saving throw or be sent back to its home plane (if it isn't there already). If they aren't on their home plane, undead are sent to the Shadowfell, and fey are sent to the Feywild.","","","CHA"],
["Dominate Person",5,3,"1 action","60 feet","Up to 1 minute","VS","",1,0,[0, 5, 7],"You attempt to beguile a humanoid that you can see within range. It must succeed on a wisdom saving throw or be charmed by you for the duration. If you or creatures that are friendly to you are fighting it, it has advantage on the saving throw.\n\nWhile the target is charmed, you have a telepathic link with it as long as the two of you are on the same plane of existence. You can use this telepathic link to issue commands to the creature while you are conscious (no action required), which it does its best to obey. You can specify a simple and general course of action, such as \"Attack that creature,\" \"Run over there,\" or \"Fetch that object.\" If the creature completes the order and doesn't receive further direction from you, it defends and preserves itself to the best of its ability.\n\nYou can use your action to take total and precise control of the target. Until the end of your next turn, the creature takes only the actions you choose, and doesn't do anything that you don't allow it to do. During this time you can also cause the creature to use a reaction, but this requires you to use your own reaction as well.\n\nEach time the target takes damage, it makes a new wisdom saving throw against the spell. If the saving throw succeeds, the spell ends.","When you cast this spell using a 6th-level spell slot, the duration is concentration, up to 10 minutes. When you use a 7th-level spell slot, the duration is concentration, up to 1 hour. When you use a spell slot of 8th level or higher, the duration is concentration, up to 8 hours.","","WIS"],
["Dream",5,5,"1 minute","Special","8 hours","VSM","A handful of sand, a dab of ink, and a writing quill plucked from a sleeping bird.",0,0,[0, 6, 7],"This spell shapes a creature's dreams. Choose a creature known to you as the target of this spell. The target must be on the same plane of existence as you. Creatures that don't sleep, such as elves, can't be contacted by this spell. You, or a willing creature you touch, enters a trance state, acting as a messenger.\n\nWhile in the trance, the messenger is aware of his or her surroundings, but can't take actions or move.\n\nIf the target is asleep, the messenger appears in the target's dreams and can converse with the target as long as it remains asleep, through the duration of the spell. The messenger can also shape the environment of the dream, creating landscapes, objects, and other images. The messenger can emerge from the trance at any time, ending the effect of the spell early. The target recalls the dream perfectly upon waking. If the target is awake when you cast the spell, the messenger knows it, and can either end the trance (and the spell) or wait for the target to fall asleep, at which point the messenger appears in the target's dreams.\n\nYou can make the messenger appear monstrous and terrifying to the target. If you do, the messenger can deliver a message of no more than ten words and then the target must make a wisdom saving throw. On a failed save, echoes of the phantasmal monstrosity spawn a nightmare that lasts the duration of the target's sleep and prevents the target from gaining any benefit from that rest. In addition, when the target wakes up, it takes 3d6 psychic damage.\n\nIf you have a body part, lock of hair, clipping from a nail, or similar portion of the target's body, the target makes its saving throw with disadvantage.","","Psychic","WIS"],
["Flame Strike",5,4,"1 action","60 feet","Instantaneous","VSM","Pinch of sulfur.",0,0,[1],"A vertical column of divine fire roars down from the heavens in a location you specify. Each creature in a 10-foot-radius, 40-foot-high cylinder centered on a point within range must make a dexterity saving throw. A creature takes 4d6 fire damage and 4d6 radiant damage on a failed save, or half as much damage on a successful one.","When you cast this spell using a spell slot of 6th level or higher, the fire damage or the radiant damage (your choice) increases by 1d6 for each slot level above 5th.","Fire","DEX"],
["Geas",5,3,"1 minute","60 feet","30 days","V","",0,0,[0, 1, 2, 3, 7],"You place a magical command on a creature that you can see within range, forcing it to carry out some service or refrain from some action or course of activity as you decide. If the creature can understand you, it must succeed on a wisdom saving throw or become charmed by you for the duration. While the creature is charmed by you, it takes 5d10 psychic damage each time it acts in a manner directly counter to your instructions, but no more than once each day. A creature that can't understand you is unaffected by the spell.\n\nYou can issue any command you choose, short of an activity that would result in certain death. Should you issue a suicidal command, the spell ends.\n\nYou can end the spell early by using an action to dismiss it. A remove curse, greater restoration, or wish spell also ends it.","When you cast this spell using a spell slot of 7th or 8th level, the duration is 1 year. When you cast this spell using a spell slot of 9th level, the spell lasts until it is ended by one of the spells mentioned above.","","WIS"],
["Greater Restoration",5,0,"1 action","Touch","Instantaneous","VSM","Diamond dust worth at least 100gp, which the spell consumes.",0,0,[0, 1, 2],"You imbue a creature you touch with positive energy to undo a debilitating effect. You can reduce the target's exhaustion level by one, or end one of the following effects on the target:\n\n- One effect that charmed or petrified the target\n\n- One curse, including the target's attunement to a cursed magic item\n\n- Any reduction to one of the target's ability scores\n\n- One effect reducing the target's hit point maximum","","",""],
["Hallow",5,4,"24 hours","Touch","Until dispelled","VSM","Herbs, oils, and incense worth at least 1,000 gp, which the spell consumes.",0,0,[1],"You touch a point and infuse an area around it with holy (or unholy) power. The area can have a radius up to 60 feet, and the spell fails if the radius includes an area already under the effect a hallow spell. The affected area is subject to the following effects.\n\nFirst, celestials, elementals, fey, fiends, and undead can't enter the area, nor can such creatures charm, frighten, or possess creatures within it. Any creature charmed, frightened, or possessed by such a creature is no longer charmed, frightened, or possessed upon entering the area. You can exclude one or more of those types of creatures from this effect.\n\nSecond, you can bind an extra effect to the area. Choose the effect from the following list, or choose an effect offered by the GM. Some of these effects apply to creatures in the area; you can designate whether the effect applies to all creatures, creatures that follow a specific deity or leader, or creatures of a specific sort, such as ores or trolls. When a creature that would be affected enters the spell's area for the first time on a turn or starts its turn there, it can make a charisma saving throw. On a success, the creature ignores the extra effect until it leaves the area.\n\n***Courage.*** Affected creatures can't be frightened while in the area.\n\n***Darkness.*** Darkness fills the area. Normal light, as well as magical light created by spells of a lower level than the slot you used to cast this spell, can't illuminate the area.\n\n***Daylight.*** Bright light fills the area. Magical darkness created by spells of a lower level than the slot you used to cast this spell can't extinguish the light.\n\n***Energy Protection.*** Affected creatures in the area have resistance to one damage type of your choice, except for bludgeoning, piercing, or slashing.\n\n***Energy Vulnerability.*** Affected creatures in the area have vulnerability to one damage type of your choice, except for bludgeoning, piercing, or slashing.\n\n***Everlasting Rest.*** Dead bodies interred in the area can't be turned into undead.\n\n***Extradimensional Interference.*** Affected creatures can't move or travel using teleportation or by extradimensional or interplanar means.\n\n***Fear.*** Affected creatures are frightened while in the area.\n\n***Silence.*** No sound can emanate from within the area, and no sound can reach into it.\n\n***Tongues.*** Affected creatures can communicate with any other creature in the area, even if they don't share a common language.","","","CHA"],
["Hold Monster",5,3,"1 action","90 feet","Up to 1 minute","VSM","A small piece of iron.",1,0,[0, 5, 6, 7],"Choose a creature you can see and reach. The target must make a saving throw of Wisdom or be paralyzed for the duration of the spell. This spell has no effect against the undead. At the end of each round, the target can make a new saving throw of Wisdom. If successful, the spell ends for the creature.","When you cast this spell using a level 6 or higher location, you can target an additional creature for each level of location beyond the fifth. The creatures must be within 30 feet o f each other when you target them.","","WIS"],
["Insect Plague",5,1,"1 action","300 feet","Up to 10 minutes","VSM","A few grains of sugar, some kernels of grain, and a smear of fat.",1,0,[1, 2, 5],"Swarming, biting locusts fill a 20-foot-radius sphere centered on a point you choose within range. The sphere spreads around corners. The sphere remains for the duration, and its area is lightly obscured. The sphere's area is difficult terrain.\n\nWhen the area appears, each creature in it must make a constitution saving throw. A creature takes 4d10 piercing damage on a failed save, or half as much damage on a successful one. A creature must also make this saving throw when it enters the spell's area for the first time on a turn or ends its turn there.","When you cast this spell using a spell slot of 6th level or higher, the damage increases by 1d10 for each slot level above 5th.","Piercing","CON"],
["Legend Lore",5,2,"10 minutes","Self","Instantaneous","VSM","Incense worth at least 250 gp, which the spell consumes, and four ivory strips worth at least 50 gp each.",0,0,[0, 1, 7],"Name or describe a person, place, or object. The spell brings to your mind a brief summary of the significant lore about the thing you named. The lore might consist of current tales, forgotten stories, or even secret lore that has never been widely known. If the thing you named isn't of legendary importance, you gain no information. The more information you already have about the thing, the more precise and detailed the information you receive is.\n\nThe information you learn is accurate but might be couched in figurative language. For example, if you have a mysterious magic axe on hand the spell might yield this information: \"Woe to the evildoer whose hand touches the axe, for even the haft slices the hand of the evil ones. Only a true Child of Stone, lover and beloved of Moradin, may awaken the true powers of the axe, and only with the sacred word *Rudnogg* on the lips.\"","","",""],
["Mass Cure Wounds",5,1,"1 action","60 feet","Instantaneous","VS","",0,0,[0, 1, 2],"A wave of healing energy washes out from a point of your choice within range. Choose up to six creatures in a 30-foot-radius sphere centered on that point. Each target regains hit points equal to 3d8 + your spellcasting ability modifier. This spell has no effect on undead or constructs.","When you cast this spell using a spell slot of 6th level or higher, the healing increases by 1d8 for each slot level above 5th.","",""],
["Mislead",5,5,"1 action","Self","Up to 1 hour","S","",1,0,[0, 7],"You become invisible at the same time that an illusory double of you appears where you are standing. The double lasts for the duration, but the invisibility ends if you attack or cast a spell.\n\nYou can use your action to move your illusory double up to twice your speed and make it gesture, speak, and behave in whatever way you choose.\n\nYou can see through its eyes and hear through its ears as if you were located where it is. On each of your turns as a bonus action, you can switch from using its senses to using your own, or back again. While you are using its senses, you are blinded and deafened in regard to your own surroundings.","","",""],
["Modify Memory",5,3,"1 action","30 feet","Up to 1 minute","VS","",1,0,[0, 7],"You attempt to reshape another creature's memories. One creature that you can see must make a wisdom saving throw. If you are fighting the creature, it has advantage on the saving throw. On a failed save, the target becomes charmed by you for the duration. The charmed target is incapacitated and unaware of its surroundings, though it can still hear you. If it takes any damage or is targeted by another spell, this spell ends, and none of the target's memories are modified.\n\nWhile this charm lasts, you can affect the target's memory of an event that it experienced within the last 24 hours and that lasted no more than 10 minutes. You can permanently eliminate all memory of the event, allow the target to recall the event with perfect clarity and exacting detail, change its memory of the details of the event, or create a memory of some other event.\n\nYou must speak to the target to describe how its memories are affected, and it must be able to understand your language for the modified memories to take root. Its mind fills in any gaps in the details of your description. If the spell ends before you have finished describing the modified memories, the creature's memory isn't altered. Otherwise, the modified memories take hold when the spell ends.\n\nA modified memory doesn't necessarily affect how a creature behaves, particularly if the memory contradicts the creature's natural inclinations, alignment, or beliefs. An illogical modified memory, such as implanting a memory of how much the creature enjoyed dousing itself in acid, is dismissed, perhaps as a bad dream. The GM might deem a modified memory too nonsensical to affect a creature in a significant manner.\n\nA remove curse or greater restoration spell cast on the target restores the creature's true memory.","If you cast this spell using a spell slot of 6th level or higher, you can alter the target's memories of an event that took place up to 7 days ago (6th level), 30 days ago (7th level), 1 year ago (8th level), or any time in the creature's past (9th level).","","WIS"],
["Passwall",5,7,"1 action","30 feet","1 hour","VSM","A pinch of sesame seeds.",0,0,[7],"A passage appears at a point of your choice that you can see on a wooden, plaster, or stone surface (such as a wall, a ceiling, or a floor) within range, and lasts for the duration. You choose the opening's dimensions: up to 5 feet wide, 8 feet tall, and 20 feet deep. The passage creates no instability in a structure surrounding it.\n\nWhen the opening disappears, any creatures or objects still in the passage created by the spell are safely ejected to an unoccupied space nearest to the surface on which you cast the spell.","","",""],
["Planar Binding",5,0,"1 hour","60 feet","24 hours","VSM","A jewel worth at least 1,000 gp, which the spell consumes.",0,0,[0, 1, 2, 7],"With this spell, you attempt to bind a celestial, an elemental, a fey, or a fiend to your service. The creature must be within range for the entire casting of the spell. (Typically, the creature is first summoned into the center of an inverted magic circle in order to keep it trapped while this spell is cast.) At the completion of the casting, the target must make a charisma saving throw. On a failed save, it is bound to serve you for the duration. If the creature was summoned or created by another spell, that spell's duration is extended to match the duration of this spell.\n\nA bound creature must follow your instructions to the best of its ability. You might command the creature to accompany you on an adventure, to guard a location, or to deliver a message. The creature obeys the letter of your instructions, but if the creature is hostile to you, it strives to twist your words to achieve its own objectives. If the creature carries out your instructions completely before the spell ends, it travels to you to report this fact if you are on the same plane of existence. If you are on a different plane of existence, it returns to the place where you bound it and remains there until the spell ends.","When you cast this spell using a spell slot of a higher level, the duration increases to 10 days with a 6th-level slot, to 30 days with a 7th-level slot, to 180 days with an 8th-level slot, and to a year and a day with a 9th-level spell slot.","","CHA"],
["Raise Dead",5,6,"1 hour","Touch","Instantaneous","VSM","A diamond worth at least 500gp, which the spell consumes.",0,0,[0, 1, 3],"You return a dead creature you touch to life, provided that it has been dead no longer than 10 days. If the creature's soul is both willing and at liberty to rejoin the body, the creature returns to life with 1 hit point.\n\nThis spell also neutralizes any poisons and cures nonmagical diseases that affected the creature at the time it died. This spell doesn't, however, remove magical diseases, curses, or similar effects; if these aren't first removed prior to casting the spell, they take effect when the creature returns to life. The spell can't return an undead creature to life.\n\nThis spell closes all mortal wounds, but it doesn't restore missing body parts. If the creature is lacking body parts or organs integral for its survival--its head, for instance--the spell automatically fails.\n\nComing back from the dead is an ordeal. The target takes a -4 penalty to all attack rolls, saving throws, and ability checks. Every time the target finishes a long rest, the penalty is reduced by 1 until it disappears.","","",""],
["Reincarnate",5,7,"1 hour","Touch","Instantaneous","VSM","Rare oils and unguents worth at least 1,000 gp, which the spell consumes.",0,0,[2],"You touch a dead humanoid or a piece of a dead humanoid. Provided that the creature has been dead no longer than 10 days, the spell forms a new adult body for it and then calls the soul to enter that body. If the target's soul isn't free or willing to do so, the spell fails.\n\nThe magic fashions a new body for the creature to inhabit, which likely causes the creature's race to change. The GM rolls a d 100 and consults the following table to determine what form the creature takes when restored to life, or the GM chooses a form.\n\n| d100 | Race |\n\n|---|---|\n\n| 01-04 | Dragonborn |\n\n| 05-13 | Dwarf, hill |\n\n| 14-21 | Dwarf, mountain |\n\n| 22-25 | Elf, dark |\n\n| 26-34 | Elf, high |\n\n| 35-42 | Elf, wood |\n\n| 43-46 | Gnome, forest |\n\n| 47-52 | Gnome, rock |\n\n| 53-56 | Half-elf |\n\n| 57-60 | Half-orc |\n\n| 61-68 | Halfling, lightfoot |\n\n| 69-76 | Halfling, stout |\n\n| 77-96 | Human |\n\n| 97-00 | Tiefling |\n\nThe reincarnated creature recalls its former life and experiences. It retains the capabilities it had in its original form, except it exchanges its original race for the new one and changes its racial traits accordingly.","","",""],
["Scrying",5,2,"10 minutes","Self","Up to 10 minutes","VSM","A focus worth at least 1,000 gp, such as a crystal ball, a silver mirror, or a font filled with holy water.",1,0,[0, 1, 2, 6, 7],"You can see and hear a particular creature you choose that is on the same plane of existence as you. The target must make a wisdom saving throw, which is modified by how well you know the target and the sort of physical connection you have to it. If a target knows you're casting this spell, it can fail the saving throw voluntarily if it wants to be observed.\n\n| Knowledge | Save Modifier |\n\n|---|---|\n\n| Secondhand (you have heard of the target) | +5 |\n\n| Firsthand (you have met the target) | +0 |\n\n| Familiar (you know the target well) | -5 |\n\n| Connection | Save Modifier |\n\n|---|---|\n\n| Likeness or picture | -2 |\n\n| Possession or garment | -4 |\n\n| Body part, lock of hair, bit of nail, or the like | -10 |\n\nOn a successful save, the target isn't affected, and you can't use this spell against it again for 24 hours.\n\nOn a failed save, the spell creates an invisible sensor within 10 feet of the target. You can see and hear through the sensor as if you were there. The sensor moves with the target, remaining within 10 feet of it for the duration. A creature that can see invisible objects sees the sensor as a luminous orb about the size of your fist.\n\nInstead of targeting a creature, you can choose a location you have seen before as the target of this spell. When you do, the sensor appears at that location and doesn't move.","","","WIS"],
["Seeming",5,5,"1 action","30 feet","8 hours","VS","",0,0,[0, 5, 7],"This spell allows you to change the appearance of any number of creatures that you can see within range. You give each target you choose a new, illusory appearance. An unwilling target can make a charisma saving throw, and if it succeeds, it is unaffected by this spell.\n\nThe spell disguises physical appearance as well as clothing, armor, weapons, and equipment. You can make each creature seem 1 foot shorter or taller and appear thin, fat, or in between. You can't change a target's body type, so you must choose a form that has the same basic arrangement of limbs. Otherwise, the extent of the illusion is up to you. The spell lasts for the duration, unless you use your action to dismiss it sooner.\n\nThe changes wrought by this spell fail to hold up to physical inspection. For example, if you use this spell to add a hat to a creature's outfit, objects pass through the hat, and anyone who touches it would feel nothing or would feel the creature's head and hair. If you use this spell to appear thinner than you are, the hand of someone who reaches out to touch you would bump into you while it was seemingly still in midair.\n\nA creature can use its action to inspect a target and make an Intelligence (Investigation) check against your spell save DC. If it succeeds, it becomes aware that the target is disguised.","","",""],
["Telekinesis",5,7,"1 action","60 feet","Up to 10 minutes","VS","",1,0,[5, 7],"You gain the ability to move or manipulate creatures or objects by thought. When you cast the spell, and as your action each round for the duration, you can exert your will on one creature or object that you can see within range, causing the appropriate effect below. You can affect the same target round after round, or choose a new one at any time. If you switch targets, the prior target is no longer affected by the spell.\n\n***Creature.*** You can try to move a Huge or smaller creature. Make an ability check with your spellcasting ability contested by the creature's Strength check. If you win the contest, you move the creature up to 30 feet in any direction, including upward but not beyond the range of this spell. Until the end of your next turn, the creature is restrained in your telekinetic grip. A creature lifted upward is suspended in mid-air.\n\nOn subsequent rounds, you can use your action to attempt to maintain your telekinetic grip on the creature by repeating the contest.\n\n***Object.*** You can try to move an object that weighs up to 1,000 pounds. If the object isn't being worn or carried, you automatically move it up to 30 feet in any direction, but not beyond the range of this spell.\n\nIf the object is worn or carried by a creature, you must make an ability check with your spellcasting ability contested by that creature's Strength check. If you succeed, you pull the object away from that creature and can move it up to 30 feet in any direction but not beyond the range of this spell.\n\nYou can exert fine control on objects with your telekinetic grip, such as manipulating a simple tool, opening a door or a container, stowing or retrieving an item from an open container, or pouring the contents from a vial.","","",""],
["Telepathic Bond",5,2,"1 action","30 feet","1 hour","VSM","Pieces of eggshell from two different kinds of creatures",0,1,[7],"You forge a telepathic link among up to eight willing creatures of your choice within range, psychically linking each creature to all the others for the duration. Creatures with Intelligence scores of 2 or less aren't affected by this spell.\n\nUntil the spell ends, the targets can communicate telepathically through the bond whether or not they have a common language. The communication is possible over any distance, though it can't extend to other planes of existence.","","",""],
["Teleportation Circle",5,1,"1 minute","10 feet","1 round","VM","Rare chalks and inks infused with precious gems with 50 gp, which the spell consumes.",0,0,[0, 5, 7],"As you cast the spell, you draw a 10-foot-diameter circle on the ground inscribed with sigils that link your location to a permanent teleportation circle of your choice whose sigil sequence you know and that is on the same plane of existence as you. A shimmering portal opens within the circle you drew and remains open until the end of your next turn. Any creature that enters the portal instantly appears within 5 feet of the destination circle or in the nearest unoccupied space if that space is occupied.\n\nMany major temples, guilds, and other important places have permanent teleportation circles inscribed somewhere within their confines. Each such circle includes a unique sigil sequence--a string of magical runes arranged in a particular pattern. When you first gain the ability to cast this spell, you learn the sigil sequences for two destinations on the Material Plane, determined by the GM. You can learn additional sigil sequences during your adventures. You can commit a new sigil sequence to memory after studying it for 1 minute.\n\nYou can create a permanent teleportation circle by casting this spell in the same location every day for one year. You need not use the circle to teleport when you cast the spell in this way.","","",""],
["Tree Stride",5,1,"1 action","Self","Up to 1 minute","VS","",1,0,[2, 4],"You gain the ability to enter a tree and move from inside it to inside another tree of the same kind within 500 feet. Both trees must be living and at least the same size as you. You must use 5 feet of movement to enter a tree. You instantly know the location of all other trees of the same kind within 500 feet and, as part of the move used to enter the tree, can either pass into one of those trees or step out of the tree you're in. You appear in a spot of your choice within 5 feet of the destination tree, using another 5 feet of movement. If you have no movement left, you appear within 5 feet of the tree you entered.\n\nYou can use this transportation ability once per round for the duration. You must end each turn outside a tree.","","",""],
["Wall of Force",5,4,"1 action","120 feet","Up to 10 minutes","VSM","A pinch of powder made by crushing a clear gemstone.",1,0,[7],"An invisible wall of force springs into existence at a point you choose within range. The wall appears in any orientation you choose, as a horizontal or vertical barrier or at an angle. It can be free floating or resting on a solid surface. You can form it into a hemispherical dome or a sphere with a radius of up to 10 feet, or you can shape a flat surface made up of ten 10-foot-by-10-foot panels. Each panel must be contiguous with another panel. In any form, the wall is 1/4 inch thick. It lasts for the duration. If the wall cuts through a creature's space when it appears, the creature is pushed to one side of the wall (your choice which side).\n\nNothing can physically pass through the wall. It is immune to all damage and can't be dispelled by dispel magic. A disintegrate spell destroys the wall instantly, however. The wall also extends into the Ethereal Plane, blocking ethereal travel through the wall.","","",""],
["Wall of Stone",5,4,"1 action","120 feet","Up to 10 minutes","VSM","A small block of granite.",1,0,[2, 5, 7],"A nonmagical wall of solid stone springs into existence at a point you choose within range. The wall is 6 inches thick and is composed of ten 10-foot-by-10-foot panels. Each panel must be contiguous with at least one other panel. Alternatively, you can create 10-foot-by-20-foot panels that are only 3 inches thick.\n\nIf the wall cuts through a creature's space when it appears, the creature is pushed to one side of the wall (your choice). If a creature would be surrounded on all sides by the wall (or the wall and another solid surface), that creature can make a dexterity saving throw. On a success, it can use its reaction to move up to its speed so that it is no longer enclosed by the wall.\n\nThe wall can have any shape you desire, though it can't occupy the same space as a creature or object. The wall doesn't need to be vertical or rest on any firm foundation. It must, however, merge with and be solidly supported by existing stone. Thus, you can use this spell to bridge a chasm or create a ramp.\n\nIf you create a span greater than 20 feet in length, you must halve the size of each panel to create supports. You can crudely shape the wall to create crenellations, battlements, and so on.\n\nThe wall is an object made of stone that can be damaged and thus breached. Each panel has AC 15 and 30 hit points per inch of thickness. Reducing a panel to 0 hit points destroys it and might cause connected panels to collapse at the GM's discretion.\n\nIf you maintain your concentration on this spell for its whole duration, the wall becomes permanent and can't be dispelled. Otherwise, the wall disappears when the spell ends.","","",""],
["Blade Barrier",6,4,"1 action","90 feet","Up to 10 minutes","VS","",1,0,[1],"You create a vertical wall of whirling, razor-sharp blades made of magical energy. The wall appears within range and lasts for the duration. You can make a straight wall up to 100 feet long, 20 feet high, and 5 feet thick, or a ringed wall up to 60 feet in diameter, 20 feet high, and 5 feet thick. The wall provides three-quarters cover to creatures behind it, and its space is difficult terrain.\n\nWhen a creature enters the wall's area for the first time on a turn or starts its turn there, the creature must make a dexterity saving throw. On a failed save, the creature takes 6d10 slashing damage. On a successful save, the creature takes half as much damage.","","Slashing","DEX"],
["Chain Lightning",6,4,"1 action","150 feet","Instantaneous","VSM","A bit of fur; a piece of amber, glass, or a crystal rod; and three silver pins.",0,0,[5, 7],"You create a bolt of lightning that arcs toward a target of your choice that you can see within range. Three bolts then leap from that target to as many as three other targets, each of which must be within 30 feet of the first target. A target can be a creature or an object and can be targeted by only one of the bolts.\n\nA target must make a dexterity saving throw. The target takes 10d8 lightning damage on a failed save, or half as much damage on a successful one.","When you cast this spell using a spell slot of 7th level or higher, one additional bolt leaps from the first target to another target for each slot level above 6th.","Lightning","DEX"],
["Circle of Death",6,6,"1 action","150 feet","Instantaneous","VSM","The powder of a crushed black pearl worth at least 500 gp.",0,0,[5, 6, 7],"A sphere of negative energy ripples out in a 60-foot radius sphere from a point within range. Each creature in that area must make a constitution saving throw. A target takes 8d6 necrotic damage on a failed save, or half as much damage on a successful one.","When you cast this spell using a spell slot of 7th level or higher, the damage increases by 2d6 for each slot level above 6th.","Necrotic","CON"],
["Conjure Fey",6,1,"1 minute","90 feet","Up to 1 hour","VS","",1,0,[2, 6],"You summon a fey creature of challenge rating 6 or lower, or a fey spirit that takes the form of a beast of challenge rating 6 or lower. It appears in an unoccupied space that you can see within range. The fey creature disappears when it drops to 0 hit points or when the spell ends.\n\nThe fey creature is friendly to you and your companions for the duration. Roll initiative for the creature, which has its own turns. It obeys any verbal commands that you issue to it (no action required by you), as long as they don't violate its alignment. If you don't issue any commands to the fey creature, it defends itself from hostile creatures but otherwise takes no actions.\n\nIf your concentration is broken, the fey creature doesn't disappear. Instead, you lose control of the fey creature, it becomes hostile toward you and your companions, and it might attack. An uncontrolled fey creature can't be dismissed by you, and it disappears 1 hour after you summoned it.\n\nThe GM has the fey creature's statistics.","When you cast this spell using a spell slot of 7th level or higher, the challenge rating increases by 1 for each slot level above 6th.","",""],
["Contingency",6,4,"10 minutes","Self","10 days","VSM","A statuette of yourself carved from ivory and decorated with gems worth at least 1,500 gp.",0,0,[7],"Choose a spell of 5th level or lower that you can cast, that has a casting time of 1 action, and that can target you. You cast that spell--called the contingent spell--as part of casting contingency, expending spell slots for both, but the contingent spell doesn't come into effect. Instead, it takes effect when a certain circumstance occurs. You describe that circumstance when you cast the two spells. For example, a contingency cast with water breathing might stipulate that water breathing comes into effect when you are engulfed in water or a similar liquid.\n\nThe contingent spell takes effect immediately after the circumstance is met for the first time, whether or not you want it to. and then contingency ends.\n\nThe contingent spell takes effect only on you, even if it can normally target others. You can use only one contingency spell at a time. If you cast this spell again, the effect of another contingency spell on you ends. Also, contingency ends on you if its material component is ever not on your person.","","",""],
["Create Undead",6,6,"1 minute","10 feet","Instantaneous","VSM","One clay pot filled with grave dirt, one clay pot filled with brackish water, and one 150 gp black onyx stone for each corpse.",0,0,[1, 6, 7],"You can cast this spell only at night. Choose up to three corpses of Medium or Small humanoids within range. Each corpse becomes a ghoul under your control. (The GM has game statistics for these creatures.)\n\nAs a bonus action on each of your turns, you can mentally command any creature you animated with this spell if the creature is within 120 feet of you (if you control multiple creatures, you can command any or all of them at the same time, issuing the same command to each one). You decide what action the creature will take and where it will move during its next turn, or you can issue a general command, such as to guard a particular chamber or corridor. If you issue no commands, the creature only defends itself against hostile creatures. Once given an order, the creature continues to follow it until its task is complete.\n\nThe creature is under your control for 24 hours, after which it stops obeying any command you have given it. To maintain control of the creature for another 24 hours, you must cast this spell on the creature before the current 24-hour period ends. This use of the spell reasserts your control over up to three creatures you have animated with this spell, rather than animating new ones.","When you cast this spell using a 7th-level spell slot, you can animate or reassert control over four ghouls. When you cast this spell using an 8th-level spell slot, you can animate or reassert control over five ghouls or two ghasts or wights. When you cast this spell using a 9th-level spell slot, you can animate or reassert control over six ghouls, three ghasts or wights, or two mummies.","",""],
["Disintegrate",6,7,"1 action","60 feet","Instantaneous","VSM","A lodestone and a pinch of dust.",0,0,[5, 7],"A thin green ray springs from your pointing finger to a target that you can see within range. The target can be a creature, an object, or a creation of magical force, such as the wall created by wall of force.\n\nA creature targeted by this spell must make a dexterity saving throw. On a failed save, the target takes 10d6 + 40 force damage. If this damage reduces the target to 0 hit points, it is disintegrated.\n\nA disintegrated creature and everything it is wearing and carrying, except magic items, are reduced to a pile of fine gray dust. The creature can be restored to life only by means of a true resurrection or a wish spell.\n\nThis spell automatically disintegrates a Large or smaller nonmagical object or a creation of magical force. If the target is a Huge or larger object or creation of force, this spell disintegrates a 10-foot-cube portion of it. A magic item is unaffected by this spell.","When you cast this spell using a spell slot of 7th level or higher, the damage increases by 3d6 for each slot level above 6th.","Force","DEX"],
["Eyebite",6,6,"1 action","Self","Up to 1 minute","VS","",1,0,[0, 5, 6, 7],"For the spell's duration, your eyes become an inky void imbued with dread power. One creature of your choice within 60 feet of you that you can see must succeed on a wisdom saving throw or be affected by one of the following effects of your choice for the duration. On each of your turns until the spell ends, you can use your action to target another creature but can't target a creature again if it has succeeded on a saving throw against this casting of eyebite.\n\n***Asleep.*** The target falls unconscious. It wakes up if it takes any damage or if another creature uses its action to shake the sleeper awake.\n\n***Panicked.*** The target is frightened of you. On each of its turns, the frightened creature must take the Dash action and move away from you by the safest and shortest available route, unless there is nowhere to move. If the target moves to a place at least 60 feet away from you where it can no longer see you, this effect ends.\n\n***Sickened.*** The target has disadvantage on attack rolls and ability checks. At the end of each of its turns, it can make another wisdom saving throw. If it succeeds, the effect ends.","","","WIS"],
["Find the Path",6,2,"1 minute","Self","Up to 24 hours","VSM","A set of divinatory tools--such as bones, ivory sticks, cards, teeth, or carved runes--worth 100gp and an object from the location you wish to find.",1,0,[0, 1, 2],"This spell allows you to find the shortest, most direct physical route to a specific fixed location that you are familiar with on the same plane of existence. If you name a destination on another plane of existence, a destination that moves (such as a mobile fortress), or a destination that isn't specific (such as \"a green dragon's lair\"), the spell fails.\n\nFor the duration, as long as you are on the same plane of existence as the destination, you know how far it is and in what direction it lies. While you are traveling there, whenever you are presented with a choice of paths along the way, you automatically determine which path is the shortest and most direct route (but not necessarily the safest route) to the destination.","","",""],
["Flesh to Stone",6,7,"1 action","60 feet","Up to 1 minute","VSM","A pinch of lime, water, and earth.",1,0,[6, 7],"You attempt to turn one creature that you can see within range into stone. If the target's body is made of flesh, the creature must make a constitution saving throw. On a failed save, it is restrained as its flesh begins to harden. On a successful save, the creature isn't affected.\n\nA creature restrained by this spell must make another constitution saving throw at the end of each of its turns. If it successfully saves against this spell three times, the spell ends. If it fails its saves three times, it is turned to stone and subjected to the petrified condition for the duration. The successes and failures don't need to be consecutive; keep track of both until the target collects three of a kind.\n\nIf the creature is physically broken while petrified, it suffers from similar deformities if it reverts to its original state.\n\nIf you maintain your concentration on this spell for the entire possible duration, the creature is turned to stone until the effect is removed.","","","CON"],
["Forbiddance",6,0,"10 minutes","Touch","24 hours","VSM","A sprinkling of holy water, rare incense, and powdered ruby worth at least 1,000 gp.",0,1,[1],"You create a ward against magical travel that protects up to 40,000 square feet of floor space to a height of 30 feet above the floor. For the duration, creatures can't teleport into the area or use portals, such as those created by the gate spell, to enter the area. The spell proofs the area against planar travel, and therefore prevents creatures from accessing the area by way of the Astral Plane, Ethereal Plane, Feywild, Shadowfell, or the plane shift spell.\n\nIn addition, the spell damages types of creatures that you choose when you cast it. Choose one or more of the following: celestials, elementals, fey, fiends, and undead. When a chosen creature enters the spell's area for the first time on a turn or starts its turn there, the creature takes 5d10 radiant or necrotic damage (your choice when you cast this spell).\n\nWhen you cast this spell, you can designate a password. A creature that speaks the password as it enters the area takes no damage from the spell.\n\nThe spell's area can't overlap with the area of another forbiddance spell. If you cast forbiddance every day for 30 days in the same location, the spell lasts until it is dispelled, and the material components are consumed on the last casting.","","",""],
["Freezing Sphere",6,4,"1 action","300 feet","Instantaneous","VSM","A small crystal sphere.",0,0,[7],"A frigid globe of cold energy streaks from your fingertips to a point of your choice within range, where it explodes in a 60-foot-radius sphere. Each creature within the area must make a constitution saving throw. On a failed save, a creature takes 10d6 cold damage. On a successful save, it takes half as much damage.\n\nIf the globe strikes a body of water or a liquid that is principally water (not including water-based creatures), it freezes the liquid to a depth of 6 inches over an area 30 feet square. This ice lasts for 1 minute. Creatures that were swimming on the surface of frozen water are trapped in the ice. A trapped creature can use an action to make a Strength check against your spell save DC to break free.\n\nYou can refrain from firing the globe after completing the spell, if you wish. A small globe about the size of a sling stone, cool to the touch, appears in your hand. At any time, you or a creature you give the globe to can throw the globe (to a range of 40 feet) or hurl it with a sling (to the sling's normal range). It shatters on impact, with the same effect as the normal casting of the spell. You can also set the globe down without shattering it. After 1 minute, if the globe hasn't already shattered, it explodes.","When you cast this spell using a spell slot of 7th level or higher, the damage increases by 1d6 for each slot level above 6th.","Cold","CON"],
["Globe of Invulnerability",6,0,"1 action","Self","Up to 1 minute","VSM","A glass or crystal bead that shatters when the spell ends.",1,0,[5, 7],"An immobile, faintly shimmering barrier springs into existence in a 10-foot radius around you and remains for the duration.\n\nAny spell of 5th level or lower cast from outside the barrier can't affect creatures or objects within it, even if the spell is cast using a higher level spell slot. Such a spell can target creatures and objects within the barrier, but the spell has no effect on them. Similarly, the area within the barrier is excluded from the areas affected by such spells.","When you cast this spell using a spell slot of 7th level or higher, the barrier blocks spells of one level higher for each slot level above 6th.","",""],
["Guards and Wards",6,0,"10 minutes","Touch","24 hours","VSM","Burning incense, a small measure of brimstone and oil, a knotted string, a small amount of umber hulk blood, and a small silver rod worth at least 10 gp.",0,0,[0, 7],"You create a ward that protects up to 2,500 square feet of floor space (an area 50 feet square, or one hundred 5-foot squares or twenty-five 10-foot squares). The warded area can be up to 20 feet tall, and shaped as you desire. You can ward several stories of a stronghold by dividing the area among them, as long as you can walk into each contiguous area while you are casting the spell.\n\nWhen you cast this spell, you can specify individuals that are unaffected by any or all of the effects that you choose. You can also specify a password that, when spoken aloud, makes the speaker immune to these effects.\n\nGuards and wards creates the following effects within the warded area.\n\n***Corridors.*** Fog fills all the warded corridors, making them heavily obscured. In addition, at each intersection or branching passage offering a choice of direction, there is a 50 percent chance that a creature other than you will believe it is going in the opposite direction from the one it chooses.\n\n***Doors.*** All doors in the warded area are magically locked, as if sealed by an arcane lock spell. In addition, you can cover up to ten doors with an illusion (equivalent to the illusory object function of the minor illusion spell) to make them appear as plain sections of wall.\n\n***Stairs.*** Webs fill all stairs in the warded area from top to bottom, as the web spell. These strands regrow in 10 minutes if they are burned or torn away while guards and wards lasts.\n\n***Other Spell Effect.*** You can place your choice of one of the following magical effects within the warded area of the stronghold.\n\n- Place dancing lights in four corridors. You can designate a simple program that the lights repeat as long as guards and wards lasts.\n\n- Place magic mouth in two locations.\n\n- Place stinking cloud in two locations. The vapors appear in the places you designate; they return within 10 minutes if dispersed by wind while guards and wards lasts.\n\n- Place a constant gust of wind in one corridor or room.\n\n- Place a suggestion in one location. You select an area of up to 5 feet square, and any creature that enters or passes through the area receives the suggestion mentally.\n\nThe whole warded area radiates magic. A dispel magic cast on a specific effect, if successful, removes only that effect.\n\nYou can create a permanently guarded and warded structure by casting this spell there every day for one year.","","",""],
["Harm",6,6,"1 action","60 feet","Instantaneous","VS","",0,0,[1],"You unleash a virulent disease on a creature that you can see within range. The target must make a constitution saving throw. On a failed save, it takes 14d6 necrotic damage, or half as much damage on a successful save. The damage can't reduce the target's hit points below 1. If the target fails the saving throw, its hit point maximum is reduced for 1 hour by an amount equal to the necrotic damage it took. Any effect that removes a disease allows a creature's hit point maximum to return to normal before that time passes.","","Necrotic","CON"],
["Heal",6,4,"1 action","60 feet","Instantaneous","VS","",0,0,[1, 2],"Choose a creature that you can see within range. A surge of positive energy washes through the creature, causing it to regain 70 hit points. This spell also ends blindness, deafness, and any diseases affecting the target. This spell has no effect on constructs or undead.","When you cast this spell using a spell slot of 7th level or higher, the amount of healing increases by 10 for each slot level above 6th.","",""],
["Heroes' Feast",6,1,"10 minutes","30 feet","Instantaneous","VSM","A gem-encrusted bowl worth at least 1,000gp, which the spell consumes.",0,0,[1, 2],"You bring forth a great feast, including magnificent food and drink. The feast takes 1 hour to consume and disappears at the end of that time, and the beneficial effects don't set in until this hour is over. Up to twelve other creatures can partake of the feast.\n\nA creature that partakes of the feast gains several benefits. The creature is cured of all diseases and poison, becomes immune to poison and being frightened, and makes all wisdom saving throws with advantage. Its hit point maximum also increases by 2d10, and it gains the same number of hit points. These benefits last for 24 hours.","","",""],
["Instant Summons",6,1,"1 minute","Touch","Until dispelled","VSM","A sapphire worth 1,000 gp.",0,1,[7],"You touch an object weighing 10 pounds or less whose longest dimension is 6 feet or less. The spell leaves an invisible mark on its surface and invisibly inscribes the name of the item on the sapphire you use as the material component. Each time you cast this spell, you must use a different sapphire.\n\nAt any time thereafter, you can use your action to speak the item's name and crush the sapphire. The item instantly appears in your hand regardless of physical or planar distances, and the spell ends.\n\nIf another creature is holding or carrying the item, crushing the sapphire doesn't transport the item to you, but instead you learn who the creature possessing the object is and roughly where that creature is located at that moment.\n\nDispel magic or a similar effect successfully applied to the sapphire ends this spell's effect.","","",""],
["Irresistible Dance",6,3,"1 action","30 feet","Up to 1 minute","V","",1,0,[0, 7],"Choose one creature that you can see within range. The target begins a comic dance in place: shuffling, tapping its feet, and capering for the duration. Creatures that can't be charmed are immune to this spell.\n\nA dancing creature must use all its movement to dance without leaving its space and has disadvantage on dexterity saving throws and attack rolls. While the target is affected by this spell, other creatures have advantage on attack rolls against it. As an action, a dancing creature makes a wisdom saving throw to regain control of itself. On a successful save, the spell ends.","","",""],
["Magic Jar",6,6,"1 minute","Self","Until dispelled","VSM","A gem, crystal, reliquary, or some other ornamental container worth at least 500 gp.",0,0,[7],"Your body falls into a catatonic state as your soul leaves it and enters the container you used for the spell's material component. While your soul inhabits the container, you are aware of your surroundings as if you were in the container's space. You can't move or use reactions. The only action you can take is to project your soul up to 100 feet out of the container, either returning to your living body (and ending the spell) or attempting to possess a humanoids body.\n\nYou can attempt to possess any humanoid within 100 feet of you that you can see (creatures warded by a protection from evil and good or magic circle spell can't be possessed). The target must make a charisma saving throw. On a failure, your soul moves into the target's body, and the target's soul becomes trapped in the container. On a success, the target resists your efforts to possess it, and you can't attempt to possess it again for 24 hours.\n\nOnce you possess a creature's body, you control it. Your game statistics are replaced by the statistics of the creature, though you retain your alignment and your Intelligence, Wisdom, and Charisma scores. You retain the benefit of your own class features. If the target has any class levels, you can't use any of its class features.\n\nMeanwhile, the possessed creature's soul can perceive from the container using its own senses, but it can't move or take actions at all.\n\nWhile possessing a body, you can use your action to return from the host body to the container if it is within 100 feet of you, returning the host creature's soul to its body. If the host body dies while you're in it, the creature dies, and you must make a charisma saving throw against your own spellcasting DC. On a success, you return to the container if it is within 100 feet of you. Otherwise, you die.\n\nIf the container is destroyed or the spell ends, your soul immediately returns to your body. If your body is more than 100 feet away from you or if your body is dead when you attempt to return to it, you die. If another creature's soul is in the container when it is destroyed, the creature's soul returns to its body if the body is alive and within 100 feet. Otherwise, that creature dies.\n\nWhen the spell ends, the container is destroyed.","","","CHA"],
["Mass Suggestion",6,3,"1 action","60 feet","24 hours","VM","A snake's tongue and either a bit of honeycomb or a drop of sweet oil.",0,0,[0, 5, 6, 7],"You suggest a course of activity (limited to a sentence or two) and magically influence up to twelve creatures of your choice that you can see within range and that can hear and understand you. Creatures that can't be charmed are immune to this effect. The suggestion must be worded in such a manner as to make the course of action sound reasonable. Asking the creature to stab itself, throw itself onto a spear, immolate itself, or do some other obviously harmful act automatically negates the effect of the spell.\n\nEach target must make a wisdom saving throw. On a failed save, it pursues the course of action you described to the best of its ability. The suggested course of action can continue for the entire duration. If the suggested activity can be completed in a shorter time, the spell ends when the subject finishes what it was asked to do.\n\nYou can also specify conditions that will trigger a special activity during the duration. For example, you might suggest that a group of soldiers give all their money to the first beggar they meet. If the condition isn't met before the spell ends, the activity isn't performed.\n\nIf you or any of your companions damage a creature affected by this spell, the spell ends for that creature.","When you cast this spell using a 7th-level spell slot, the duration is 10 days. When you use an 8th-level spell slot, the duration is 30 days. When you use a 9th-level spell slot, the duration is a year and a day.","","WIS"],
["Move Earth",6,7,"1 action","120 feet","Up to 2 hours","VSM","An iron blade and a small bag containing a mixture of soils--clay, loam, and sand.",1,0,[2, 5, 7],"Choose an area of terrain no larger than 40 feet on a side within range. You can reshape dirt, sand, or clay in the area in any manner you choose for the duration. You can raise or lower the area's elevation, create or fill in a trench, erect or flatten a wall, or form a pillar. The extent of any such changes can't exceed half the area's largest dimension. So, if you affect a 40-foot square, you can create a pillar up to 20 feet high, raise or lower the square's elevation by up to 20 feet, dig a trench up to 20 feet deep, and so on. It takes 10 minutes for these changes to complete.\n\nAt the end of every 10 minutes you spend concentrating on the spell, you can choose a new area of terrain to affect.\n\nBecause the terrain's transformation occurs slowly, creatures in the area can't usually be trapped or injured by the ground's movement.\n\nThis spell can't manipulate natural stone or stone construction. Rocks and structures shift to accommodate the new terrain. If the way you shape the terrain would make a structure unstable, it might collapse.\n\nSimilarly, this spell doesn't directly affect plant growth. The moved earth carries any plants along with it.","","",""],
["Planar Ally",6,1,"10 minutes","60 feet","Instantaneous","VS","",0,0,[1],"You beseech an otherworldly entity for aid. The being must be known to you: a god, a primordial, a demon prince, or some other being of cosmic power. That entity sends a celestial, an elemental, or a fiend loyal to it to aid you, making the creature appear in an unoccupied space within range. If you know a specific creature's name, you can speak that name when you cast this spell to request that creature, though you might get a different creature anyway (GM's choice).\n\nWhen the creature appears, it is under no compulsion to behave in any particular way. You can ask the creature to perform a service in exchange for payment, but it isn't obliged to do so. The requested task could range from simple (fly us across the chasm, or help us fight a battle) to complex (spy on our enemies, or protect us during our foray into the dungeon). You must be able to communicate with the creature to bargain for its services.\n\nPayment can take a variety of forms. A celestial might require a sizable donation of gold or magic items to an allied temple, while a fiend might demand a living sacrifice or a gift of treasure. Some creatures might exchange their service for a quest undertaken by you.\n\nAs a rule of thumb, a task that can be measured in minutes requires a payment worth 100 gp per minute. A task measured in hours requires 1,000 gp per hour. And a task measured in days (up to 10 days) requires 10,000 gp per day. The GM can adjust these payments based on the circumstances under which you cast the spell. If the task is aligned with the creature's ethos, the payment might be halved or even waived. Nonhazardous tasks typically require only half the suggested payment, while especially dangerous tasks might require a greater gift. Creatures rarely accept tasks that seem suicidal.\n\nAfter the creature completes the task, or when the agreed-upon duration of service expires, the creature returns to its home plane after reporting back to you, if appropriate to the task and if possible. If you are unable to agree on a price for the creature's service, the creature immediately returns to its home plane.\n\nA creature enlisted to join your group counts as a member of it, receiving a full share of experience points awarded.","","",""],
["Programmed Illusion",6,5,"1 action","120 feet","Until dispelled","VSM","A bit of fleece and jade dust worth at least 25 gp.",0,0,[0, 7],"You create an illusion of an object, a creature, or some other visible phenomenon within range that activates when a specific condition occurs. The illusion is imperceptible until then. It must be no larger than a 30-foot cube, and you decide when you cast the spell how the illusion behaves and what sounds it makes. This scripted performance can last up to 5 minutes.\n\nWhen the condition you specify occurs, the illusion springs into existence and performs in the manner you described. Once the illusion finishes performing, it disappears and remains dormant for 10 minutes. After this time, the illusion can be activated again.\n\nThe triggering condition can be as general or as detailed as you like, though it must be based on visual or audible conditions that occur within 30 feet of the area. For example, you could create an illusion of yourself to appear and warn off others who attempt to open a trapped door, or you could set the illusion to trigger only when a creature says the correct word or phrase.\n\nPhysical interaction with the image reveals it to be an illusion, because things can pass through it. A creature that uses its action to examine the image can determine that it is an illusion with a successful Intelligence (Investigation) check against your spell save DC. If a creature discerns the illusion for what it is, the creature can see through the image, and any noise it makes sounds hollow to the creature.","","",""],
["Sunbeam",6,4,"1 action","Self","Up to 1 minute","VSM","A magnifying glass.",1,0,[2, 5, 7],"A beam of brilliant light flashes out from your hand in a 5-foot-wide, 60-foot-long line. Each creature in the line must make a constitution saving throw. On a failed save, a creature takes 6d8 radiant damage and is blinded until your next turn. On a successful save, it takes half as much damage and isn't blinded by this spell. Undead and oozes have disadvantage on this saving throw.\n\nYou can create a new line of radiance as your action on any turn until the spell ends.\n\nFor the duration, a mote of brilliant radiance shines in your hand. It sheds bright light in a 30-foot radius and dim light for an additional 30 feet. This light is sunlight.","","Radiant","CON"],
["Transport via Plants",6,1,"1 action","10 feet","1 round","VS","",0,0,[2],"This spell creates a magical link between a Large or larger inanimate plant within range and another plant, at any distance, on the same plane of existence. You must have seen or touched the destination plant at least once before. For the duration, any creature can step into the target plant and exit from the destination plant by using 5 feet of movement.","","",""],
["True Seeing",6,2,"1 action","Touch","1 hour","VSM","An ointment for the eyes that costs 25gp; is made from mushroom powder, saffron, and fat; and is consumed by the spell.",0,0,[0, 1, 5, 6, 7],"This spell gives the willing creature you touch the ability to see things as they actually are. For the duration, the creature has truesight, notices secret doors hidden by magic, and can see into the Ethereal Plane, all out to a range of 120 feet.","","",""],
["Wall of Ice",6,4,"1 action","120 feet","Up to 10 minutes","VSM","A small piece of quartz.",1,0,[7],"You create a wall of ice on a solid surface within range. You can form it into a hemispherical dome or a sphere with a radius of up to 10 feet, or you can shape a flat surface made up of ten 10-foot-square panels. Each panel must be contiguous with another panel. In any form, the wall is 1 foot thick and lasts for the duration.\n\nIf the wall cuts through a creature's space when it appears, the creature within its area is pushed to one side of the wall and must make a dexterity saving throw. On a failed save, the creature takes 10d6 cold damage, or half as much damage on a successful save.\n\nThe wall is an object that can be damaged and thus breached. It has AC 12 and 30 hit points per 10-foot section, and it is vulnerable to fire damage. Reducing a 10-foot section of wall to 0 hit points destroys it and leaves behind a sheet of frigid air in the space the wall occupied. A creature moving through the sheet of frigid air for the first time on a turn must make a constitution saving throw. That creature takes 5d6 cold damage on a failed save, or half as much damage on a successful one.","When you cast this spell using a spell slot of 7th level or higher, the damage the wall deals when it appears increases by 2d6, and the damage from passing through the sheet of frigid air increases by 1d6, for each slot level above 6th.","Cold","DEX"],
["Wall of Thorns",6,1,"1 action","120 feet","Up to 10 minutes","VSM","A handful of thorns.",1,0,[2],"You create a wall of tough, pliable, tangled brush bristling with needle-sharp thorns. The wall appears within range on a solid surface and lasts for the duration. You choose to make the wall up to 60 feet long, 10 feet high, and 5 feet thick or a circle that has a 20-foot diameter and is up to 20 feet high and 5 feet thick. The wall blocks line of sight.\n\nWhen the wall appears, each creature within its area must make a dexterity saving throw. On a failed save, a creature takes 7d8 piercing damage, or half as much damage on a successful save.\n\nA creature can move through the wall, albeit slowly and painfully. For every 1 foot a creature moves through the wall, it must spend 4 feet of movement. Furthermore, the first time a creature enters the wall on a turn or ends its turn there, the creature must make a dexterity saving throw. It takes 7d8 slashing damage on a failed save, or half as much damage on a successful one.","When you cast this spell using a spell slot of 7th level or higher, both types of damage increase by 1d8 for each slot level above 6th.","Piercing","DEX"],
["Wind Walk",6,7,"1 minute","30 feet","8 hours","VSM","Fire and holy water.",0,0,[2],"You and up to ten willing creatures you can see within range assume a gaseous form for the duration, appearing as wisps of cloud. While in this cloud form, a creature has a flying speed of 300 feet and has resistance to damage from nonmagical weapons. The only actions a creature can take in this form are the Dash action or to revert to its normal form. Reverting takes 1 minute, during which time a creature is incapacitated and can't move. Until the spell ends, a creature can revert to cloud form, which also requires the 1-minute transformation.\n\nIf a creature is in cloud form and flying when the effect ends, the creature descends 60 feet per round for 1 minute until it lands, which it does safely. If it can't land after 1 minute, the creature falls the remaining distance.","","",""],
["Word of Recall",6,1,"1 action","5 feet","Instantaneous","V","",0,0,[1],"You and up to five willing creatures within 5 feet of you instantly teleport to a previously designated sanctuary. You and any creatures that teleport with you appear in the nearest unoccupied space to the spot you designated when you prepared your sanctuary (see below). If you cast this spell without first preparing a sanctuary, the spell has no effect.\n\nYou must designate a sanctuary by casting this spell within a location, such as a temple, dedicated to or strongly linked to your deity. If you attempt to cast the spell in this manner in an area that isn't dedicated to your deity, the spell has no effect.","","",""],
["Arcane Sword",7,4,"1 action","60 feet","Up to 1 minute","VSM","A miniature platinum sword with a grip and pommel of copper and zinc, worth 250 gp.",1,0,[0, 7],"You create a sword-shaped plane of force that hovers within range. It lasts for the duration.\n\nWhen the sword appears, you make a melee spell attack against a target of your choice within 5 feet of the sword. On a hit, the target takes 3d10 force damage. Until the spell ends, you can use a bonus action on each of your turns to move the sword up to 20 feet to a spot you can see and repeat this attack against the same target or a different one.","","Force",""],
["Conjure Celestial",7,1,"1 minute","90 feet","Up to 1 hour","VS","",1,0,[1],"You summon a celestial of challenge rating 4 or lower, which appears in an unoccupied space that you can see within range. The celestial disappears when it drops to 0 hit points or when the spell ends.\n\nThe celestial is friendly to you and your companions for the duration. Roll initiative for the celestial, which has its own turns. It obeys any verbal commands that you issue to it (no action required by you), as long as they don't violate its alignment. If you don't issue any commands to the celestial, it defends itself from hostile creatures but otherwise takes no actions.\n\nThe GM has the celestial's statistics.","When you cast this spell using a 9th-level spell slot, you summon a celestial of challenge rating 5 or lower.","",""],
["Delayed Blast Fireball",7,4,"1 action","150 feet","Up to 1 minute","VSM","A tiny ball of bat guano and sulfur.",1,0,[5, 7],"A beam of yellow light flashes from your pointing finger, then condenses to linger at a chosen point within range as a glowing bead for the duration. When the spell ends, either because your concentration is broken or because you decide to end it, the bead blossoms with a low roar into an explosion of flame that spreads around corners. Each creature in a 20-foot-radius sphere centered on that point must make a dexterity saving throw. A creature takes fire damage equal to the total accumulated damage on a failed save, or half as much damage on a successful one.\n\nThe spell's base damage is 12d6. If at the end of your turn the bead has not yet detonated, the damage increases by 1d6.\n\nIf the glowing bead is touched before the interval has expired, the creature touching it must make a dexterity saving throw. On a failed save, the spell ends immediately, causing the bead to erupt in flame. On a successful save, the creature can throw the bead up to 40 feet. When it strikes a creature or a solid object, the spell ends, and the bead explodes.\n\nThe fire damages objects in the area and ignites flammable objects that aren't being worn or carried.","When you cast this spell using a spell slot of 8th level or higher, the base damage increases by 1d6 for each slot level above 7th.","Fire","DEX"],
["Divine Word",7,4,"1 bonus action","30 feet","Instantaneous","V","",0,0,[1],"You utter a divine word, imbued with the power that shaped the world at the dawn of creation. Choose any number of creatures you can see within range. Each creature that can hear you must make a Charisma saving throw. On a failed save, a creature suffers an effect based on its current hit points:\n\n- 50 hit points or fewer: deafened for 1 minute\n\n- 40 hit points or fewer: deafened and blinded for 10 minutes\n\n- 30 hit points or fewer: blinded, deafened, and stunned for 1 hour\n\n- 20 hit points or fewer: killed instantly\n\nRegardless of its current hit points, a celestial, an elemental, a fey, or a fiend that fails its save is forced back to its plane of origin (if it isn't there already) and can't return to your current plane for 24 hours by any means short of a wish spell.","","","CHA"],
["Etherealness",7,7,"1 action","Self","8 hours","VS","",0,0,[0, 1, 5, 6, 7],"You step into the border regions of the Ethereal Plane, in the area where it overlaps with your current plane. You remain in the Border Ethereal for the duration or until you use your action to dismiss the spell. During this time, you can move in any direction. If you move up or down, every foot of movement costs an extra foot. You can see and hear the plane you originated from, but everything there looks gray, and you can't see anything more than 60 feet away.\n\nWhile on the Ethereal Plane, you can only affect and be affected by other creatures on that plane. Creatures that aren't on the Ethereal Plane can't perceive you and can't interact with you, unless a special ability or magic has given them the ability to do so.\n\nYou ignore all objects and effects that aren't on the Ethereal Plane, allowing you to move through objects you perceive on the plane you originated from.\n\nWhen the spell ends, you immediately return to the plane you originated from in the spot you currently occupy. If you occupy the same spot as a solid object or creature when this happens, you are immediately shunted to the nearest unoccupied space that you can occupy and take force damage equal to twice the number of feet you are moved.\n\nThis spell has no effect if you cast it while you are on the Ethereal Plane or a plane that doesn't border it, such as one of the Outer Planes.","When you cast this spell using a spell slot of 8th level or higher, you can target up to three willing creatures (including you) for each slot level above 7th. The creatures must be within 10 feet of you when you cast the spell.","",""],
["Finger of Death",7,6,"1 action","60 feet","Instantaneous","VS","",0,0,[5, 6, 7],"You send negative energy coursing through a creature that you can see within range, causing it searing pain. The target must make a constitution saving throw. It takes 7d8 + 30 necrotic damage on a failed save, or half as much damage on a successful one.\n\nA humanoid killed by this spell rises at the start of your next turn as a zombie that is permanently under your command, following your verbal orders to the best of its ability.","","Necrotic","CON"],
["Fire Storm",7,4,"1 action","150 feet","Instantaneous","VS","",0,0,[1, 2, 5],"A storm made up of sheets of roaring flame appears in a location you choose within range. The area of the storm consists of up to ten 10-foot cubes, which you can arrange as you wish. Each cube must have at least one face adjacent to the face of another cube. Each creature in the area must make a dexterity saving throw. It takes 7d10 fire damage on a failed save, or half as much damage on a successful one.\n\nThe fire damages objects in the area and ignites flammable objects that aren't being worn or carried. If you choose, plant life in the area is unaffected by this spell.","","Fire","DEX"],
["Forcecage",7,4,"1 action","100 feet","1 hour","VSM","Ruby dust worth 1,500 gp.",0,0,[0, 6, 7],"An immobile, invisible, cube-shaped prison composed of magical force springs into existence around an area you choose within range. The prison can be a cage or a solid box, as you choose.\n\nA prison in the shape of a cage can be up to 20 feet on a side and is made from 1/2-inch diameter bars spaced 1/2 inch apart.\n\nA prison in the shape of a box can be up to 10 feet on a side, creating a solid barrier that prevents any matter from passing through it and blocking any spells cast into or out from the area.\n\nWhen you cast the spell, any creature that is completely inside the cage's area is trapped. Creatures only partially within the area, or those too large to fit inside the area, are pushed away from the center of the area until they are completely outside the area.\n\nA creature inside the cage can't leave it by nonmagical means. If the creature tries to use teleportation or interplanar travel to leave the cage, it must first make a charisma saving throw. On a success, the creature can use that magic to exit the cage. On a failure, the creature can't exit the cage and wastes the use of the spell or effect. The cage also extends into the Ethereal Plane, blocking ethereal travel.\n\nThis spell can't be dispelled by dispel magic.","","",""],
["Magnificent Mansion",7,1,"1 minute","300 feet","24 hours","VSM","A miniature portal carved from ivory, a small piece of polished marble, and a tiny silver spoon, each item worth at least 5 gp.",0,0,[0, 7],"You conjure an extradimensional dwelling in range that lasts for the duration. You choose where its one entrance is located. The entrance shimmers faintly and is 5 feet wide and 10 feet tall. You and any creature you designate when you cast the spell can enter the extradimensional dwelling as long as the portal remains open. You can open or close the portal if you are within 30 feet of it. While closed, the portal is invisible.\n\nBeyond the portal is a magnificent foyer with numerous chambers beyond. The atmosphere is clean, fresh, and warm.\n\nYou can create any floor plan you like, but the space can't exceed 50 cubes, each cube being 10 feet on each side. The place is furnished and decorated as you choose. It contains sufficient food to serve a nine course banquet for up to 100 people. A staff of 100 near-transparent servants attends all who enter. You decide the visual appearance of these servants and their attire. They are completely obedient to your orders. Each servant can perform any task a normal human servant could perform, but they can't attack or take any action that would directly harm another creature. Thus the servants can fetch things, clean, mend, fold clothes, light fires, serve food, pour wine, and so on. The servants can go anywhere in the mansion but can't leave it. Furnishings and other objects created by this spell dissipate into smoke if removed from the mansion. When the spell ends, any creatures inside the extradimensional space are expelled into the open spaces nearest to the entrance.","","",""],
["Mirage Arcane",7,5,"10 minutes","Sight","10 days","VS","",0,0,[0, 2, 7],"You make terrain in an area up to 1 mile square look, sound, smell, and even feel like some other sort of terrain. The terrain's general shape remains the same, however. Open fields or a road could be made to resemble a swamp, hill, crevasse, or some other difficult or impassable terrain. A pond can be made to seem like a grassy meadow, a precipice like a gentle slope, or a rock-strewn gully like a wide and smooth road.\n\nSimilarly, you can alter the appearance of structures, or add them where none are present. The spell doesn't disguise, conceal, or add creatures.\n\nThe illusion includes audible, visual, tactile, and olfactory elements, so it can turn clear ground into difficult terrain (or vice versa) or otherwise impede movement through the area. Any piece of the illusory terrain (such as a rock or stick) that is removed from the spell's area disappears immediately.\n\nCreatures with truesight can see through the illusion to the terrain's true form; however, all other elements of the illusion remain, so while the creature is aware of the illusion's presence, the creature can still physically interact with the illusion.","","",""],
["Plane Shift",7,1,"1 action","Touch","Instantaneous","VSM","A forked, metal rod worth at least 250 gp, attuned to a particular plane of existence.",0,0,[1, 2, 5, 6, 7],"You and up to eight willing creatures who link hands in a circle are transported to a different plane of existence. You can specify a target destination in general terms, such as the City of Brass on the Elemental Plane of Fire or the palace of Dispater on the second level of the Nine Hells, and you appear in or near that destination. If you are trying to reach the City of Brass, for example, you might arrive in its Street of Steel, before its Gate of Ashes, or looking at the city from across the Sea of Fire, at the GM's discretion.\n\nAlternatively, if you know the sigil sequence of a teleportation circle on another plane of existence, this spell can take you to that circle. If the teleportation circle is too small to hold all the creatures you transported, they appear in the closest unoccupied spaces next to the circle.\n\nYou can use this spell to banish an unwilling creature to another plane. Choose a creature within your reach and make a melee spell attack against it. On a hit, the creature must make a charisma saving throw. If the creature fails this save, it is transported to a random location on the plane of existence you specify. A creature so transported must find its own way back to your current plane of existence.","","","CHA"],
["Prismatic Spray",7,4,"1 action","Self","Instantaneous","VS","",0,0,[5, 7],"Eight multicolored rays of light flash from your hand. Each ray is a different color and has a different power and purpose. Each creature in a 60-foot cone must make a dexterity saving throw. For each target, roll a d8 to determine which color ray affects it.\n\n***1. Red.*** The target takes 10d6 fire damage on a failed save, or half as much damage on a successful one.\n\n***2. Orange.*** The target takes 10d6 acid damage on a failed save, or half as much damage on a successful one.\n\n***3. Yellow.*** The target takes 10d6 lightning damage on a failed save, or half as much damage on a successful one.\n\n***4. Green.*** The target takes 10d6 poison damage on a failed save, or half as much damage on a successful one.\n\n***5. Blue.*** The target takes 10d6 cold damage on a failed save, or half as much damage on a successful one.\n\n***6. Indigo.*** On a failed save, the target is restrained. It must then make a constitution saving throw at the end of each of its turns. If it successfully saves three times, the spell ends. If it fails its save three times, it permanently turns to stone and is subjected to the petrified condition. The successes and failures don't need to be consecutive; keep track of both until the target collects three of a kind.\n\n***7. Violet.*** On a failed save, the target is blinded. It must then make a wisdom saving throw at the start of your next turn. A successful save ends the blindness. If it fails that save, the creature is transported to another plane of existence of the GM's choosing and is no longer blinded. (Typically, a creature that is on a plane that isn't its home plane is banished home, while other creatures are usually cast into the Astral or Ethereal planes.)\n\n***8. Special.*** The target is struck by two rays. Roll twice more, rerolling any 8.","","","DEX"],
["Project Image",7,5,"1 action","500 miles","Up to 24 hours","VSM","A small replica of you made from materials worth at least 5 gp.",1,0,[0, 7],"You create an illusory copy of yourself that lasts for the duration. The copy can appear at any location within range that you have seen before, regardless of intervening obstacles. The illusion looks and sounds like you but is intangible. If the illusion takes any damage, it disappears, and the spell ends.\n\nYou can use your action to move this illusion up to twice your speed, and make it gesture, speak, and behave in whatever way you choose. It mimics your mannerisms perfectly.\n\nYou can see through its eyes and hear through its ears as if you were in its space. On your turn as a bonus action, you can switch from using its senses to using your own, or back again. While you are using its senses, you are blinded and deafened in regard to your own surroundings.\n\nPhysical interaction with the image reveals it to be an illusion, because things can pass through it. A creature that uses its action to examine the image can determine that it is an illusion with a successful Intelligence (Investigation) check against your spell save DC. If a creature discerns the illusion for what it is, the creature can see through the image, and any noise it makes sounds hollow to the creature.","","",""],
["Regenerate",7,7,"1 minute","Touch","1 hour","VSM","A prayer wheel and holy water.",0,0,[0, 1, 2],"You touch a creature and stimulate its natural healing ability. The target regains 4d8 + 15 hit points. For the duration of the spell, the target regains 1 hit point at the start of each of its turns (10 hit points each minute).\n\nThe target's severed body members (fingers, legs, tails, and so on), if any, are restored after 2 minutes. If you have the severed part and hold it to the stump, the spell instantaneously causes the limb to knit to the stump.","","",""],
["Resurrection",7,6,"1 hour","Touch","Instantaneous","VSM","A diamond worth at least 1,000gp, which the spell consumes.",0,0,[0, 1],"You touch a dead creature that has been dead for no more than a century, that didn't die of old age, and that isn't undead. If its soul is free and willing, the target returns to life with all its hit points.\n\nThis spell neutralizes any poisons and cures normal diseases afflicting the creature when it died. It doesn't, however, remove magical diseases, curses, and the like; if such effects aren't removed prior to casting the spell, they afflict the target on its return to life.\n\nThis spell closes all mortal wounds and restores any missing body parts.\n\nComing back from the dead is an ordeal. The target takes a -4 penalty to all attack rolls, saving throws, and ability checks. Every time the target finishes a long rest, the penalty is reduced by 1 until it disappears.\n\nCasting this spell to restore life to a creature that has been dead for one year or longer taxes you greatly. Until you finish a long rest, you can't cast spells again, and you have disadvantage on all attack rolls, ability checks, and saving throws.","","",""],
["Reverse Gravity",7,7,"1 action","100 feet","Up to 1 minute","VSM","A lodestone and iron filings.",1,0,[2, 5, 7],"This spell reverses gravity in a 50-foot-radius, 100-foot high cylinder centered on a point within range. All creatures and objects that aren't somehow anchored to the ground in the area fall upward and reach the top of the area when you cast this spell. A creature can make a dexterity saving throw to grab onto a fixed object it can reach, thus avoiding the fall.\n\nIf some solid object (such as a ceiling) is encountered in this fall, falling objects and creatures strike it just as they would during a normal downward fall. If an object or creature reaches the top of the area without striking anything, it remains there, oscillating slightly, for the duration.\n\nAt the end of the duration, affected objects and creatures fall back down.","","","DEX"],
["Sequester",7,7,"1 action","Touch","Until dispelled","VSM","A powder composed of diamond, emerald, ruby, and sapphire dust worth at least 5,000 gp, which the spell consumes.",0,0,[7],"By means of this spell, a willing creature or an object can be hidden away, safe from detection for the duration. When you cast the spell and touch the target, it becomes invisible and can't be targeted by divination spells or perceived through scrying sensors created by divination spells.\n\nIf the target is a creature, it falls into a state of suspended animation. Time ceases to flow for it, and it doesn't grow older.\n\nYou can set a condition for the spell to end early. The condition can be anything you choose, but it must occur or be visible within 1 mile of the target. Examples include \"after 1,000 years\" or \"when the tarrasque awakens.\" This spell also ends if the target takes any damage.","","",""],
["Simulacrum",7,5,"12 hours","Touch","Until dispelled","VSM","Snow or ice in quantities sufficient to made a life-size copy of the duplicated creature; some hair, fingernail clippings, or other piece of that creature's body placed inside the snow or ice; and powdered ruby worth 1,500 gp, sprinkled over the duplicate and consumed by the spell.",0,0,[7],"You shape an illusory duplicate of one beast or humanoid that is within range for the entire casting time of the spell. The duplicate is a creature, partially real and formed from ice or snow, and it can take actions and otherwise be affected as a normal creature. It appears to be the same as the original, but it has half the creature's hit point maximum and is formed without any equipment. Otherwise, the illusion uses all the statistics of the creature it duplicates.\n\nThe simulacrum is friendly to you and creatures you designate. It obeys your spoken commands, moving and acting in accordance with your wishes and acting on your turn in combat. The simulacrum lacks the ability to learn or become more powerful, so it never increases its level or other abilities, nor can it regain expended spell slots.\n\nIf the simulacrum is damaged, you can repair it in an alchemical laboratory, using rare herbs and minerals worth 100 gp per hit point it regains. The simulacrum lasts until it drops to 0 hit points, at which point it reverts to snow and melts instantly.\n\nIf you cast this spell again, any currently active duplicates you created with this spell are instantly destroyed.","","",""],
["Symbol",7,0,"1 minute","Touch","Until dispelled","VSM","Mercury, phosphorus, and powdered diamond and opal with a total value of at least 1,000 gp, which the spell consumes.",0,0,[0, 1, 7],"When you cast this spell, you inscribe a harmful glyph either on a surface (such as a section of floor, a wall, or a table) or within an object that can be closed to conceal the glyph (such as a book, a scroll, or a treasure chest). If you choose a surface, the glyph can cover an area of the surface no larger than 10 feet in diameter. If you choose an object, that object must remain in its place; if the object is moved more than 10 feet from where you cast this spell, the glyph is broken, and the spell ends without being triggered.\n\nThe glyph is nearly invisible, requiring an Intelligence (Investigation) check against your spell save DC to find it.\n\nYou decide what triggers the glyph when you cast the spell. For glyphs inscribed on a surface, the most typical triggers include touching or stepping on the glyph, removing another object covering it, approaching within a certain distance of it, or manipulating the object that holds it. For glyphs inscribed within an object, the most common triggers are opening the object, approaching within a certain distance of it, or seeing or reading the glyph.\n\nYou can further refine the trigger so the spell is activated only under certain circumstances or according to a creature's physical characteristics (such as height or weight), or physical kind (for example, the ward could be set to affect hags or shapechangers). You can also specify creatures that don't trigger the glyph, such as those who say a certain password.\n\nWhen you inscribe the glyph, choose one of the options below for its effect. Once triggered, the glyph glows, filling a 60-foot-radius sphere with dim light for 10 minutes, after which time the spell ends. Each creature in the sphere when the glyph activates is targeted by its effect, as is a creature that enters the sphere for the first time on a turn or ends its turn there.\n\n***Death.*** Each target must make a constitution saving throw, taking 10d 10 necrotic damage on a failed save, or half as much damage on a successful save.\n\n***Discord.*** Each target must make a constitution saving throw. On a failed save, a target bickers and argues with other creatures for 1 minute. During this time, it is incapable of meaningful communication and has disadvantage on attack rolls and ability checks.\n\n***Fear.*** Each target must make a wisdom saving throw and becomes frightened for 1 minute on a failed save. While frightened, the target drops whatever it is holding and must move at least 30 feet away from the glyph on each of its turns, if able.\n\n***Hopelessness.*** Each target must make a charisma saving throw. On a failed save, the target is overwhelmed with despair for 1 minute. During this time, it can't attack or target any creature with harmful abilities, spells, or other magical effects.\n\n***Insanity.*** Each target must make an intelligence saving throw. On a failed save, the target is driven insane for 1 minute. An insane creature can't take actions, can't understand what other creatures say, can't read, and speaks only in gibberish. The GM controls its movement, which is erratic.\n\n***Pain.*** Each target must make a constitution saving throw and becomes incapacitated with excruciating pain for 1 minute on a failed save.\n\n***Sleep.*** Each target must make a wisdom saving throw and falls unconscious for 10 minutes on a failed save. A creature awakens if it takes damage or if someone uses an action to shake or slap it awake.\n\n***Stunning.*** Each target must make a wisdom saving throw and becomes stunned for 1 minute on a failed save.","","",""],
["Teleport",7,1,"1 action","10 feet","Instantaneous","V","",0,0,[0, 5, 7],"This spell instantly transports you and up to eight willing creatures of your choice that you can see within range, or a single object that you can see within range, to a destination you select. If you target an object, it must be able to fit entirely inside a 10-foot cube, and it can't be held or carried by an unwilling creature.\n\nThe destination you choose must be known to you, and it must be on the same plane of existence as you. Your familiarity with the destination determines whether you arrive there successfully. The GM rolls d100 and consults the table.\n\n| Familiarity | Mishap | Similar Area | Off Target | On Target |\n\n|---|---|---|---|---|\n\n| Permanent circle | -- | -- | -- | 01-100 |\n\n| Associated object | -- | -- | -- | 01-100 |\n\n| Very familiar | 01-05 | 06-13 | 14-24 | 25-100 |\n\n| Seen casually | 01-33 | 34-43 | 44-53 | 54-100 |\n\n| Viewed once | 01-43 | 44-53 | 54-73 | 74-100 |\n\n| Description | 01-43 | 44-53 | 54-73 | 74-100 |\n\n| False destination | 01-50 | 51-100 | -- | -- |\n\n***Familiarity.*** \"Permanent circle\" means a permanent teleportation circle whose sigil sequence you know.\n\n\"Associated object\" means that you possess an object taken from the desired destination within the last six months, such as a book from a wizard's library, bed linen from a royal suite, or a chunk of marble from a lich's secret tomb.\n\n\"Very familiar\" is a place you have been very often, a place you have carefully studied, or a place you can see when you cast the spell.\n\n\"Seen casually\" is someplace you have seen more than once but with which you aren't very familiar.\n\n\"Viewed once\" is a place you have seen once, possibly using magic.\n\n\"Description\" is a place whose location and appearance you know through someone else's description, perhaps from a map.\n\n\"False destination\" is a place that doesn't exist. Perhaps you tried to scry an enemy's sanctum but instead viewed an illusion, or you are attempting to teleport to a familiar location that no longer exists.\n\n***On Target.*** You and your group (or the target object) appear where you want to.\n\n***Off Target.*** You and your group (or the target object) appear a random distance away from the destination in a random direction. Distance off target is 1d10 x 1d10 percent of the distance that was to be traveled. For example, if you tried to travel 120 miles, landed off target, and rolled a 5 and 3 on the two d10s, then you would be off target by 15 percent, or 18 miles. The GM determines the direction off target randomly by rolling a d8 and designating 1 as north, 2 as northeast, 3 as east, and so on around the points of the compass. If you were teleporting to a coastal city and wound up 18 miles out at sea, you could be in trouble.\n\n***Similar Area.*** You and your group (or the target object) wind up in a different area that's visually or thematically similar to the target area. If you are heading for your home laboratory, for example, you might wind up in another wizard's laboratory or in an alchemical supply shop that has many of the same tools and implements as your laboratory. Generally, you appear in the closest similar place, but since the spell has no range limit, you could conceivably wind up anywhere on the plane.\n\n***Mishap.*** The spell's unpredictable magic results in a difficult journey. Each teleporting creature (or the target object) takes 3d10 force damage, and the GM rerolls on the table to see where you wind up (multiple mishaps can occur, dealing damage each time).","","",""],
["Animal Shapes",8,7,"1 action","30 feet","Up to 24 hours","VS","",1,0,[2],"Your magic turns others into beasts. Choose any number of willing creatures that you can see within range. You transform each target into the form of a Large or smaller beast with a challenge rating of 4 or lower. On subsequent turns, you can use your action to transform affected creatures into new forms.\n\nThe transformation lasts for the duration for each target, or until the target drops to 0 hit points or dies. You can choose a different form for each target. A target's game statistics are replaced by the statistics of the chosen beast, though the target retains its alignment and Intelligence, Wisdom, and Charisma scores. The target assumes the hit points of its new form, and when it reverts to its normal form, it returns to the number of hit points it had before it transformed. If it reverts as a result of dropping to 0 hit points, any excess damage carries over to its normal form. As long as the excess damage doesn't reduce the creature's normal form to 0 hit points, it isn't knocked unconscious. The creature is limited in the actions it can perform by the nature of its new form, and it can't speak or cast spells.\n\nThe target's gear melds into the new form. The target can't activate, wield, or otherwise benefit from any of its equipment.","","",""],
["Antimagic Field",8,0,"1 action","Self","Up to 1 hour","VSM","A pinch of powdered iron or iron filings.",1,0,[1, 7],"A 10-foot-radius invisible sphere of antimagic surrounds you. This area is divorced from the magical energy that suffuses the multiverse. Within the sphere, spells can't be cast, summoned creatures disappear, and even magic items become mundane. Until the spell ends, the sphere moves with you, centered on you.\n\nSpells and other magical effects, except those created by an artifact or a deity, are suppressed in the sphere and can't protrude into it. A slot expended to cast a suppressed spell is consumed. While an effect is suppressed, it doesn't function, but the time it spends suppressed counts against its duration.\n\n***Targeted Effects.*** Spells and other magical effects, such as magic missile and charm person, that target a creature or an object in the sphere have no effect on that target.\n\n***Areas of Magic.*** The area of another spell or magical effect, such as fireball, can't extend into the sphere. If the sphere overlaps an area of magic, the part of the area that is covered by the sphere is suppressed. For example, the flames created by a wall of fire are suppressed within the sphere, creating a gap in the wall if the overlap is large enough.\n\n***Spells.*** Any active spell or other magical effect on a creature or an object in the sphere is suppressed while the creature or object is in it.\n\n***Magic Items.*** The properties and powers of magic items are suppressed in the sphere. For example, a +1 longsword in the sphere functions as a nonmagical longsword.\n\nA magic weapon's properties and powers are suppressed if it is used against a target in the sphere or wielded by an attacker in the sphere. If a magic weapon or a piece of magic ammunition fully leaves the sphere (for example, if you fire a magic arrow or throw a magic spear at a target outside the sphere), the magic of the item ceases to be suppressed as soon as it exits.\n\n***Magical Travel.*** Teleportation and planar travel fail to work in the sphere, whether the sphere is the destination or the departure point for such magical travel. A portal to another location, world, or plane of existence, as well as an opening to an extradimensional space such as that created by the rope trick spell, temporarily closes while in the sphere.\n\n***Creatures and Objects.*** A creature or object summoned or created by magic temporarily winks out of existence in the sphere. Such a creature instantly reappears once the space the creature occupied is no longer within the sphere.\n\n***Dispel Magic.*** Spells and magical effects such as dispel magic have no effect on the sphere. Likewise, the spheres created by different antimagic field spells don't nullify each other.","","",""],
["Antipathy/Sympathy",8,3,"1 hour","60 feet","10 days","VSM","Either a lump of alum soaked in vinegar for the antipathy effect or a drop of honey for the sympathy effect.",0,0,[2, 7],"This spell attracts or repels creatures of your choice. You target something within range, either a Huge or smaller object or creature or an area that is no larger than a 200-foot cube. Then specify a kind of intelligent creature, such as red dragons, goblins, or vampires. You invest the target with an aura that either attracts or repels the specified creatures for the duration. Choose antipathy or sympathy as the aura's effect.\n\n***Antipathy.*** The enchantment causes creatures of the kind you designated to feel an intense urge to leave the area and avoid the target. When such a creature can see the target or comes within 60 feet of it, the creature must succeed on a wisdom saving throw or become frightened. The creature remains frightened while it can see the target or is within 60 feet of it. While frightened by the target, the creature must use its movement to move to the nearest safe spot from which it can't see the target. If the creature moves more than 60 feet from the target and can't see it, the creature is no longer frightened, but the creature becomes frightened again if it regains sight of the target or moves within 60 feet of it.\n\n***Sympathy.*** The enchantment causes the specified creatures to feel an intense urge to approach the target while within 60 feet of it or able to see it. When such a creature can see the target or comes within 60 feet of it, the creature must succeed on a wisdom saving throw or use its movement on each of its turns to enter the area or move within reach of the target. When the creature has done so, it can't willingly move away from the target.\n\nIf the target damages or otherwise harms an affected creature, the affected creature can make a wisdom saving throw to end the effect, as described below.\n\n***Ending the Effect.*** If an affected creature ends its turn while not within 60 feet of the target or able to see it, the creature makes a wisdom saving throw. On a successful save, the creature is no longer affected by the target and recognizes the feeling of repugnance or attraction as magical. In addition, a creature affected by the spell is allowed another wisdom saving throw every 24 hours while the spell persists.\n\nA creature that successfully saves against this effect is immune to it for 1 minute, after which time it can be affected again.","","",""],
["Clone",8,6,"1 hour","Touch","Instantaneous","VSM","A diamond worth at least 1,000 gp and at least 1 cubic inch of flesh of the creature that is to be cloned, which the spell consumes, and a vessel worth at least 2,000 gp that has a sealable lid and is large enough to hold a Medium creature, such as a huge urn, coffin, mud-filled cyst in the ground, or crystal container filled with salt water.",0,0,[7],"This spell grows an inert duplicate of a living creature as a safeguard against death. This clone forms inside a sealed vessel and grows to full size and maturity after 120 days; you can also choose to have the clone be a younger version of the same creature. It remains inert and endures indefinitely, as long as its vessel remains undisturbed.\n\nAt any time after the clone matures, if the original creature dies, its soul transfers to the clone, provided that the soul is free and willing to return. The clone is physically identical to the original and has the same personality, memories, and abilities, but none of the original's equipment. The original creature's physical remains, if they still exist, become inert and can't thereafter be restored to life, since the creature's soul is elsewhere.","","",""],
["Control Weather",8,7,"10 minutes","Self","Up to 8 hours","VSM","Burning incense and bits of earth and wood mixed in water.",1,0,[1, 2, 7],"You take control of the weather within 5 miles of you for the duration. You must be outdoors to cast this spell. Moving to a place where you don't have a clear path to the sky ends the spell early.\n\nWhen you cast the spell, you change the current weather conditions, which are determined by the GM based on the climate and season. You can change precipitation, temperature, and wind. It takes 1d4 x 10 minutes for the new conditions to take effect. Once they do so, you can change the conditions again. When the spell ends, the weather gradually returns to normal.\n\nWhen you change the weather conditions, find a current condition on the following tables and change its stage by one, up or down. When changing the wind, you can change its direction.\n\n##### Precipitation\n\n| Stage | Condition |\n\n|---|---|\n\n| 1 | Clear |\n\n| 2 | Light clouds |\n\n| 3 | Overcast or ground fog |\n\n| 4 | Rain, hail, or snow |\n\n| 5 | Torrential rain, driving hail, or blizzard |\n\n##### Temperature\n\n| Stage | Condition |\n\n|---|---|\n\n| 1 | Unbearable heat |\n\n| 2 | Hot |\n\n| 3 | Warm |\n\n| 4 | Cool |\n\n| 5 | Cold |\n\n| 6 | Arctic cold |\n\n##### Wind\n\n| Stage | Condition |\n\n|---|---|\n\n| 1 | Calm |\n\n| 2 | Moderate wind |\n\n| 3 | Strong wind |\n\n| 4 | Gale |\n\n| 5 | Storm |","","",""],
["Demiplane",8,1,"1 action","60 feet","1 hour","S","",0,0,[6, 7],"You create a shadowy door on a flat solid surface that you can see within range. The door is large enough to allow Medium creatures to pass through unhindered. When opened, the door leads to a demiplane that appears to be an empty room 30 feet in each dimension, made of wood or stone. When the spell ends, the door disappears, and any creatures or objects inside the demiplane remain trapped there, as the door also disappears from the other side.\n\nEach time you cast this spell, you can create a new demiplane, or have the shadowy door connect to a demiplane you created with a previous casting of this spell. Additionally, if you know the nature and contents of a demiplane created by a casting of this spell by another creature, you can have the shadowy door connect to its demiplane instead.","","",""],
["Dominate Monster",8,3,"1 action","60 feet","Up to 1 hour","VS","",1,0,[0, 5, 6, 7],"You attempt to beguile a creature that you can see within range. It must succeed on a wisdom saving throw or be charmed by you for the duration. If you or creatures that are friendly to you are fighting it, it has advantage on the saving throw.\n\nWhile the creature is charmed, you have a telepathic link with it as long as the two of you are on the same plane of existence. You can use this telepathic link to issue commands to the creature while you are conscious (no action required), which it does its best to obey. You can specify a simple and general course of action, such as \"Attack that creature,\" \"Run over there,\" or \"Fetch that object.\" If the creature completes the order and doesn't receive further direction from you, it defends and preserves itself to the best of its ability.\n\nYou can use your action to take total and precise control of the target. Until the end of your next turn, the creature takes only the actions you choose, and doesn't do anything that you don't allow it to do. During this time, you can also cause the creature to use a reaction, but this requires you to use your own reaction as well.\n\nEach time the target takes damage, it makes a new wisdom saving throw against the spell. If the saving throw succeeds, the spell ends.","When you cast this spell with a 9th-level spell slot, the duration is concentration, up to 8 hours.","","WIS"],
["Earthquake",8,4,"1 action","500 feet","Up to 1 minute","VSM","A pinch of dirt, a piece of rock, and a lump of clay.",1,0,[1, 2, 5],"You create a seismic disturbance at a point on the ground that you can see within range. For the duration, an intense tremor rips through the ground in a 100-foot-radius circle centered on that point and shakes creatures and structures in contact with the ground in that area.\n\nThe ground in the area becomes difficult terrain. Each creature on the ground that is concentrating must make a constitution saving throw. On a failed save, the creature's concentration is broken.\n\nWhen you cast this spell and at the end of each turn you spend concentrating on it, each creature on the ground in the area must make a dexterity saving throw. On a failed save, the creature is knocked prone.\n\nThis spell can have additional effects depending on the terrain in the area, as determined by the GM.\n\nFissures. Fissures open throughout the spell's area at the start of your next turn after you cast the spell. A total of 1d6 such fissures open in locations chosen by the GM. Each is 1d10 x 10 feet deep, 10 feet wide, and extends from one edge of the spell's area to the opposite side. A creature standing on a spot where a fissure opens must succeed on a dexterity saving throw or fall in. A creature that successfully saves moves with the fissure's edge as it opens.\n\nA fissure that opens beneath a structure causes it to automatically collapse (see below).\n\nStructures. The tremor deals 50 bludgeoning damage to any structure in contact with the ground in the area when you cast the spell and at the start of each of your turns until the spell ends. If a structure drops to 0 hit points, it collapses and potentially damages nearby creatures. A creature within half the distance of a structure's height must make a dexterity saving throw. On a failed save, the creature takes 5d6 bludgeoning damage, is knocked prone, and is buried in the rubble, requiring a DC 20 Strength (Athletics) check as an action to escape. The GM can adjust the DC higher or lower, depending on the nature of the rubble. On a successful save, the creature takes half as much damage and doesn't fall prone or become buried.","","",""],
["Feeblemind",8,3,"1 action","150 feet","Instantaneous","VSM","A handful of clay, crystal, glass, or mineral spheres.",0,0,[0, 2, 6, 7],"You blast the mind of a creature that you can see within range, attempting to shatter its intellect and personality. The target takes 4d6 psychic damage and must make an intelligence saving throw.\n\nOn a failed save, the creature's Intelligence and Charisma scores become 1. The creature can't cast spells, activate magic items, understand language, or communicate in any intelligible way. The creature can, however, identify its friends, follow them, and even protect them.\n\nAt the end of every 30 days, the creature can repeat its saving throw against this spell. If it succeeds on its saving throw, the spell ends.\n\nThe spell can also be ended by greater restoration, heal, or wish.","","Psychic","INT"],
["Glibness",8,7,"1 action","Self","1 hour","V","",0,0,[0, 6],"Until the spell ends, when you make a Charisma check, you can replace the number you roll with a 15. Additionally, no matter what you say, magic that would determine if you are telling the truth indicates that you are being truthful.","","",""],
["Holy Aura",8,0,"1 action","Self","Up to 1 minute","VSM","A tiny reliquary worth at least 1,000gp containing a sacred relic, such as a scrap of cloth from a saint's robe or a piece of parchment from a religious text.",1,0,[1],"Divine light washes out from you and coalesces in a soft radiance in a 30-foot radius around you. Creatures of your choice in that radius when you cast this spell shed dim light in a 5-foot radius and have advantage on all saving throws, and other creatures have disadvantage on attack rolls against them until the spell ends. In addition, when a fiend or an undead hits an affected creature with a melee attack, the aura flashes with brilliant light. The attacker must succeed on a constitution saving throw or be blinded until the spell ends.","","",""],
["Incendiary Cloud",8,1,"1 action","150 feet","Up to 1 minute","VS","",1,0,[5, 7],"A swirling cloud of smoke shot through with white-hot embers appears in a 20-foot-radius sphere centered on a point within range. The cloud spreads around corners and is heavily obscured. It lasts for the duration or until a wind of moderate or greater speed (at least 10 miles per hour) disperses it.\n\nWhen the cloud appears, each creature in it must make a dexterity saving throw. A creature takes 10d8 fire damage on a failed save, or half as much damage on a successful one. A creature must also make this saving throw when it enters the spell's area for the first time on a turn or ends its turn there.\n\nThe cloud moves 10 feet directly away from you in a direction that you choose at the start of each of your turns.","","Fire","DEX"],
["Maze",8,1,"1 action","60 feet","Up to 10 minutes","VS","",1,0,[7],"You banish a creature that you can see within range into a labyrinthine demiplane. The target remains there for the duration or until it escapes the maze.\n\nThe target can use its action to attempt to escape. When it does so, it makes a DC 20 Intelligence check. If it succeeds, it escapes, and the spell ends (a minotaur or goristro demon automatically succeeds).\n\nWhen the spell ends, the target reappears in the space it left or, if that space is occupied, in the nearest unoccupied space.","","",""],
["Mind Blank",8,0,"1 action","Touch","24 hours","VS","",0,0,[0, 7],"Until the spell ends, one willing creature you touch is immune to psychic damage, any effect that would sense its emotions or read its thoughts, divination spells, and the charmed condition. The spell even foils wish spells and spells or effects of similar power used to affect the target's mind or to gain information about the target.","","",""],
["Power Word Stun",8,3,"1 action","60 feet","Instantaneous","V","",0,0,[0, 5, 6, 7],"You speak a word of power that can overwhelm the mind of one creature you can see within range, leaving it dumbfounded. If the target has 150 hit points or fewer, it is stunned. Otherwise, the spell has no effect.\n\nThe stunned target must make a constitution saving throw at the end of each of its turns. On a successful save, this stunning effect ends.","","",""],
["Sunburst",8,4,"1 action","150 feet","Instantaneous","VSM","Fire and a piece of sunstone.",0,0,[2, 5, 7],"Brilliant sunlight flashes in a 60-foot radius centered on a point you choose within range. Each creature in that light must make a constitution saving throw. On a failed save, a creature takes 12d6 radiant damage and is blinded for 1 minute. On a successful save, it takes half as much damage and isn't blinded by this spell. Undead and oozes have disadvantage on this saving throw.\n\nA creature blinded by this spell makes another constitution saving throw at the end of each of its turns. On a successful save, it is no longer blinded.\n\nThis spell dispels any darkness in its area that was created by a spell.","","Radiant","CON"],
["Astral Projection",9,6,"1 hour","10 feet","Special","VSM","For each creature you affect with this spell, you must provide one jacinth worth at least 1,000gp and one ornately carved bar of silver worth at least 100gp, all of which the spell consumes.",0,0,[1, 6, 7],"You and up to eight willing creatures within range project your astral bodies into the Astral Plane (the spell fails and the casting is wasted if you are already on that plane). The material body you leave behind is unconscious and in a state of suspended animation; it doesn't need food or air and doesn't age.\n\nYour astral body resembles your mortal form in almost every way, replicating your game statistics and possessions. The principal difference is the addition of a silvery cord that extends from between your shoulder blades and trails behind you, fading to invisibility after 1 foot. This cord is your tether to your material body. As long as the tether remains intact, you can find your way home. If the cord is cut--something that can happen only when an effect specifically states that it does--your soul and body are separated, killing you instantly.\n\nYour astral form can freely travel through the Astral Plane and can pass through portals there leading to any other plane. If you enter a new plane or return to the plane you were on when casting this spell, your body and possessions are transported along the silver cord, allowing you to re-enter your body as you enter the new plane. Your astral form is a separate incarnation. Any damage or other effects that apply to it have no effect on your physical body, nor do they persist when you return to it.\n\nThe spell ends for you and your companions when you use your action to dismiss it. When the spell ends, the affected creature returns to its physical body, and it awakens.\n\nThe spell might also end early for you or one of your companions. A successful dispel magic spell used against an astral or physical body ends the spell for that creature. If a creature's original body or its astral form drops to 0 hit points, the spell ends for that creature. If the spell ends and the silver cord is intact, the cord pulls the creature's astral form back to its body, ending its state of suspended animation.\n\nIf you are returned to your body prematurely, your companions remain in their astral forms and must find their own way back to their bodies, usually by dropping to 0 hit points.","","",""],
["Foresight",9,2,"1 minute","Touch","8 hours","VSM","A hummingbird feather.",0,0,[0, 2, 6, 7],"You touch a willing creature and bestow a limited ability to see into the immediate future. For the duration, the target can't be surprised and has advantage on attack rolls, ability checks, and saving throws. Additionally, other creatures have disadvantage on attack rolls against the target for the duration.\n\nThis spell immediately ends if you cast it again before its duration ends.","","",""],
["Gate",9,1,"1 action","60 feet","Up to 1 minute","VSM","A diamond worth at least 5,000gp.",1,0,[1, 5, 7],"You conjure a portal linking an unoccupied space you can see within range to a precise location on a different plane of existence. The portal is a circular opening, which you can make 5 to 20 feet in diameter. You can orient the portal in any direction you choose. The portal lasts for the duration.\n\nThe portal has a front and a back on each plane where it appears. Travel through the portal is possible only by moving through its front. Anything that does so is instantly transported to the other plane, appearing in the unoccupied space nearest to the portal.\n\nDeities and other planar rulers can prevent portals created by this spell from opening in their presence or anywhere within their domains.\n\nWhen you cast this spell, you can speak the name of a specific creature (a pseudonym, title, or nickname doesn't work). If that creature is on a plane other than the one you are on, the portal opens in the named creature's immediate vicinity and draws the creature through it to the nearest unoccupied space on your side of the portal. You gain no special power over the creature, and it is free to act as the GM deems appropriate. It might leave, attack you, or help you.","","",""],
["Imprisonment",9,0,"1 minute","30 feet","Until dispelled","VSM","A vellum depiction or a carved statuette in the likeness of the target, and a special component that varies according to the version of the spell you choose, worth at least 500gp per Hit Die of the target.",0,0,[6, 7],"You create a magical restraint to hold a creature that you can see within range. The target must succeed on a wisdom saving throw or be bound by the spell; if it succeeds, it is immune to this spell if you cast it again. While affected by this spell, the creature doesn't need to breathe, eat, or drink, and it doesn't age. Divination spells can't locate or perceive the target.\n\nWhen you cast the spell, you choose one of the following forms of imprisonment.\n\n***Burial.*** The target is entombed far beneath the earth in a sphere of magical force that is just large enough to contain the target. Nothing can pass through the sphere, nor can any creature teleport or use planar travel to get into or out of it.\n\nThe special component for this version of the spell is a small mithral orb.\n\n***Chaining.*** Heavy chains, firmly rooted in the ground, hold the target in place. The target is restrained until the spell ends, and it can't move or be moved by any means until then.\n\nThe special component for this version of the spell is a fine chain of precious metal.\n\n***Hedged Prison.*** The spell transports the target into a tiny demiplane that is warded against teleportation and planar travel. The demiplane can be a labyrinth, a cage, a tower, or any similar confined structure or area of your choice.\n\nThe special component for this version of the spell is a miniature representation of the prison made from jade.\n\n***Minimus Containment.*** The target shrinks to a height of 1 inch and is imprisoned inside a gemstone or similar object. Light can pass through the gemstone normally (allowing the target to see out and other creatures to see in), but nothing else can pass through, even by means of teleportation or planar travel. The gemstone can't be cut or broken while the spell remains in effect.\n\nThe special component for this version of the spell is a large, transparent gemstone, such as a corundum, diamond, or ruby.\n\n***Slumber.*** The target falls asleep and can't be awoken.\n\nThe special component for this version of the spell consists of rare soporific herbs.\n\n***Ending the Spell.*** During the casting of the spell, in any of its versions, you can specify a condition that will cause the spell to end and release the target. The condition can be as specific or as elaborate as you choose, but the GM must agree that the condition is reasonable and has a likelihood of coming to pass. The conditions can be based on a creature's name, identity, or deity but otherwise must be based on observable actions or qualities and not based on intangibles such as level, class, or hit points.\n\nA dispel magic spell can end the spell only if it is cast as a 9th-level spell, targeting either the prison or the special component used to create it.\n\nYou can use a particular special component to create only one prison at a time. If you cast the spell again using the same component, the target of the first casting is immediately freed from its binding.","","","WIS"],
["Mass Heal",9,1,"1 action","60 feet","Instantaneous","VS","",0,0,[1],"A flood of healing energy flows from you into injured creatures around you. You restore up to 700 hit points, divided as you choose among any number of creatures that you can see within range. Creatures healed by this spell are also cured of all diseases and any effect making them blinded or deafened. This spell has no effect on undead or constructs.","","",""],
["Meteor Swarm",9,4,"1 action","1 mile","Instantaneous","VS","",0,0,[5, 7],"Blazing orbs of fire plummet to the ground at four different points you can see within range. Each creature in a 40-foot-radius sphere centered on each point you choose must make a dexterity saving throw. The sphere spreads around corners. A creature takes 20d6 fire damage and 20d6 bludgeoning damage on a failed save, or half as much damage on a successful one. A creature in the area of more than one fiery burst is affected only once.\n\nThe spell damages objects in the area and ignites flammable objects that aren't being worn or carried.","","Fire","DEX"],
["Power Word Kill",9,3,"1 action","60 feet","Instantaneous","V","",0,0,[0, 5, 6, 7],"You utter a word of power that can compel one creature you can see within range to die instantly. If the creature you choose has 100 hit points or fewer, it dies. Otherwise, the spell has no effect.","","",""],
["Prismatic Wall",9,0,"1 action","60 feet","10 minutes","VS","",0,0,[7],"A shimmering, multicolored plane of light forms a vertical opaque wall--up to 90 feet long, 30 feet high, and 1 inch thick--centered on a point you can see within range. Alternatively, you can shape the wall into a sphere up to 30 feet in diameter centered on a point you choose within range. The wall remains in place for the duration. If you position the wall so that it passes through a space occupied by a creature, the spell fails, and your action and the spell slot are wasted.\n\nThe wall sheds bright light out to a range of 100 feet and dim light for an additional 100 feet. You and creatures you designate at the time you cast the spell can pass through and remain near the wall without harm. If another creature that can see the wall moves to within 20 feet of it or starts its turn there, the creature must succeed on a constitution saving throw or become blinded for 1 minute.\n\nThe wall consists of seven layers, each with a different color. When a creature attempts to reach into or pass through the wall, it does so one layer at a time through all the wall's layers. As it passes or reaches through each layer, the creature must make a dexterity saving throw or be affected by that layer's properties as described below.\n\nThe wall can be destroyed, also one layer at a time, in order from red to violet, by means specific to each layer. Once a layer is destroyed, it remains so for the duration of the spell. A rod of cancellation destroys a prismatic wall, but an antimagic field has no effect on it.\n\n***1. Red.*** The creature takes 10d6 fire damage on a failed save, or half as much damage on a successful one. While this layer is in place, nonmagical ranged attacks can't pass through the wall. The layer can be destroyed by dealing at least 25 cold damage to it.\n\n***2. Orange.*** The creature takes 10d6 acid damage on a failed save, or half as much damage on a successful one. While this layer is in place, magical ranged attacks can't pass through the wall. The layer is destroyed by a strong wind.\n\n***3. Yellow.*** The creature takes 10d6 lightning damage on a failed save, or half as much damage on a successful one. This layer can be destroyed by dealing at least 60 force damage to it.\n\n***4. Green.*** The creature takes 10d6 poison damage on a failed save, or half as much damage on a successful one. A passwall spell, or another spell of equal or greater level that can open a portal on a solid surface, destroys this layer.\n\n***5. Blue.*** The creature takes 10d6 cold damage on a failed save, or half as much damage on a successful one. This layer can be destroyed by dealing at least 25 fire damage to it.\n\n***6. Indigo.*** On a failed save, the creature is restrained. It must then make a constitution saving throw at the end of each of its turns. If it successfully saves three times, the spell ends. If it fails its save three times, it permanently turns to stone and is subjected to the petrified condition. The successes and failures don't need to be consecutive; keep track of both until the creature collects three of a kind.\n\nWhile this layer is in place, spells can't be cast through the wall. The layer is destroyed by bright light shed by a daylight spell or a similar spell of equal or higher level.\n\n***7. Violet.*** On a failed save, the creature is blinded. It must then make a wisdom saving throw at the start of your next turn. A successful save ends the blindness. If it fails that save, the creature is transported to another plane of the GM's choosing and is no longer blinded. (Typically, a creature that is on a plane that isn't its home plane is banished home, while other creatures are usually cast into the Astral or Ethereal planes.) This layer is destroyed by a dispel magic spell or a similar spell of equal or higher level that can end spells and magical effects.","","",""],
["Shapechange",9,7,"1 action","Self","Up to 1 hour","VSM","A jade circlet worth at least 1,500 gp, which you must place on your head before you cast the spell.",1,0,[2, 7],"You assume the form of a different creature for the duration. The new form can be of any creature with a challenge rating equal to your level or lower. The creature can't be a construct or an undead, and you must have seen the sort of creature at least once. You transform into an average example of that creature, one without any class levels or the Spellcasting trait.\n\nYour game statistics are replaced by the statistics of the chosen creature, though you retain your alignment and Intelligence, Wisdom, and Charisma scores. You also retain all of your skill and saving throw proficiencies, in addition to gaining those of the creature. If the creature has the same proficiency as you and the bonus listed in its statistics is higher than yours, use the creature's bonus in place of yours. You can't use any legendary actions or lair actions of the new form.\n\nYou assume the hit points and Hit Dice of the new form. When you revert to your normal form, you return to the number of hit points you had before you transformed. If you revert as a result of dropping to 0 hit points, any excess damage carries over to your normal form. As long as the excess damage doesn't reduce your normal form to 0 hit points, you aren't knocked unconscious.\n\nYou retain the benefit of any features from your class, race, or other source and can use them, provided that your new form is physically capable of doing so. You can't use any special senses you have (for example, darkvision) unless your new form also has that sense. You can only speak if the creature can normally speak.\n\nWhen you transform, you choose whether your equipment falls to the ground, merges into the new form, or is worn by it. Worn equipment functions as normal. The GM determines whether it is practical for the new form to wear a piece of equipment, based on the creature's shape and size. Your equipment doesn't change shape or size to match the new form, and any equipment that the new form can't wear must either fall to the ground or merge into your new form. Equipment that merges has no effect in that state.\n\nDuring this spell's duration, you can use your action to assume a different form following the same restrictions and rules for the original form, with one exception: if your new form has more hit points than your current one, your hit points remain at their current value.","","",""],
["Storm of Vengeance",9,1,"1 action","Sight","Up to 1 minute","VS","",1,0,[2],"A churning storm cloud forms, centered on a point you can see and spreading to a radius of 360 feet. Lightning flashes in the area, thunder booms, and strong winds roar. Each creature under the cloud (no more than 5,000 feet beneath the cloud) when it appears must make a constitution saving throw. On a failed save, a creature takes 2d6 thunder damage and becomes deafened for 5 minutes.\n\nEach round you maintain concentration on this spell, the storm produces additional effects on your turn.\n\n***Round 2.*** Acidic rain falls from the cloud. Each creature and object under the cloud takes 1d6 acid damage.\n\n***Round 3.*** You call six bolts of lightning from the cloud to strike six creatures or objects of your choice beneath the cloud. A given creature or object can't be struck by more than one bolt. A struck creature must make a dexterity saving throw. The creature takes 10d6 lightning damage on a failed save, or half as much damage on a successful one.\n\n***Round 4.*** Hailstones rain down from the cloud. Each creature under the cloud takes 2d6 bludgeoning damage.\n\n***Round 5-10.*** Gusts and freezing rain assail the area under the cloud. The area becomes difficult terrain and is heavily obscured. Each creature there takes 1d6 cold damage. Ranged weapon attacks in the area are impossible. The wind and rain count as a severe distraction for the purposes of maintaining concentration on spells. Finally, gusts of strong wind (ranging from 20 to 50 miles per hour) automatically disperse fog, mists, and similar phenomena in the area, whether mundane or magical.","","Thunder","CON"],
["Time Stop",9,7,"1 action","Self","Instantaneous","V","",0,0,[5, 7],"You briefly stop the flow of time for everyone but yourself. No time passes for other creatures, while you take 1d4 + 1 turns in a row, during which you can use actions and move as normal.\n\nThis spell ends if one of the actions you use during this period, or any effects that you create during this period, affects a creature other than you or an object being worn or carried by someone other than you. In addition, the spell ends if you move to a place more than 1,000 feet from the location where you cast it.","","",""],
["True Polymorph",9,7,"1 action","30 feet","Up to 1 hour","VSM","A drop of mercury, a dollop of gum arabic, and a wisp of smoke.",1,0,[0, 6, 7],"Choose one creature or nonmagical object that you can see within range. You transform the creature into a different creature, the creature into an object, or the object into a creature (the object must be neither worn nor carried by another creature). The transformation lasts for the duration, or until the target drops to 0 hit points or dies. If you concentrate on this spell for the full duration, the transformation becomes permanent.\n\nShapechangers aren't affected by this spell. An unwilling creature can make a wisdom saving throw, and if it succeeds, it isn't affected by this spell.\n\n***Creature into Creature.*** If you turn a creature into another kind of creature, the new form can be any kind you choose whose challenge rating is equal to or less than the target's (or its level, if the target doesn't have a challenge rating). The target's game statistics, including mental ability scores, are replaced by the statistics of the new form. It retains its alignment and personality.\n\nThe target assumes the hit points of its new form, and when it reverts to its normal form, the creature returns to the number of hit points it had before it transformed. If it reverts as a result of dropping to 0 hit points, any excess damage carries over to its normal form. As long as the excess damage doesn't reduce the creature's normal form to 0 hit points, it isn't knocked unconscious.\n\nThe creature is limited in the actions it can perform by the nature of its new form, and it can't speak, cast spells, or take any other action that requires hands or speech unless its new form is capable of such actions.\n\nThe target's gear melds into the new form. The creature can't activate, use, wield, or otherwise benefit from any of its equipment.\n\n***Object into Creature.*** You can turn an object into any kind of creature, as long as the creature's size is no larger than the object's size and the creature's challenge rating is 9 or lower. The creature is friendly to you and your companions. It acts on each of your turns. You decide what action it takes and how it moves. The GM has the creature's statistics and resolves all of its actions and movement.\n\nIf the spell becomes permanent, you no longer control the creature. It might remain friendly to you, depending on how you have treated it.\n\n***Creature into Object.*** If you turn a creature into an object, it transforms along with whatever it is wearing and carrying into that form. The creature's statistics become those of the object, and the creature has no memory of time spent in this form, after the spell ends and it returns to its normal form.","","",""],
["True Resurrection",9,6,"1 hour","Touch","Instantaneous","VSM","A sprinkle of holy water and diamonds worth at least 25,000gp, which the spell consumes.",0,0,[1, 2],"You touch a creature that has been dead for no longer than 200 years and that died for any reason except old age. If the creature's soul is free and willing, the creature is restored to life with all its hit points.\n\nThis spell closes all wounds, neutralizes any poison, cures all diseases, and lifts any curses affecting the creature when it died. The spell replaces damaged or missing organs and limbs.\n\nThe spell can even provide a new body if the original no longer exists, in which case you must speak the creature's name. The creature then appears in an unoccupied space you choose within 10 feet of you.","","",""],
["Weird",9,5,"1 action","120 feet","Up to 1 minute","VS","",1,0,[7],"Drawing on the deepest fears of a group of creatures, you create illusory creatures in their minds, visible only to them. Each creature in a 30-foot-radius sphere centered on a point of your choice within range must make a wisdom saving throw. On a failed save, a creature becomes frightened for the duration. The illusion calls on the creature's deepest fears, manifesting its worst nightmares as an implacable threat. At the start of each of the frightened creature's turns, it must succeed on a wisdom saving throw or take 4d10 psychic damage. On a successful save, the spell ends for that creature.","","","WIS"],
/* ---------- SRD 5.2.1 additions (CC-BY-4.0) ---------- */
["Aura of Life",4,0,"1 action","Self (30-ft radius)","Up to 10 minutes","VS","",1,0,[1],"Life-preserving energy radiates from you in a 30-foot radius aura. Until the spell ends, the aura moves with you, centered on you. Each nonhostile creature in the aura (including you) has resistance to necrotic damage, and its hit point maximum can't be reduced. In addition, a nonhostile, living creature in the aura regains 1 hit point when it starts its turn there with 0 hit points.","","",""],
["Charm Monster",4,3,"1 action","30 feet","1 hour","VS","",0,0,[0, 2, 5, 6, 7],"You attempt to charm a creature you can see within range. It must make a Wisdom saving throw, and it does so with advantage if you or your companions are fighting it. If it fails the saving throw, it is charmed by you until the spell ends or until you or your companions do anything harmful to it. The charmed creature regards you as a friendly acquaintance. When the spell ends, the creature knows it was charmed by you.","When you cast this spell using a spell slot of 5th level or higher, you can target one additional creature for each slot level above 4th. The creatures must be within 30 feet of each other when you target them.","","WIS"],
["Chromatic Orb",1,4,"1 action","90 feet","Instantaneous","VSM","A diamond worth at least 50gp.",0,0,[5, 7],"You hurl a 4-inch-diameter sphere of energy at a creature that you can see within range. You choose acid, cold, fire, lightning, poison, or thunder for the type of sphere you create, and then make a ranged spell attack against the target. If the attack hits, the creature takes 3d8 damage of the type you chose.","When you cast this spell using a spell slot of 2nd level or higher, the damage increases by 1d8 for each slot level above 1st.","",""],
["Dissonant Whispers",1,3,"1 action","60 feet","Instantaneous","V","",0,0,[0],"You whisper a discordant melody that only one creature of your choice within range can hear, wracking it with terrible pain. The target must make a Wisdom saving throw. On a failed save, it takes 3d6 psychic damage and must immediately use its reaction, if available, to move as far as its speed allows away from you. The creature doesn't move into obviously dangerous ground, such as a fire or a pit. On a successful save, the target takes half as much damage and doesn't have to move away. A deafened creature automatically succeeds on the saving throw.","When you cast this spell using a spell slot of 2nd level or higher, the damage increases by 1d6 for each slot level above 1st.","Psychic","WIS"],
["Divine Smite",1,4,"1 bonus action","Self","Instantaneous","V","",0,0,[3],"The next time you hit a creature with a melee weapon attack before the end of the current turn, your weapon flares with divine power. The attack deals extra Radiant damage equal to 2d8, or 3d8 if the target is an Undead or a Fiend.","When you cast this spell using a spell slot of 2nd level or higher, the extra damage increases by 1d8 for each slot level above 1st.","Radiant",""],
["Dragon's Breath",2,7,"1 bonus action","Touch","Up to 1 minute","VSM","A hot pepper.",1,0,[5, 7],"You touch one willing creature and imbue it with the power to spew magical energy from its mouth, provided it has one. Choose acid, cold, fire, lightning, or poison. Until the spell ends, the creature can use an action to exhale energy of the chosen type in a 15-foot cone. Each creature in that area must make a Dexterity saving throw, taking 3d6 damage of the chosen type on a failed save, or half as much damage on a successful one.","When you cast this spell using a spell slot of 3rd level or higher, the damage increases by 1d6 for each slot level above 2nd.","","DEX"],
["Elementalism",0,7,"1 action","30 feet","Instantaneous","VS","",0,0,[2, 5, 7],"You exert control over the elements, creating one of the following effects within range:\n\n***Beckon Air.*** You create a breeze strong enough to cause a lit torch to flicker or extinguish a candle, or you cause loose paper to scatter.\n\n***Beckon Earth.*** You create a small amount of earth or stone (up to 1 cubic foot) in an unoccupied space on the ground, or you cause loose dirt or stone to shift for a moment.\n\n***Beckon Fire.*** You create a flickering flame in your palm or on a surface you touch. This flame can be as large as a torch and lasts for 1 minute. It doesn't burn you, and you can dismiss it early as a free action.\n\n***Beckon Water.*** You create up to 1 pint of fresh water in an open container, or you cause a ripple on the surface of nearby water.","","",""],
["Ensnaring Strike",1,1,"1 bonus action","Self","Up to 1 minute","V","",1,0,[4],"The next time you hit a creature with a weapon attack before this spell ends, a writhing mass of thorny vines appears at the point of impact, and the target must succeed on a Strength saving throw or be restrained by the magical vines until the spell ends. A Large or larger creature has advantage on this saving throw. While restrained by this spell, the target takes 1d6 piercing damage at the start of each of its turns. A creature restrained by the vines or one that can touch the creature can use its action to make a Strength check against your spell save DC; on a success, the target is freed.","When you cast this spell using a spell slot of 2nd level or higher, the damage on each of the target's turns increases by 1d6 for each slot level above 1st.","Piercing","STR"],
["Hex",1,3,"1 bonus action","90 feet","Up to 1 hour","VSM","The petrified eye of a newt.",1,0,[6],"You place a curse on a creature that you can see within range. Until the spell ends, you deal an extra 1d6 necrotic damage to the target whenever you hit it with an attack. Also, choose one ability when you cast the spell. The target has disadvantage on ability checks made with the chosen ability.\n\nIf the target drops to 0 hit points before this spell ends, you can use a bonus action on a subsequent turn of yours to curse a new creature.\n\nA remove curse cast on the target ends this spell early.","When you cast this spell using a spell slot of 3rd or 4th level, you can maintain your concentration on the spell for up to 8 hours. When you use a spell slot of 5th level or higher, you can maintain your concentration on the spell for up to 24 hours.","Necrotic",""],
["Ice Knife",1,1,"1 action","60 feet","Instantaneous","SM","A drop of water or piece of ice.",0,0,[2, 5, 7],"You create a shard of ice and fling it at one creature within range. Make a ranged spell attack against the target. On a hit, the target takes 1d10 piercing damage. Hit or miss, the shard then explodes. The target and each creature within 5 feet of the point where the ice exploded must succeed on a Dexterity saving throw or take 2d6 cold damage.","When you cast this spell using a spell slot of 2nd level or higher, the cold damage increases by 1d6 for each slot level above 1st.","Cold","DEX"],
["Mind Spike",2,2,"1 action","60 feet","Up to 1 hour","S","",1,0,[5, 6, 7],"You drive a spike of psionic energy into the mind of one creature you can see within range. The target must make a Wisdom saving throw, taking 3d8 psychic damage on a failed save, or half as much damage on a successful one. On a failed save, you also always know the target's location until the spell ends, but only while the two of you are on the same plane of existence. While you have this knowledge, the target can't become hidden from you, and if it's invisible, it gains no benefit from that condition against you.","When you cast this spell using a spell slot of 3rd level or higher, the damage increases by 1d8 for each slot level above 2nd.","Psychic","WIS"],
["Phantasmal Force",2,5,"1 action","60 feet","Up to 1 minute","VSM","A bit of fleece.",1,0,[0, 5, 7],"You craft an illusion that takes root in the mind of a creature that you can see within range. The target must make an Intelligence saving throw. On a failed save, you create a phantasmal object, creature, or phenomenon no larger than a 10-foot cube that the target perceives for the spell's duration. The phantasm includes sound, temperature, and other stimuli, also evident only to the target.\n\nThe target can use its action to examine the phantasm with an Intelligence (Investigation) check against your spell save DC. If the check succeeds, the target realizes the phantasm is an illusion and the spell ends.\n\nWhile affected by the spell, the target treats the phantasm as if it were real. The target rationalizes any illogical outcomes from interacting with the phantasm. For example, a target attempting to walk across a phantasmal bridge that spans a chasm falls once it steps onto the bridge; if it survives, it still believes the bridge exists and invents another explanation for the fall.","","Psychic","INT"],
["Power Word Heal",9,3,"1 action","Touch","Instantaneous","V","",0,0,[0, 1],"A wave of healing energy washes over the creature you touch. The target regains all its hit points. If the creature has the charmed, frightened, paralyzed, or stunned condition, the condition ends. If the creature has the prone condition, it can use its reaction to stand up. This spell has no effect on undead or constructs.","","",""],
["Ray of Sickness",1,6,"1 action","60 feet","Instantaneous","VS","",0,0,[5, 7],"A ray of sickening greenish energy lashes out toward a creature within range. Make a ranged spell attack against the target. On a hit, the target takes 2d8 poison damage and must make a Constitution saving throw. On a failed save, it is also poisoned until the end of your next turn.","When you cast this spell using a spell slot of 2nd level or higher, the damage increases by 1d8 for each slot level above 1st.","Poison","CON"],
["Searing Smite",1,4,"1 bonus action","Self","Up to 1 minute","V","",1,0,[3, 4],"The next time you hit a creature with a melee weapon attack during this spell's duration, your weapon flares with white-hot intensity, and the attack deals an extra 1d6 fire damage to the target and causes the target to ignite in flames. At the start of each of its turns until the spell ends, the target must make a Constitution saving throw. On a failed save, it takes 1d6 fire damage. On a successful save, the spell ends. If the target or a creature within 5 feet of it uses an action to put out the flames, or if some other effect douses the flames, the spell ends.","When you cast this spell using a spell slot of 2nd level or higher, the initial extra fire damage increases by 1d6 for each slot level above 1st.","Fire","CON"],
["Sorcerous Burst",0,4,"1 action","120 feet","Instantaneous","VS","",0,0,[5],"You release a swirling surge of magic at a creature or object within range. Make a ranged spell attack against the target. On a hit, the target takes 1d8 damage. Choose the type of damage when you cast the spell: acid, cold, fire, lightning, poison, psychic, or thunder.\n\nIf you roll the highest number on a damage die, roll the die again and add the result to the damage total. This can cascade multiple times in succession.\n\nThis spell's damage increases by 1d8 when you reach 5th level (2d8), 11th level (3d8), and 17th level (4d8).","","",""],
["Starry Wisp",0,4,"1 action","60 feet","Instantaneous","VS","",0,0,[0, 2],"You launch a mote of light at one creature or object within range. Make a ranged spell attack against the target. On a hit, the target takes 1d8 radiant damage and emits a faint light until the start of your next turn. The light is visible to creatures within 60 feet of the target.\n\nThis spell's damage increases by 1d8 when you reach 5th level (2d8), 11th level (3d8), and 17th level (4d8).","","Radiant",""],
["Summon Dragon",5,1,"1 action","60 feet","Up to 1 hour","VSM","A gem worth at least 500gp.",1,0,[7],"You call forth a draconic spirit. It manifests in an unoccupied space that you can see within range. When you cast this spell, choose a type of dragon: chromatic, metallic, or gem. The spirit looks like a young dragon of the chosen type, which determines certain traits in its stat block. The dragon is friendly to you and your companions for the duration. In combat, the dragon shares your initiative count but takes its turn immediately after yours. It obeys your verbal commands (no action required by you). If you don't issue any, it takes the Dodge action and uses its movement to avoid danger.\n\nIf the dragon dies, the spell ends.","When you cast this spell using a spell slot of 6th level or higher, use the higher level wherever the spell's level appears in the stat block.","",""],
["Tsunami",8,1,"1 minute","Sight","Up to 6 rounds","V","",1,0,[1, 2],"A wall of water springs into existence at a point you choose within range. You can make the wall up to 300 feet long, 300 feet high, and 50 feet thick. The wall lasts for the spell's duration.\n\nWhen the wall appears, each creature within its area must make a Strength saving throw. On a failed save, a creature takes 6d10 bludgeoning damage, or half as much on a successful save.\n\nAt the start of each of your turns after the wall appears, the wall, along with any creatures in it, moves 50 feet away from you. Any Huge or smaller creature inside the wall or whose space the wall enters must make a Strength saving throw. On a failed save, the creature takes 5d10 bludgeoning damage. On a successful save, the creature takes half as much. A creature can take this damage only once per round. At the end of each turn, the wall's height is reduced by 50 feet and the damage dealt on subsequent rounds is reduced by 1d10. When the wall reaches 0 feet in height, the spell ends.","","Bludgeoning","STR"],
["Vitriolic Sphere",4,4,"1 action","150 feet","Instantaneous","VS","",0,0,[5, 7],"You point at a location within range, and a ball of acid streaks there and explodes in a 20-foot-radius sphere. Each creature in that area must make a Dexterity saving throw. On a failed save, a creature takes 10d4 acid damage and another 5d4 acid damage at the end of its next turn. On a successful save, a creature takes half the initial damage and no damage at the end of its next turn.","When you cast this spell using a spell slot of 5th level or higher, the initial damage increases by 2d4 for each slot level above 4th.","Acid","DEX"],
["Wish",9,1,"1 action","Self","Instantaneous","V","",0,0,[5, 7],"Wish is the mightiest spell a mortal creature can cast. By simply speaking aloud, you can alter the very foundations of reality in accord with your desires.\n\nThe basic use of this spell is to duplicate any other spell of 8th level or lower. You don't need to meet any requirements in that spell, including costly components. The spell simply takes effect.\n\nAlternatively, you can create one of the following effects of your choice:\n\n- You create one object of up to 25,000 gp in value that isn't a magic item. The object can be no more than 300 feet in any dimension, and it appears in an unoccupied space you can see on the ground.\n\n- You allow up to twenty creatures that you can see to regain all hit points, and you end all effects on them described in the greater restoration spell.\n\n- You grant up to ten creatures that you can see resistance to a damage type you choose.\n\n- You grant up to ten creatures you can see immunity to a single spell or other magical effect for 8 hours. For instance, you could make yourself and all your companions immune to a lich's life drain attack.\n\n- You undo a single recent event by forcing a reroll of any roll made within the last round (including your last turn). Reality reshapes itself to accommodate the new result. For example, a wish spell could undo an opponent's successful save, a foe's critical hit, or a friend's failed save. You can force the reroll to be made with advantage or disadvantage, and you can choose whether to use the reroll or the original roll.\n\nYou might be able to achieve something beyond the scope of the above examples. State your wish to the GM as precisely as possible. The GM has great latitude in ruling what occurs in such an instance; the greater the wish, the greater the likelihood that something goes wrong. This spell might simply fail, the effect you desire might only be partly achieved, or you might suffer some unforeseen consequence as a result of how you worded the wish. For example, wishing that a villain were dead might propel you forward in time to a period when that villain is no longer alive, effectively removing you from the game. Similarly, wishing for a legendary magic item or artifact might instantly transport you to the presence of the item's current owner.\n\nThe stress of casting this spell to produce any effect other than duplicating another spell weakens you. After enduring that stress, each time you cast a spell until you finish a long rest, you take 1d10 necrotic damage per level of that spell. This damage can't be reduced or prevented in any way. In addition, your Strength drops to 3, if it isn't 3 or lower already, for 2d4 days. For each of those days that you spend resting and doing nothing more than light activity, your remaining recovery time decreases by 2 days. Finally, there is a 33 percent chance that you are unable to cast wish ever again if you suffer this stress.","","",""]
];

function unpackSpells5e() {
  return SPELLDATA_5E.map((r, i) => ({
    uid: '5e:' + i,
    system: '5e',
    name: r[0],
    level: r[1],
    school: r[2] >= 0 ? SPELL_SCHOOLS_5E[r[2]] : '',
    castingTime: r[3],
    range: r[4],
    duration: r[5],
    components: r[6],
    material: r[7],
    concentration: !!r[8],
    ritual: !!r[9],
    classes: r[10].map(x => SPELL_CLASSES_5E[x]),
    text: r[11],
    higher: r[12],
    damageType: r[13],
    save: r[14],
    source: 'SRD 5.1'
  }));
}


